/* 令和2年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r02.committeeSessions.push(...[{"id":"r02-20201013-4","meetingId":"r02-c-settlement","date":"2020年10月13日","dateIso":"2020-10-13","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時３４分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を173件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和元年度品川区一般会計歳入歳出決算","agenda":"令和元年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"芹澤委員","kind":"質問・要望","question":"私からは、３６７ページ、学校ＩＣＴ推進経費、あとは３５１ページ、８３運動経費についてお伺いいたします。その前に、ページが見つからないので、所管がずれるかもしれないので、その場合、またおっしゃっていただきたいと思うのですが、品川区は宮古市と災害時相互援助協定を結んでおりますけれども、これまで宮古市と品川区の児童が交流を持つ２泊３日のツアーをやってきたと伺っています。","respondent":"有馬庶務課長、工藤指導課長","answer":"この事業は、青少年育成活動、親子体験交流事業ということで実施していると捉えております。毎年親子１０組２０人程度は行っているのではないかということです。今年度はコロナの関係で行けないという情報を聞いております。タブレットの活用での持ち帰りのところですが、配備いたしますタブレットにつきましては、携帯電話と同じ通信ということで、学校の中での活用においても、もちろん校内・校外、また家庭においてもインターネットにつながる環境ですので。","voiceIndex":6,"id":"exchange-001"},{"speaker":"芹澤委員","kind":"確認","question":"宮古市のほうは、ほかの事業で海外研修といったものもあるかと思います。それで、タブレットはもう一度確認したいのですが、そうすると、持ち帰りが前提になるということでよろしいのでしょうか。それとも、まだ学校での判断もしくは保護者の判断で、それぞれ持ち帰っていただければというような方向性なのでしょうか。","respondent":"工藤指導課長","answer":"タブレットにつきましては、持ち帰りが前提でということで検討を進めているところです。","voiceIndex":9,"id":"exchange-002"},{"speaker":"芹澤委員","kind":"提案","question":"続けて８３運動についてお伺いいたします。８３運動については、予算特別委員会の中で何度か提案をさせていただきました。コロナ禍ということでありますので、大きな進捗というのはないのかと理解していますけれども、８３運動で今年度進んだということが何かあればお聞かせください。","respondent":"有馬庶務課長","answer":"いろいろとご提案も頂きました、８３運動の日を設定するとか、８３運動週間というのは、８３運動が、８月３日が夏休みであるということや、いきなり週間を設定するのは難しいということで、冒頭申し上げましたけれど、ポスターということの話が出ましたが。","voiceIndex":11,"id":"exchange-003"},{"speaker":"芹澤委員","kind":"質問","question":"特にまたコロナの中で、不審者情報などが相次ぐ中で、８３運動の事業というのが、さらに大きな意義を持っていくと理解しています。それを少しずつ改善していきたいというような発言があって、今、チラシをお配りされるということですので、これまでのＰＴＡに対しての周知とは、また、より１つギアを上げて周知されるというような理解でよろしいのでしょうか。","respondent":"有馬庶務課長","answer":"今までは８３運動推進委員会から、啓発グッズでこんなものを作ってほしいというようなことで、それに対応して、ではそうしましょうということで、それをお配りしていたというような形での、本当の側面支援という形でしたけれども、一歩踏み込んで。","voiceIndex":13,"id":"exchange-004"},{"speaker":"芹澤委員","kind":"意見","question":"運動に参加する人数をどんどん増やしていくというのは、なかなか難しいことなのかなとも思うのですが、特に８３運動というのは、非常に大きな負担をかけるようなものでもなくて、非常に分かりやすく意義のあるものだと思いますので、ぜひ引き続き、これは積極的に取り組んでいただければと思います。何かあればご意見をお聞かせください。","respondent":"有馬庶務課長","answer":"コロナ禍でいろいろと行事ができなかったところもありますので、一応、心のケアではないですけれど、何か思い出づくりということに取り組んでいこうということで考えているところです。","voiceIndex":15,"id":"exchange-005"},{"speaker":"松澤委員","kind":"確認","question":"私からは、３６７ページ、学校ＩＣＴ活用経費、３６９ページ、学校システム運営費についてお伺いいたします。私自体、教育ＩＣＴが詳しく分からないので、確認しながらの質問になることをお許しください。そこで、品川区におけるＩＣＴ環境整備は現在どのように進んでいるのかと、推進校で全員配付しているタブレットが壊れてしまった場合の補償などがどのようになっているのか、教えてください。","respondent":"篠田学務課長","answer":"機械が壊れてしまった場合ですけれども、区から貸与している機械ですので、例えば壊れてしまったということでお預かりして、その間、代替機をお渡ししてお使いいただくというような形で対応しています。","voiceIndex":18,"id":"exchange-006"},{"speaker":"松澤委員","kind":"質問","question":"代替機を渡すことは、壊した家庭が負担するということはないということでよろしいでしょうか。","respondent":"篠田学務課長","answer":"例えば故意で、明らかにいたずらをして壊してしまったなどということがなければ、そういった確認が取れなければ、基本的には公費で全て対応しています。","voiceIndex":20,"id":"exchange-007"},{"speaker":"松澤委員","kind":"質問","question":"ただいま、無線ＬＡＮを全て配置という話がありましたけれども、国が目指しているのは、教科指導における教育用のコンピュータ導入というのがあります。そこでお聞きしたいのが、パソコンを導入する学校もある中、タブレットを品川区が選んだ理由と、タブレットにはセルラーモデルとＷｉ－Ｆｉモデルというのがあります。通信料、交信料がかさんでしまう。そこでお聞きいたします。この２点をお願いします。","respondent":"篠田学務課長","answer":"タブレットを選んだ理由ですけれども、パソコン等ですと、１年生等小さいお子さん方ですと、取扱いの関係で、やはりタブレットのほうがなじみやすいだろうということで、またこれから先の時代を考えたときに。","voiceIndex":22,"id":"exchange-008"},{"speaker":"松澤委員","kind":"意見","question":"分かりました。ＬＴＥが悪いなどではないのですけれども、セルラーモデルと比べてＷｉ－Ｆｉモデルというのは、たしか調べたところ、２万円ぐらい安いのです。こういった図書館でのＷｉ－Ｆｉの活用などを私は考えましたが、話し合いの場でどのような議論がされたのかというのが１点。そして、家庭でのインターネット環境についてのアンケートの結果が分かりましたらお願いいたします。","respondent":"篠田学務課長","answer":"したがいまして、今回の契約におきましても、一般的な使用料から考えると、かなり割安な回線の使用料となってきているところですので、Ｗｉ－Ｆｉモデルですと、例えばご自宅に持ち帰ったときに、環境がなければ別にまたポケットルーターなどの貸出しが必要になったり。","voiceIndex":24,"id":"exchange-009"},{"speaker":"松澤委員","kind":"質問・要望","question":"全国どこでも、どこの学校にいても、最新の質の高い学習環境を利用できる仕組みの整備が求められております。品川区でも、この教育クラウドを活用していくと思いますが、グーグルやマイクロソフト、最近ではＧｏｏｇｌｅ Ｃｈｒｏｍｅが活用されていると聞いておりますが、例えばＣｈｒｏｍｅｂｏｏｋとまなびポケットを組み合わせるなど、品川区での今後の予定などがありましたら教えてください。","respondent":"篠田学務課長","answer":"今お話のあったような基盤の関係につきましては、当初はなくても全体の管理ができるのかということで考えていたところではあるのですけれども、やはり様々共有フォルダの作成など、いろいろと考えていくと、何らか対応していくことが必要だろうということで、現在。","voiceIndex":28,"id":"exchange-010"},{"speaker":"松澤委員","kind":"質問・要望","question":"ぜひ、子どもたちにとって何が一番いいのかを考えて活用していただきたいと要望いたします。これは家庭の問題だとは思うのですけれども、学校側から何かそういうものに向けて取り組む課題やお考えというのはありますでしょうか。","respondent":"工藤指導課長","answer":"今後、宿題等を学校、教員から出す場合には、ｅライブラリアドバンスを活用することで、宿題はそれによって行う。そういったことで、家庭学習・自学自習を習慣化していくことにも取り組むというところで検討を進めているところです。","voiceIndex":30,"id":"exchange-011"},{"speaker":"松澤委員","kind":"質問","question":"宿題をタブレットでやるようになれば、子どももやはり開かなければいけないという部分で、大変いい取組みだと思われます。最近では、情報化統括責任者であるＣＩＯというのですか、最高情報責任者を置く民間企業が増えていると聞いております。そこで、雇用や勤務形態は様々ですが、品川区におけるＩＣＴ支援員の現状と今後の取組みについて教えてください。","respondent":"篠田学務課長","answer":"人材の関係があるものですから、なかなかいきなりすぐに増やすというのは、難しい部分はあろうかとは思うのですけれども、できるだけ厚みを持った形での対応をしていきたいということと、また来年度においても、さらにそれを一層継続して。","voiceIndex":32,"id":"exchange-012"},{"speaker":"松澤委員","kind":"質問","question":"続きまして、学校システム運営費からお聞きいたします。そうすると、私は友達が周りにいないと連絡帳を預けられないなどといった声も聞いたことがありますので、電話で済む話なのですけれども、そういった部分で困っている、要はＳＮＳでやってほしいです。欠席届をオンラインでやり取りするとか、学校プリントのデジタル化を含めた現場の先生の負担軽減等の考え方も含めてご見解をお聞かせください。","respondent":"工藤指導課長","answer":"そういったことも含めて、研究も含めながら、今、検討を進めているところではあります。ですので、保護者の方のニーズも踏まえながら、また学校の教員の働き方改革という観点からも、効率よく連絡がしっかりとできるようなところを検討してまいりたいと考えています。","voiceIndex":34,"id":"exchange-013"},{"speaker":"松澤委員","kind":"質問・要望","question":"確かに、いきなりデジタル化で全部デジタルというのは、私もどうなのかとは正直思っております。紙と一緒に共存していくという考え方も確かにすばらしいと考えています。アプリや支援ツールというものを活用して、ＩＣＴ教育に対する負担を軽減するためにも改善していただきたいと考えますが、先ほどとかぶってしまいますけれども、ご見解をお聞かせください。","respondent":"工藤指導課長","answer":"教員については、採点を自動機能で行いますので、子どもたちの進捗状況をすぐさま確認することもできますので、そういった意味で業務改善、また授業改善に資することができるとも考えておりますので、そういった活用についても含めて様々検討していきたいと考えています。","voiceIndex":36,"id":"exchange-014"},{"speaker":"松澤委員","kind":"質問・要望","question":"情報化がどんどん進んでいく中で、ご苦労されている教育委員会の皆さんと先生たち、特に先生たちが、コロナ禍というのもありまして、いろいろな負担を強いられていると思います。そういった方々をしっかりと把握してフォローする、そういった環境の整備を要望して質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-015"},{"speaker":"新妻委員","kind":"質問・要望","question":"３６１ページ、マイスクール運営費、３６７ページ、学校ＩＣＴ活用経費から関連してお伺いいたします。昨日の今日でありますので、まだ詳細はこれからかと思いますが、昨日１日、オンライン授業がどのように行われ、そしてまた、先生の様子、生徒の様子、またお声がありましたらお聞かせいただきたいと思います。１日の授業が、全てオンラインが活用されたのかということもお伺いいたします。","respondent":"篠田学務課長","answer":"本日からは本格的に授業で取り組むと聞いていますので、まだ詳細を聞き及んではいないのですけれども、今日から活用されているです。","voiceIndex":40,"id":"exchange-016"},{"speaker":"新妻委員","kind":"確認","question":"そして９月には一斉下校後の訓練ということで、保護者を交えてオンラインでの安否確認をするということで、６月、７月、９月と、このように取り組んできた成果が、今回のオンライン授業に活かされてくるのかと考えています。今回この学校がオンライン授業を展開するにあたっては、これらの準備が活かされてきていると認識するのですが、区の見解を伺います。","respondent":"工藤指導課長","answer":"委員にご指摘いただきましたように、お話しいただいたところは、早くから計画的にＺｏｏｍを活用するというところを進めていたという事例であると私どもも認識しています。","voiceIndex":42,"id":"exchange-017"},{"speaker":"新妻委員","kind":"質問・要望","question":"ＩＣＴと言うと得手不得手があったりというところもありますが、地域の力というのはすごいということも実感しておりますので、これからも様々活用していただきながら、強力に進めていただきたいと思います。改めて、マイスクールに通いたい人は、どういう段取りややり取りがあって、マイスクールに入室というのでしょうか、マイスクールに入っていくのかという流れをお知らせいただきたいと思います。","respondent":"矢部教育総合支援センター長","answer":"所管は教育総合支援センターですので、そちらのＨＥＡＲＴＳを中心とした指導主事にも相談して、これからの道筋について考えてまいります。本当に適応指導教室がよろしいのか、学校の中で対応できるのか、その辺の検討からまず始めます。","voiceIndex":44,"id":"exchange-018"},{"speaker":"新妻委員","kind":"確認","question":"前期の文教委員会の所管事務調査でひきこもりを取り上げた際に、教育委員会には、マイスクールの現状、人数等々も含めて確認させていただきました。３学期になると、空きがなかなか少ないというようなことも伺いましたけれども、現状、この３つのマイスクールに、どれだけの人数が通っていて、また待機者というのでしょうか、見学したいという人がどれだけいるのかということをお知らせください。","respondent":"矢部教育総合支援センター長","answer":"マイスクール五反田、マイスクール浜川につきましては、それぞれ現状で、昨年度末で、五反田のほうが２６名、浜川のほうが十数名という報告を受けてあります。","voiceIndex":46,"id":"exchange-019"},{"speaker":"新妻委員","kind":"質問","question":"マイスクール八潮はもう定員がいっぱいであって見学者も数人いる。五反田と浜川に関しては、少しまだ余裕があるという状況でよろしいのでしょうか。だけれども、見学を申し込んではいるものの、空きがないということで、年度初めの来年４月まで待ってほしいと言われたと。今後のマイスクールの在り方やニーズ等を踏まえて、マイスクールの拡充等も必要かと思いますが、区の見解をお伺いいたします。","respondent":"矢部教育総合支援センター長","answer":"小学生につきましては、委員ご指摘のとおり、八潮で対応しています。先ほどもお話に出ましたが、人口が増加しているというところで、ニーズの強さ、大きさは感じております。今後ともこの３教室の在り方について前向きに検討してまいりたいと考えております。","voiceIndex":48,"id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"３５５ページ、生徒指導対策等経費に関連して、中学校の理不尽な校則についてお伺いしたいと思います。質疑後、中学生の保護者から、見直しを求める質問への共感、さらに、理不尽な校則の実態など、様々な声が届きました。今回は特に髪形に絞って伺いたいと思います。校長会について、誰がいつどんなお話を何度もしているのか、伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"それを踏まえまして、見直しのことですが、昨年も含めてこれまでも、校長会で教育長より見直しの指導はございました。現在、生活指導主任会でも話題に挙げて、見直しの検討をしています。","voiceIndex":52,"id":"exchange-021"},{"speaker":"中塚委員","kind":"質問","question":"私が伺った中学１年生と中学３年生の生徒は、生徒同士の中でも、「ツーブロック禁止っておかしいよね」とか、「サイドを伸ばすのはおしゃれだから禁止って納得できない」など、生徒の中で様々話題になっていることが分かりました。生徒会でこうした意見を提出した学校はあるのか、伺いたいと思います。先ほども伺いましたが、教員の中ではどんな議論が実際にされているのかも伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"生活指導の中ではどのようなお話があるかというご質問ですが、先般でも私のほうで聞いたところは、校則の目的、小学校も含めてですけれど、何でここにこうあるのか、また共通理解をどのようにするべきかというような議論が交わされております。","voiceIndex":54,"id":"exchange-022"},{"speaker":"中塚委員","kind":"提案","question":"ツーブロックという具体的ではないが、見直しのお話をしているということですが、学校の現場ではすごく具体的に禁止事項が並べられていますので、具体的に提案をすることが必要ではないかと思うのです。お伺いしますが、生徒の髪形禁止の不満の声は教育委員会にどのように届いているのか、どんな声があるのか伺いたいと思います。こうした姿勢が重要だと思いますけれども、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"どちらにしましても、地域で今までの時代背景や子どもたちの様子を見て決めてきたことですので、そこはこれからも見直しのほうの働きかけを進めてまいりたいと考えております。","voiceIndex":56,"id":"exchange-023"},{"speaker":"中塚委員","kind":"質問","question":"見直しの働きかけは歓迎したいと思いますけれども、質問したのは、生徒の髪形についての不満の声は区教育委員会に届いているのか、どんな声があるのか、改めて伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"失礼いたしました。児童・生徒の髪形についての意見については、私どもには聞こえてきておりません。","voiceIndex":58,"id":"exchange-024"},{"speaker":"中塚委員","kind":"質問","question":"教育委員会に届いていないというのは、現場の声が届いていないと思います。生徒の声を吸い上げ、区教育委員会にもその声を受け止めてほしいと思いますが、いかがでしょうか。実際に、保護者からも、納得がいかなくて教育委員会に電話をするということもよく伺います。声をつかんでいないというのは、あまりにも、生徒の声、保護者の声を軽視していると思いますが、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"真摯に受け止めてあります。生活指導主任会を２か月に１度ほど行いますので、そこで、今回の校則の見直しの話題の際にも、児童・生徒からどのような声が上がったかというのは、その中では協議されていることと考えております。","voiceIndex":60,"id":"exchange-025"},{"speaker":"中塚委員","kind":"提案","question":"本会議の質問の後、複数の保護者からお話を伺いました。それで、「従わないと内申点に響きますよ」と言ったそうです。ポニーテール禁止というのは本当ですか。この方は今、高校生になったので、今の中学校がどうかまでは私は確認しておりませんけれども、ポニーテール禁止について教育委員会は知っているのか、なぜ禁止なのか。私はおかしいと思いますけれども、いかがでしょうか。","respondent":"矢部教育総合支援センター長、工藤指導課長","answer":"繰り返しになりますけれども、これまでの決まりの設定にあたっては、各学校が吟味して作成していると考えておりますので、委員がおっしゃるとおり、見直しはまだこれからも続けるよう働きかけてまいります。ですから、そういったことを把握して、学校は適切に指導していると思いますが、先ほど教育総合支援センター長からもありましたとおり、いわゆる内申に関わるであるなどというのは正さなければいけないと思いますけれども。","voiceIndex":62,"id":"exchange-026"},{"speaker":"中塚委員","kind":"質問","question":"私もこの質問をするにあたって、ポニーテールというのがそもそもどういう髪形なのか聞いたところではあるのですけれども、結ぶ位置が上のほうにあるということでいいのですね。先ほどの説明だと、結ぶ位置が上だと黒板が見えなくなる。そんな理由で、主に女子生徒が自分の好きな髪形を禁止するというのは、理不尽だと思いますけれども、いかがでしょうか。","respondent":"工藤指導課長","answer":"そういった指導が理不尽ではないかというご指摘ですが、やはり指導というのは前後関係、教員と生徒の関係ももちろんありますし、また校則を含めたところは、当然、今、見直しを進めているところではありますけれども、そういったものが。","voiceIndex":65,"id":"exchange-027"},{"speaker":"中塚委員","kind":"質問・要望","question":"どういう話の中で、どういう生徒との関係の中で、そういう指導が入ったのか、前後関係があるのは分かります。そして、大人が決めた校則ですから、自ら、やはりこれは時代に合わないと思うものは、正していくことも必要だと思います。この時期を、禁止、禁止と縛るのではなくて、その生徒を個人として尊重し、主体性にこそ向き合う、そういう指導をしていただきたいと思いますが、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"どれも重要なことだと考えております。ただ、学校の中では、子どもたちの個性を光らせる場面は多々ありまして、いろいろなところで私たちは輝く場面を見ます。そこの場面で十分活躍させて褒めていきたいと考えております。","voiceIndex":67,"id":"exchange-028"},{"speaker":"中塚委員","kind":"質問・要望","question":"よく校則の話をすると、学校では個性を出すと集団生活ができなくなる、こういう理屈を持ち出す人が結構いるのです。今後とも、生徒や保護者、また現場の教員の声に耳を傾けていただいて、学校教育を進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-029"},{"speaker":"筒井委員","kind":"確認","question":"私からは、３４８ページ、教育費全般から、コロナウイルスによる影響と少人数教育について、３６４ページ、図書館費についてお伺いいたします。かなり緊張感を強いることにもなろうと思いますけれども、確認としまして、品川区でもこのような形で給食を行っているのか、現状をお知らせください。行っていたとすれば、それはいつから始められたのでしょうか。","respondent":"篠田学務課長","answer":"これを始めたのは、学校が再開されました６月から分散登校を始め、そのときからそういった形で始めて、現在も継続しています。","voiceIndex":71,"id":"exchange-030"},{"speaker":"筒井委員","kind":"質問","question":"報道でも取り上げられておりますけれども、本区でも、こうした、コロナウイルスによって子どもが受けたストレス、心のダメージがあるという実感や事例というのはあるのでしょうか。同様に、子どもに対応する教員も、コロナ感染防止対策に気を遣うのと相まって、ストレスや心のダメージが相当あるかと思いますけれども、そうした実感や事例はありますでしょうか。","respondent":"矢部教育総合支援センター長、工藤指導課長","answer":"その中では、やはり学習に対する不安と、もう一つ、クラスが変わったところがありますので、お友達との関係の不安は出てまいりました。そういった中では、教員が１人で抱え込むようなことはなく、やはりチームとして学校教育を行っていくということが必要であるということは、お話をしながら進めているところではあります。","voiceIndex":73,"id":"exchange-031"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひ教員の方にも気を向けて、ケアをしていただきたいと思います。子どもも当然そうですけれども、学習面や友達との関係で悩みがあるということですが、そうした子どもたちと教員の心のケアはどうされていくのか。先ほどご答弁がありましたとおり、生徒たちに対しては思い出づくりをやっていくというようなことをおっしゃられましたけれども、具体的にそれはどのような形でやっていくのでしょうか。","respondent":"矢部教育総合支援センター長","answer":"もともと卒業遠足があったところは、そちらの卒業遠足をまた３学期にやろうと考えているところもありますし、もう既に移動教室が中止になったことで、６年生や５年生に、それぞれ自分たちが考えた活動をやろうということで。","voiceIndex":76,"id":"exchange-032"},{"speaker":"筒井委員","kind":"質問","question":"そうした遠足やレクリエーション、活動などといったことで、子どもたちに対しては心のケアをやられていくということなのですけれども、そういった活動をさせる、思い出づくりをさせるといったこと以外で、子どもたちに対してもう少し丁寧に聞き取るとか寄り添うとか、そういった活動というのはないのでしょうか。","respondent":"矢部教育総合支援センター長、工藤指導課長","answer":"学期に１回は生活アンケートを取ってありますので、そちらでお子さんの様子を取り、５年生・７年生については東京都のスクールカウンセラーによる全員面接も行ってあります。教員の心のケアにつきましては、先ほど申し上げましたが、不調が見られたりした場合には、もちろん必要に応じて産業医面談につなぐなど、やはり教職員のケアについても引き続き注意深く見ながら進めていきたいと考えています。","voiceIndex":78,"id":"exchange-033"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。続けて少人数学級のほうをお伺いいたしますけれども、先月、突然、文部科学省が、３０人学級に１０年をかけて段階的に移行するというような方向性を発表しました。東京都品川区の、今、言ったとおり、物理的・場所的制約といった地域事情も加味されるべきかと思うのですけれども、本区としては、文部科学省が今回出した方向性に対し、どう対応されていくのでしょうか。","respondent":"篠田学務課長","answer":"ただ、こちらのほうも、文部科学省も、今、委員からのご指摘があったとおり、一定の期間を置いてというような形での、まだ考え方が示されているだけですので、その辺のスケジュールが固まってくれば、それに沿った対応を考えていく必要があるだろうとは受け止めているところです。","voiceIndex":81,"id":"exchange-034"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。ただ、どうしても方向性が少人数学級になっていくのかと思いますので、これは注意深く見ていただいて、それに対しての準備はしていくべきかと思いますので、しっかりと対応のほどよろしくお願いします。続いて図書館のほうに移りますけれども、今、書籍消毒器というのが区内の図書館に幾つかあると思いますけれども、各図書館の設置台数とメーカーと１台当たりの値段を教えてください。","respondent":"横山品川図書館長","answer":"メーカーについては、図書館流通センターのＬＩＶＡという、４冊を除菌できる機械が、価格８０万円から９０万円で入っているのと、あと２、３冊に対応するＣＯＣＯＣＨＩという機種が、５０万円から７０万円台で入ってあります。","voiceIndex":83,"id":"exchange-035"},{"speaker":"筒井委員","kind":"質問","question":"もともと図書館の本というのはどうしても不特定多数の人が触れるので、衛生面で消毒の必要性が高まっているかと思いますけれども、今回のコロナウイルスで消毒の必要性はさらに高まっていると思いますので、ぜひそうした書籍消毒器の対応というのもお願いしたいと思いますが、どうしても今後もウィズコロナということ、コロナウイルス感染防止ということを考えますと、そうした機械での対応というのは。","respondent":"横山品川図書館長","answer":"一方で、地域資料、品川区にしかない資料については、これからデジタル化を進めていこうという形で、電子書籍の導入とともに地域資料のデジタル化というものを併せて導入しようという検討を今進めているところですので、状況を見ながら対応していこうと思っているところです。","voiceIndex":85,"id":"exchange-036"},{"speaker":"筒井委員","kind":"質問","question":"コロナウイルス感染防止、ウィズコロナという時代の対応というのは必要だと思いますので、今、研究は進められているということですけれども、引き続き電子図書館の研究、そして、図書館を電子化しますと国から急に言われたときに、いつでもすぐに対応できるような準備をぜひよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":87,"id":"exchange-037"},{"speaker":"田中委員","kind":"質問・要望","question":"学校給食放射性物質検査について伺います。学校給食でもそうなのかと区教育委員会へ問い合わせたところ、学校は継続と確認ができました。これらのことからも、今後さらに放射性物質検査の必要性が求められます。質問します。給食の安全を確認するためにも継続して検査すること、そして放射性物質が移行しやすい食材の傾向が見えてきていることから、単品検査への切替えを再度求めますが、見解を伺います。","respondent":"篠田学務課長","answer":"これまでもご答弁申し上げているとおり、放射性物質の検査につきましては、日々、様々なケースの状況等、それから当然、経費もかかりますし労力もかかるという中で、そこのバランスを考えながら、実施にあたっては考えていくということでお話を申し上げまして、これまでも。","voiceIndex":89,"id":"exchange-038"},{"speaker":"田中委員","kind":"質問・要望","question":"子どもの生きる、発達するという育ちの権利を保障する観点からも、これ以上縮小を進めることのないよう強く要望します。デートＤＶ、性教育について伺います。保健体育の教科書を確認したところ、デートＤＶについてほんの１文触れていましたが、デートＤＶについて理解を深める授業が行われているのか、改めて伺います。","respondent":"矢部教育総合支援センター長","answer":"デートＤＶに限らず、子どもたちの人権を守るという点で、市民科をはじめ各社会科でも、教科を中心に指導してきたところです。各学校におきましては、セーフティ教室などで、子どもたちの、自分で身を守る被害防止に努めているところです。","voiceIndex":91,"id":"exchange-039"},{"speaker":"田中委員","kind":"質問・要望","question":"子どもがデートＤＶにある状態を通常だと誤って認識してしまわぬよう、学ぶ機会が求められます。冊子については、子どもの手の届くところに置き、講演についても周知するなど連携を図っていただきたいと要望します。それで見解を伺いますが、次にいきます。月経について伺います。その結果、不妊をはじめとした気づきにくい様々な病気の早期発見にもつながると考えますが、区教育委員会の見解を伺います。","respondent":"矢部教育総合支援センター長","answer":"ただし、お子さんの様子につきましては、養護教諭を含め、もしも必要であれば学校医とも相談して、丁寧に、プライバシーを守って対応してまいりたいと考えております。デートＤＶについてです。","voiceIndex":93,"id":"exchange-040"},{"speaker":"田中委員","kind":"質問・要望","question":"ぜひ連携を取って進めていただきたいと要望いたします。養護教諭やＰＴＡ、保健センターなどと協力して、子どもが体について学ぶ機会の確保を求めたいと要望しますが、見解を伺います。次に、体罰等の実態調査について伺います。そして、都の改善には時間がかかると思うので、区内での体罰・暴力の早期発見・救出のために、都の改善を待たずに、区としての調査を早急に行うことを求めますが、見解を伺います。","respondent":"矢部教育総合支援センター長、工藤指導課長","answer":"初めに、月経に関わる対応のお話ですが、私たちとしましては、子どもたちは様々な悩みを抱えてありますので、担任を中心に子どもたちに丁寧に向き合って対応してまいりたいと考えております。生徒アンケートの期間ですけれども、東京都教育委員会が行っています調査につきましては、実施時期が１２月ということで、生徒向けには１２月という案内をしています。","voiceIndex":95,"id":"exchange-041"},{"speaker":"田中委員","kind":"質問・要望","question":"でしたら、非該当にはならないと思います。中・高生の体罰の質問用紙についての期間については、小学生の質問用紙を確認すると、期間というのは書かれていないのです。だから子どもたちは書けるのです。改善を都にも求めてほしいですし、区としても、そこを削除して調査を行ってほしいと思います。区教育委員会としての趣旨説明が必要だと考えますが、見解を伺います。","respondent":"工藤指導課長","answer":"やはりご指摘も頂いてありますが、体罰あるいは不適切な指導をなくすということが非常に重要なことであると認識していますし、例えば本調査の趣旨も含めて、そういったことが、学校、教員。","voiceIndex":98,"id":"exchange-042"},{"speaker":"田中委員","kind":"質問・要望","question":"様式についてです。東京都の調査様式というのは分かるのですけれども、区としてすぐに直せると思うので求めます。そして次に、新型コロナウイルス感染症関係について伺います。民生費でも伺いましたが、新型コロナウイルス感染症の影響から、来年度、小・中・高等学校に入学する子どもたちは、例年とは違い、準備が間に合わないまま進学します。","respondent":"矢部教育総合支援センター長","answer":"中学校に向けましても、既に６年生は今、コロナ禍だからこそできることでリーダーシップを取っておりますので、そのようなことで、また中学校のほうも対応して、そのような状況を踏まえて丁寧に対応してまいりたいと考えております。","voiceIndex":100,"id":"exchange-043"},{"speaker":"田中委員","kind":"質問・要望","question":"小学生になった子どもたちは、例年に比べてできることが少ないかもしれませんが、それを受け止めてほしいと要望します。区教育委員会と学校だけでなく、幼稚園や保育園などの先生たちと情報共有を行い、子どもたちを迎える体制を整えてほしいと要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":102,"id":"exchange-044"},{"speaker":"松本委員","kind":"質問・要望","question":"本日は、３６７ページ、学校ＩＣＴ活用経費、３５４ページ、区教員経費、あるいは３５５ページ、教職員人材育成経費について伺います。ですので、タブレットとペーパーレスの関係の中でも、まずはこれまで手配りされていたプリントをペーパーレスの方向で進めていくということが、学校現場でも必要ではないかと思いますが、ご見解を伺います。","respondent":"工藤指導課長","answer":"ただ、やはりそれは、今後のタブレット配備も併せながら、大事な視点であると認識していますので、そういった意味では検討してまいりたいと考えています。","voiceIndex":104,"id":"exchange-045"},{"speaker":"松本委員","kind":"質問","question":"教職員のところはまた後ほどお伺いできればと思うのですけれども、児童・生徒に対する紙の配布というところで、まずはプリント等のペーパーレス化を進めるというのは大事かと思いつつ、さらに一歩進めて、例えばテストの結果や通知表は、新型コロナの関係で終業式には通知表を配れませんでしたというふうな報道なども、これは品川区ではありませんけれども結構あるところでございまして、これも。","respondent":"工藤指導課長","answer":"もちろん個人情報の保護というのが、タブレット内、またそういった情報の管理というのは非常に重要ですので、そういったことが可能かどうか、またはそれが適しているのかどうかも含めて、検討課題であるという認識ではありますので、そういったことも踏まえて。","voiceIndex":106,"id":"exchange-046"},{"speaker":"松本委員","kind":"質問・要望","question":"少しお伺いしたいのですけれども、１人１台、ＬＴＥ型タブレットが配付されて、児童・生徒がデジタル教材で学べるようになった後、もうかなり学べるようになった後に、保護者の中から、希望者には、デジタル教材を学校側が学校の経費で負担して印刷して配付すべきだ、全員ではなくて希望者には配付するべきだという話が出てきた場合。","respondent":"工藤指導課長","answer":"そういったメリット・デメリットも含めながら、何が有効かというのは検討する必要があるとも思いますし、そういった活用を図っていく範囲では、様々ご要望はあろうかと思いますが、取組みの趣旨というのをご理解いただくということも踏まえながら進めたいと考えています。","voiceIndex":108,"id":"exchange-047"},{"speaker":"松本委員","kind":"質問・要望","question":"続きまして教員側ですけれども、先ほど、職員会議のペーパーレス化に取り組んでいただいている学校もあるということで、これはぜひ進めていただきたいと思いますが、ほかの学校での取組みや、推進していく流れというところもお願いできればと思います。","respondent":"工藤指導課長","answer":"各学校で行っていくものに関しましては、やはりあらかじめ資料等、読み込んでいただきたいものというのは事前に配付する。それを、例えば現在の機能で言えば（イントラネットの）回覧機能を使って、既に送っておくということで取り組んでいる学校もあると存じています。","voiceIndex":110,"id":"exchange-048"},{"speaker":"松本委員","kind":"質問","question":"その中でまたお伺いしたいのですけれども、一部の教員が、自分が雇用されたときにはタブレットなどなかった。タブレットを使うことは働く上で前提とされていなかったと述べて、紙での授業しかやらない、あるいは職員会議も、希望者には資料を学校側できちんと印刷して紙で配るべきだと主張した場合に、学校側としてはどのように対応するでしょうか。","respondent":"工藤指導課長","answer":"もう今、現状は、タブレットを活用することで授業の質も高められるという視点で授業改善に資していくというところが、教員に課されている使命であるというところは、教員に対しては指導してまいりたいと思いますし、そのように取り組んでいきたいと考えています。","voiceIndex":112,"id":"exchange-049"},{"speaker":"松本委員","kind":"質問","question":"時代に合わせて、やはり職場環境、働き方も変わっていくものだと思います。タブレットが配付されて、ペーパーレスでやっていきましょうという流れの中で、希望者には資料を紙で配付するべきだと、資料を作成する側もそういったことがあると、教員にも負担となると考えています。停滞させている人たちに対しては強く怒りを持っているということを改めて申し上げまして、私の質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":114,"id":"exchange-050"},{"speaker":"西村委員","kind":"質問","question":"３５９ページ、学校と家庭の連携推進事業と、３６１ページ、マイスクール運営費、関連しまして、不登校、ひきこもりについて伺ってまいります。ページが見当たりませんでしたが、時間が余りましたら、まもるっちについて伺います。先ほどのご答弁で、マイスクールそれぞれの利用状況の報告がございました。この人数は多いのか少ないのか。お知らせください。","respondent":"矢部教育総合支援センター長","answer":"平成３０年の不登校の出現率につきましては０.５５％、中学校につきましては３.７１％と、例年、徐々に増加傾向にあります。","voiceIndex":116,"id":"exchange-051"},{"speaker":"西村委員","kind":"質問・要望","question":"不登校児童・生徒への支援の在り方について伺ってまいりたいと思います。現在、不登校児は、全国小・中学校で合わせて１７万人と言われます。把握が難しいとは理解していますが、マイスクールやフリースクールに行かない、行けない児童・生徒の推計値はどのようになっているでしょうか。ケアしている配慮があれば、さらに取り組んでいただきたいと思いますので、お聞かせください。","respondent":"矢部教育総合支援センター長","answer":"実際には個別対応になりまして、不登校の理由はみんなそれぞれ個別ですので、担任を中心に学校で、体制をつくりながら、家庭と連携を取って連絡しています。こちらはＨＥＡＲＴＳもつながっている事例もありますので、そちらで訪問して話をしたりということまでは聞いてあります。","voiceIndex":118,"id":"exchange-052"},{"speaker":"西村委員","kind":"質問・要望","question":"品川区にはＨＥＡＲＴＳがありますし、スクールカウンセラーもいてくださって大変心強いのですが、不登校児の中には長らく外出できていない児童・生徒もいると伺っています。私が伺った事例ですと、ＨＥＡＲＴＳの面談をきっかけにマイスクール五反田に行く。児童センターに行くお子さんもいると伺っています。このようなことに関して、区のお考えと今後の展望をお聞かせください。","respondent":"矢部教育総合支援センター長、工藤指導課長","answer":"今後、１人１台タブレットが配付されますので、学校に来られないお子さんたちの新たなフォローになるかということで、学習面・生活面でも検討を進めていきたいと考えています。区内においても、マイスクール五反田等で通い始めて、自分で学びたいという意欲が上がってきて、進学につながっているという実績もあります。そういったところが相まって進学率が上がってきていると認識しています。","voiceIndex":120,"id":"exchange-053"},{"speaker":"西村委員","kind":"質問","question":"ＩＣＴの推進は大変期待が持てると思います。今、教育分野は大きく変わろうとしていると思っています。一般的に、フリースクール、ホームスクールなどは、原則、公的な支援がありませんので、親が学費を負担しなければならず、金銭面で苦しむ家庭も少なくないと伺っています。こういった、学校に行けない児童・生徒のこれからの公教育はどうあるべきか、区のお考えをお聞かせください。","respondent":"矢部教育総合支援センター長","answer":"ただ懸念は、不登校が長期化することを助長してしまうということは文部科学省の通知にもありますので、その辺りを慎重に進めてまいりたいと考えております。","voiceIndex":123,"id":"exchange-054"},{"speaker":"西村委員","kind":"質問","question":"ぜひとも引き続きお願いします。ひきこもり支援について伺いますが、全国的にも苦労しているといういろいろな報道が多い中、経済産業省の委託事業で、「ｅスポーツを活性化させるための方策に関する検討会」という報告書を読みました。都市部は特に、ゲーム、オンライン、ｅスポーツなどの取組みが注目されていますが、この辺りはどのようにお考えでしょうか。お聞かせください。","respondent":"矢部教育総合支援センター長","answer":"ｅスポーツにつきましては、世界でも認知されているということは承知しています。ただし、現在、新しく学習指導要領が改訂されましたが、そちらには示しがございませんので、国または東京都の示しを踏まえて対応していきたいと考えております。","voiceIndex":125,"id":"exchange-055"},{"speaker":"西村委員","kind":"質問・要望","question":"ほかの地域での事例ですけれども、オンライン学習、あと対話が中心の哲学カフェのような、非認知能力を養う講座を出席扱いとしたり、スタディーサプリを無料で受講できるといった事例も伺いました。それが心を開くきっかけになることもあります。寄り添う施策としてぜひ調査・研究を進めていただきたいと思っています。９月２１日の広報しながわで教育特集が組まれていました。次の質問に移ります。","respondent":"矢部教育総合支援センター長","answer":"それ以外に専門家、特に不登校への対応についての専門家をお呼びして、校内で研修を行っていただく。そのような事業です。","voiceIndex":127,"id":"exchange-056"},{"speaker":"西村委員","kind":"意見","question":"保護者出席率が９割という区内地域もあったそうです。１学期・２学期は外部の講師を呼ぶことが中止になりまして、コロナ対策をした上で、今まで培ってきた外部とのつながりを壊さないように、コミュニティ・スクールをぜひ継続してほしいと考えています。その辺り、ご意見をお聞かせください。","respondent":"矢部教育総合支援センター長、工藤指導課長","answer":"各学校の行事につきましては、委員がおっしゃったとおり、１学期はコロナ禍でございましたので大分控えてございましたが、新たな形で、日にちを分けたり、時間を分けたり、来ていただく方を制限したりということで進めてあります。ご指摘いただきましたように、コミュニティ・スクールは、地域に根差した、地域とともにある学校づくりという中では、やはり地域の関わりのところは、学校支援地域本部も含めまして。","voiceIndex":129,"id":"exchange-057"},{"speaker":"西村委員","kind":"質問・要望","question":"最後に、まもるっちについて伺いたいのですが、項目が特別になく、見つけられず、すみません。入学した際に、学校側もしくは、オプションのご説明までは要らないと思うのですが、基本装備の部分だけでももう少し丁寧に、説明会が難しい場合は、何かＹｏｕＴｕｂｅで動画で作っていただくなど工夫していただきたいと思うのですが、可能でしょうか。ご意見をお聞かせください。","respondent":"有馬庶務課長","answer":"ところが、今年度につきましては、ちょうど入学式があってすぐ休校になってしまったというようなこともございまして、保護者の方に十分な説明が学校からできなかったのかと拝察いたします。","voiceIndex":132,"id":"exchange-058"},{"speaker":"西村委員","kind":"質問","question":"私の子どもが１年生で、なかなか、まもるっちを理解できていなくて、コロナ禍ということがあったのだと改めて理解いたしました。何かそのような方法で、緊急通報時にどのような連絡が来るのか、あとはこれは２４時間対応できているのかなどのご質問も保護者の方たちからありまして、その辺りがなかなかまだ周知されていないのだと感じていますので、ぜひとも取組みをお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":134,"id":"exchange-059"},{"speaker":"つる委員","kind":"提案","question":"３６４ページ、図書館費、３６９ページ、学校図書館経費、それから教育費で学校の朝の受入れ時間について、それから３５２ページ、教育指導費について伺っていきたいと思います。図書館関係であります。その『よりぬきサザエさん』を読んで読書感想文を出したのです。中学校については、今年度についてはモデル校として、冨士見台中学校では市民科の授業で取り組まれていると伺いました。","respondent":"横山品川図書館長","answer":"国際連合で、持続可能な開発目標について、子ども、６歳から１２歳が学び、実際に行動を起こすことを促すために、「ＳＤＧｓ Ｂｏｏｋ Ｃｌｕｂ」という形で、目標の１から１７まで順番に取り上げて、１か月ずつブックリストを発表していくという方針が出されております。","voiceIndex":137,"id":"exchange-060"},{"speaker":"つる委員","kind":"質問・要望","question":"どこか分からなかったので教育費というところで恐縮なのですが、平日、いわゆる通常の登校する朝の、学校での受入れ時間の対応についてということなのですが、これは２０１９年ですか、２０１８年だったでしょうか、これから新１年生になるという保護者の方からご相談を頂いて、いわゆる小１の壁の一つとして、朝の登校時間の課題のご相談を頂きました。そういう学校も伺っているところであります。","respondent":"矢部教育総合支援センター長、有馬庶務課長","answer":"それに対応しまして、校長のほうで、今お話がありました教員の勤務時間のこともありますが、管理職を中心に、早めにお子さんを一部お預かりしている事例はあります。これは学習面の支援ということではございませんが、通学安全業務につきましては７時半から配置できるようにということで対応しています。","voiceIndex":139,"id":"exchange-061"},{"speaker":"つる委員","kind":"質問・要望","question":"子どもたちの安全・安心というところでは、７時半ぐらいから体制を取っていただいているということでありました。次に教育指導費ということで、午前中の質疑の中で、コロナ禍における様々な教育、それから指導内容については、オンラインの活用なども含めて個別具体のことは伺いましたし、また文教委員会でも一定程度質疑がされているのも確認させていただきました。","respondent":"矢部教育総合支援センター長","answer":"今後につきましても、今のようなコロナの事情、またこれから、なかなか制限がありますけれども行事も進めていくということになっておりますので、学校独自の工夫した、子どもたちの創意を活かしたような行事も組み立てていきたいと考えています。","voiceIndex":142,"id":"exchange-062"},{"speaker":"つる委員","kind":"質問・要望","question":"たしか今年の予算特別委員会でも申し上げたと思いますが、やはりそういう意味では、こうした機会をどう教育の現場で捉えて、児童・生徒の生き抜く力に結びつけていくかということが大事だと思います。「お手紙どうもありがとう。花丸」。それで今、生きる力というか勉強を頑張るという気持ちになっていて、やはりこんな、子どもの心に響くような教師が１人でも増えていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":144,"id":"exchange-063"},{"speaker":"くにば委員","kind":"質問","question":"私は、３５７ページ、一貫教育推進経費、３６７ページ、学校ＩＣＴ活用経費から、オンライン学習について伺います。品川区では、平成１８年に先進的な取組みとして小中一貫校を開校し、さらに平成２８年度には義務教育学校開校、令和２年度で５年目になります。","respondent":"工藤指導課長","answer":"そういった意味では、小学校も中学校もそれぞれの方針に応じた特色ある学校行事等も行ってありますので、義務教育学校の中で育まれる、また４－３－２という学年団のまとまりというのも非常に、特に５・６・７年生、また前期課程と後期課程の教員の行き来であるとか。","voiceIndex":146,"id":"exchange-064"},{"speaker":"くにば委員","kind":"質問","question":"今ご答弁くださったメリットであるとか、デメリットもあると思うのですけれども、そういった部分を、小・中学校の教育現場にフィードバックして、その結果、新たに始めた取組みや、あとは変更した教育手法がありましたらお知らせください。今、品川区には義務教育学校が６校ありますけれども、今後さらにこの取組みを強化して、義務教育学校を増やしていく方針はありますでしょうか。ご答弁をお願いします。","respondent":"工藤指導課長、篠田学務課長","answer":"やはり勉強合宿を行うにあたっては、様々指導員の確保であるとか、教職員体制が十分取れているというところで取り組みやすさというのがありますけれども、ただその取組みにつきましては。これまで品川区では６校、地域バランス等を考えて設置してまいりましたけれども、小学校・中学校・義務教育学校と、３校種の体制、バランスの取れた体制が一番重要と考えていますので。","voiceIndex":148,"id":"exchange-065"},{"speaker":"くにば委員","kind":"質問","question":"最後にもう一点、小中一貫校、義務教育学校出身者について、卒業後の中長期的な特性把握の分析であるとか、あとは小・中学校出身者との大学進学率の差異であるとか、その後の職業分布等の違いなど、客観的な統計データを取る調査やアンケート等はなさっていますでしょうか。こちらについては、全国の自治体や文部科学省で、同様に、この点の中長期的な統計調査は取っているのでしょうか。","respondent":"工藤指導課長","answer":"国のほうのそういった統計的な調査があるかということにも、現状、私どもも、そういったものがあるという把握もしてございません。","voiceIndex":151,"id":"exchange-066"},{"speaker":"くにば委員","kind":"質問・要望","question":"続いてオンライン学習についてです。学習の遅れは、学校がありとあらゆる工夫を図って教育をすべきで、これでは家庭への教育の押しつけだ」。そういった保護者の声について、区はどのように捉え、受け止めていますでしょうか。オンライン学習については、生徒へのケアだけではなく保護者の負担軽減、メンタル面への配慮やケアが必要だと考えますけれども、この点のお考えをお聞かせください。","respondent":"工藤指導課長","answer":"そういった意味では、例えば保護者の方に採点をお願いするなどという事例も幾つかあったと認識していますけれども、学校によっては、子どもが家で考えるような課題を提示しながら、またそれが、登校できたとき、または課題を回収するときに。","voiceIndex":153,"id":"exchange-067"},{"speaker":"くにば委員","kind":"質問","question":"自宅学習だと、漫画やゲーム、スマホ等、多くの誘惑があり、学習の進みが遅くなる生徒がいる。学校でほかの生徒と関わる機会が損なわれているため、人間関係形成についての教育が進まないなど、様々なデメリットが指摘されていますけれども、これらのデメリットに対する具体的な改善策の取組み、例えば集中力持続のための具体的な方策のアドバイスなど、どのようになさっていますでしょうか。","respondent":"工藤指導課長","answer":"委員から今ご指摘があったところですけれども、これから私どもはタブレットを導入して、さらにオンラインでの学習というのも進めていく中、また家庭学習の在り方ということについても、やはり同時に検討しているところではあります。","voiceIndex":155,"id":"exchange-068"},{"speaker":"くにば委員","kind":"質問・要望","question":"オンライン学習については非常に有用で、今後必ず進めていかなければいけない分野だと思います。コロナの影響はこれからもまだまだ続くと思いますし、ここに関しては区でもしっかりと研究を進めていただいて、オンライン学習が、より生徒が今までの学習よりもプラスになるような研究を進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":157,"id":"exchange-069"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私からは、３６１ページの特別支援教育費について伺いたいと思います。インクルーシブ教育の充実を求めて、学習支援員・介助員の拡充、それから特別支援教育推進計画の策定を求めて質問したいと思います。そのことで現場がどう変わったのか、また現場の状況から、今後さらに大幅に増やすことが必要ではないかと考えますが、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"品川区の人口が増えておりますので、今後も、広げてまいりたいと考えております。介助員・学習支援員の数については、手元にすぐ出てきませんので、今はお答えできません。すみません。","voiceIndex":159,"id":"exchange-070"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、増えた人数に合わせて５倍にした場合どうなるのかと計算しましたら、８億８,０００万円ぐらいになるのですけれども、そういうことで考えると、この予算の増え方というのは少し少ないのではないかと思うのですが、いかがでしょうか。そういうことからすれば、ここのところの大幅増をすべきではないかと思いますが、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"担任も、そのスタッフや、自分も見識を深めて、そのお子さんに対してどうあるべきか、ほかの子どもたちにはどう理解してもらうかということが大事なのかと考えておりますので、繰り返しますが、人数については増えていくことは認知しておりますが。","voiceIndex":161,"id":"exchange-071"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"だって、１人につき、１週間に１時間しかついていないわけですから。こういうことからも、ぜひ品川区ではもう少し、ここのところの増員、時間数の増、１人についての時間数の増も含めて、大幅増員をしていただきたいと強く要望しておきます。しかし、今、障害者の権利条約も批准されましたし、障害者差別解消法も整備されて、法整備もかなりできていまして、インクルーシブ教育の充実が求められております。","respondent":"矢部教育総合支援センター長","answer":"本年度におきましても、豊葉の杜学園に、ことばの教室、また来年度におきましても、荏原平塚学園と日野学園において、特別支援学級の前期課程のほうの対応をするところです。これからも様々な状況を鑑みながら計画的に進めてまいりたいと考えています。","voiceIndex":163,"id":"exchange-072"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"東京都も計画をもちろんつくっているのですけれど、それとともに、やはり区独自の計画をぜひつくっていただきたいと思うのです。隣の目黒区、そのほかの幾つもの区がつくっているのですけれども、隣の目黒区では、平成１９年に第一次をつくり、今年３月に第四次をつくりました。区としてもぜひ推進計画をつくって、この取組みを拡充させていただきたいと思うのですが、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"ご意見のとおり、これまでも計画的に進めてきたところです。まだまだ課題もあると思いますので、これからの成果とともに十分検討してまいりたいと考えております。","voiceIndex":165,"id":"exchange-073"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、計画をつくることによって、これまでの状況をしっかりと分析して、そして課題を明らかにして、そして何が今大事なのかというところを精査して、具体的な対策というところにつなげていくことができると思うのです。ぜひとも推進計画をつくっていただくように要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":167,"id":"exchange-074"},{"speaker":"せお委員","kind":"質問","question":"学校ＩＣＴ活用経費です。いよいよですが、来年、品川区においても、児童・生徒全員、１人につき１台、タブレットが渡されます。そこでお聞きしたいのが、各教科の指導に関しては、この文部科学省の資料を参考にされるのか、それとも、例えばですけれども、品川モデルみたいな感じで、名前をつけて品川区独自に活用方法を検討するのか、この活用方法について見解をお聞かせください。","respondent":"工藤指導課長","answer":"やはり区としても、品川区の一貫教育に合った活用を図るという観点で、学校、また教員の意見も反映させながら作成しておるところです。","voiceIndex":169,"id":"exchange-075"},{"speaker":"せお委員","kind":"質問","question":"今おっしゃられた、本当に品川区の特性に合わせた部分というのを取り入れていただけると効果が上がると思いますので、ぜひお願いいたします。そこで言いますと、ＩＣＴ推進校で今まで活用していたトータル学習システムもすばらしいものなのですが、このトータル学習システムは今後どのような取扱いになりますでしょうか。","respondent":"篠田学務課長","answer":"今後はなかなかそういう形ではなくて、クラウド環境において、常にオンラインで最新の情報が引き出せるといったことが理想的だろうということで、今回、新たなタブレットを配付するにあたっては、トータル学習システムはここまでという形で。","voiceIndex":171,"id":"exchange-076"},{"speaker":"せお委員","kind":"質問","question":"全く新しいものに変わるということで、教師の方も子どもたちも混乱しないようなＩＣＴの活用をお願いしたいと思っています。さらに、先ほどご紹介した文部科学省の参考資料ですが、その中には、特別支援教育におけるＩＣＴの活用についても資料があります。先ほどは教科の面でしたが、今度は特別支援教育におけるＩＣＴの活用について、品川区での具体的な方法を伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"特別支援教育におけるＩＣＴ活用についてのご質問です。既に特別支援学級におきましてはタブレットが渡っておりまして、１人１台とは申し上げられませんけれども活用しております。","voiceIndex":173,"id":"exchange-077"},{"speaker":"せお委員","kind":"質問・要望","question":"現在ある、そういったノウハウももちろん活用していただいて、個別最適化した学びを実現していただきたいと思っています。そこでお聞きしたいのですが、まず通常学級に通っている、特別支援教室の対象ではないお子さんは、現在、個別最適化した学びのための支援というのはどのように行っているのか。そして、タブレットを導入したらどのような支援になるのか。以上、２点、お聞かせください。","respondent":"矢部教育総合支援センター長","answer":"そこで個別に教員も回りまして、子どもたちの考えを活かして、その後、追究、検討となるわけです。そのようなことで、個々の時間において個別に対応していると考えています。","voiceIndex":175,"id":"exchange-078"},{"speaker":"せお委員","kind":"提案","question":"個別最適化した学びというと、先ほどご案内した文部科学省の活用例にもありますが、肢体不自由児などで、学校に通うのが困難なお子さんは、現在、特別支援学校の訪問教育を受けているお子さんが多くて、一般質問でもご提案しました、ＯｒｉＨｉｍｅなどを使って地域の子どもたちとの触れ合いを行ったり、視線や口を使って入力装置を使用するなど、ＩＣＴの活用が進めば、望んでいた未来に近づきそうで。","respondent":"矢部教育総合支援センター長","answer":"委員にご紹介いただきましたＩＣＴ活用も含めまして、これまでの特別支援学級等のＩＣＴ活用を、有効なものを取り入れて、今後もほかの、１人１台タブレットに向けて、有効な活用を考えてまいりたいと思います。","voiceIndex":177,"id":"exchange-079"},{"speaker":"せお委員","kind":"質問・要望","question":"質問が変わりまして、３５５ページ、学校支援費に関連して、児童・生徒のメンタルケアについてお聞きします。東京都は臨時休校明けに、スクールカウンセラーとの面接を、まずは心配な様子が見られる子どもから行い、その後、５年生、７年生、全員と行うよう求めていて、先ほど、品川区でも面接を行ったとご答弁がありましたが、面接した結果、どのようにフォローしているのでしょうか。","respondent":"矢部教育総合支援センター長","answer":"５年生・７年生以外の面談またはスクールカウンセラーの対応ですが、基本的にはやはり担任が毎日様子を見ていますので、そこから、養護教諭やスクールカウンセラー、また保護者と随時連携して、丁寧に対応していきたいと考えています。","voiceIndex":179,"id":"exchange-080"},{"speaker":"せお委員","kind":"質問・要望","question":"それで、児童・生徒に負担がかかり過ぎるような感染対策というのは、いま一度検討していただきたいと要望いたします。こちらは確認となるのですが、就学相談の中では、それぞれのお子さんに、通常学級か、特別支援学級か、または特別支援学校か、どこに就学したらよいかを伝えていると認識しています。さらに、現在の就学相談はどのような流れで実施していますでしょうか。２点お聞かせください。","respondent":"矢部教育総合支援センター長","answer":"就学相談についてのお尋ねです。就学相談の担当の委員は、まず医師です。さらに校長、また特別支援学級のあった学校の元校長、特別支援学校や特別支援学級の教員が集まって協議を致します。","voiceIndex":181,"id":"exchange-081"},{"speaker":"せお委員","kind":"質問","question":"今の就学相談の流れなのですが、お子さんの様子を見て面談をして、その後、どこがいいかとお伝えする。就学相談の中身はそれだけなのでしょうか。","respondent":"矢部教育総合支援センター長","answer":"その後に協議の結果、ここがよいのではないかというような助言をするという形で、そこからご連絡をさせていただいた際に、いかがですかということで、そこからさらに次の枝葉に分かれる選択肢、または相談に乗るというような手順です。","voiceIndex":183,"id":"exchange-082"},{"speaker":"せお委員","kind":"質問・要望","question":"これに関してはまた別の機会で質問します。主要施策の成果報告書の４８ページから、こちらも確認なのですが、事業概要に、「様々な障害のある児童・生徒の増加、多様化に対応するため、特別支援学級・特別支援教室を整備、増設する」とあり、課題のところにも、「特別支援学級の新設を継続して行う」とあります。","respondent":"矢部教育総合支援センター長","answer":"ただ、インクルーシブ教育は、いろいろなお子さんに対応するということだと考えておりますので、通常学級にいても、特別支援学級、特別支援教室、特別支援学校においても、そのお子さんにとって、これからの成長に一番望ましいものを支援していく場所と捉えております。","voiceIndex":185,"id":"exchange-083"},{"speaker":"せお委員","kind":"質問","question":"最後に１点だけ。特別支援学級を増設してほしいというか、多分、各校に欲しいというお声があると思うのですけれど、そういうニーズがあるということへの理由というのは何だとお感じでしょうか。","respondent":"矢部教育総合支援センター長","answer":"個別に様々な理由が考えられますけれども、やはり１つは保護者の理解。例えば、ここ１０年間、私が教育委員会にいた間でも、特別支援教育に対する理解はとても深まっていると思います。","voiceIndex":187,"id":"exchange-084"},{"speaker":"せお委員","kind":"質問・要望","question":"私たち障害児の親の考えでは、多くの人は、特別支援学級や特別支援学校というのは、本来のインクルーシブ教育には含まれていないです。それは、障害がない子たちとは所属が異なるからです。みんなで過ごせるという。そういったところが本来のインクルーシブ教育ではないかと私は思っています。ぜひともそこを念頭に、これからの教育のビジョンを考えていただきたいと要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":189,"id":"exchange-085"},{"speaker":"横山委員","kind":"質問・要望","question":"私からは、３５７ページ、ルネサンス推進事業について、３７５ページ、保健運営費について、５１８ページ、美術工芸品・芸術文化資料類についてお伺いいたします。１点目に、ルネサンス推進事業についてお伺いいたします。結果の平等を追求すべき内容と、機会の均等を確保しておけばよい内容とをどのように区別していますでしょうか。３点目の、美術工芸品・芸術文化資料類についてもお伺いいたします。","respondent":"工藤指導課長、矢部教育総合支援センター長、有馬庶務課長、篠田学務課長","answer":"ルネサンス推進、また「プラン２１」というお話も頂きました。品川区の一貫教育についてのお尋ねというところで回答申し上げます。例えば、「見通しと振り返り」という言葉になっていまして、子どもたちが一番最初に学習課題を捉えた後に、どうやって勉強していったらいいだろう。それ以外には、各学校では複製絵画を持っておりまして、これにつきましては、年に１回、学校を巡回するというようなことで。学校の健診と保健衛生部門との連携についてのお尋ねがございました。","voiceIndex":191,"id":"exchange-086"},{"speaker":"横山委員","kind":"意見","question":"みんな違っていい、みんなオーケーを両立するということをお願いしたいと思います。美術品についてなのですけれども、低稼働率のものなどがありましたら、なるべく区内全域の多くの子どもたちに鑑賞してもらえるようお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":197,"id":"exchange-087"},{"speaker":"小芝委員","kind":"質問","question":"私からは、３５３ページ、学校給食費に関連して和牛などを使用した学校給食について、３６３ページ、教科書採択事務について、３６９ページ、学校図書館経費に関連して電子書籍の促進についてお伺いいたします。この日本の食を守るために幾つか質問します。今年の３月から学校が休校となりましたが、学校の再開後、給食も再開されたと思いますけれども、いつ頃から具体的に再開されたのかを教えてください。","respondent":"篠田学務課長","answer":"今年度の学校給食の再開ですけれども、学校が６月から分散登校ということで再開されましたので、それに合わせて給食も提供させていただいたところです。","voiceIndex":199,"id":"exchange-088"},{"speaker":"小芝委員","kind":"意見","question":"その学校給食の食材が今、画期的なニュースとなっています。全国の自治体でも、和牛などを使った献立を提供する取組みがある中で、品川区でも学校給食に、これまではなかなか提供できなかった和牛など、日本の第一次産業で育てられた食を提供することで、子どもたちの思い出づくりをサポートすることになると思いますし、食育の機会にもなると思いますが、お考えをお聞かせいただければと思います。","respondent":"篠田学務課長","answer":"ですので、なかなか区が単独でできる事業ではないというのがあるのですけれども、そういった面で制度面が整ってくれば、一定程度、私どもも対応の仕方はあるのかとは考えているところです。","voiceIndex":201,"id":"exchange-089"},{"speaker":"小芝委員","kind":"質問・要望","question":"ざっくり否定されてしまいましたけれども、前向きにぜひお考えいただければと思います。続きまして、３６３ページ、教科書採択事務についてお伺いいたします。今年の夏、来年度から使用されます、中学校や義務教育学校の後期課程の生徒を対象にしました教科書の選定が行われました。教育委員会で教科書が採択されるまでの、ざっくりとした流れというものを教えていただきたいと思います。","respondent":"矢部教育総合支援センター長","answer":"教科書採択の流れです。初めに、教科用図書調査検討委員会を立ち上げます。その後に、教科書調査研究会、こちらは各教科別に担当教員がおりまして、複数で協議します。その結果を、次にもう一度、教科用図書調査検討委員会に上げまして、その報告を教育委員会でしていただく。","voiceIndex":203,"id":"exchange-090"},{"speaker":"小芝委員","kind":"質問・要望","question":"３段階を経て教科書が採択されるということを理解いたしました。教科書採択には、文部科学省のホームページにもあるとおり、公正性と透明性が求められています。品川区でも同様の事案がありました。その後、こういう事案のニュースは聞かなくなりましたが、教科書採択の公正性を担保するために品川区が取り組んできたことがあれば、教えていただきたいと思います。","respondent":"矢部教育総合支援センター長","answer":"教科書採択に関わるご意見のことです。２か所、品川区役所と教育総合支援センターにおきまして、教科書展示会を１か月間ほど行いました。その間に、アンケート用紙がありますので、それなどでご意見を頂いています。特に委員がご心配されるような内容はございませんでした。","voiceIndex":205,"id":"exchange-091"},{"speaker":"小芝委員","kind":"質問","question":"採択の原点に立ち、いかなる教科書であっても、公正・中立なご判断のもと、真摯に教育委員会で審議されるべきと考えております。そこでお聞きします。これまでの教科書採択の歴史の中で、数ある教科書の中で特定の教科書だけは採択しないようにという意見が、これまで教育委員会、また採択に関わる人々に対してされた事実はありましたでしょうか。","respondent":"矢部教育総合支援センター長","answer":"当然、意見を書きますので、このたびＡ社、Ｂ社についてご意見はありました。ただ、そこは、受ける意見の一つだと考えていますので、そのように認識しています。","voiceIndex":207,"id":"exchange-092"},{"speaker":"小芝委員","kind":"提案","question":"３６９ページの学校図書館経費に関連して、電子書籍の促進についてお伺いいたします。今年の第１回定例会で、我が会派の芹澤委員からも導入の提案がありました電子書籍について、コロナ禍を生きる子どもたちの未来に向けた質問をします。今、コロナ禍で、電子書籍への注目が高まっております。今は既に自由に使えると思いますが、今現在の学校図書館での状況を教えていただければと思います。","respondent":"横山品川図書館長","answer":"区立図書館から学校図書館へ、学校支援スタッフを派遣している状況ですが、休校が明けましてからは、スタッフも学校図書館で生徒を待って対応しているような状況が続いて、通常どおり開館しています。","voiceIndex":209,"id":"exchange-093"},{"speaker":"小芝委員","kind":"意見","question":"その環境を整えていくことも、行政による区民サービスの一つであると考えますし、ＧＩＧＡスクール構想で今年度中にタブレット端末が区内の全ての小・中学生に行き渡れば、誰もが電子書籍にアクセスできる公平性が担保されることからも、学校図書館への電子書籍の導入を視野に入れた前向きなお考えを頂ければと思いますが、よろしくお願いします。","respondent":"横山品川図書館長","answer":"先ほどご案内しましたように、電子図書館の導入そのものについても、今後の状況を見ながら検討していきたいと思ってあります。","voiceIndex":211,"id":"exchange-094"},{"speaker":"小芝委員","kind":"質問","question":"今、こういうコロナ禍の状況ですけれど、感染拡大防止につながる点で、私も電子書籍の導入に向けて質問させていただきました。今後も時代の変化に合わせて、品川区に限らず東京都、そして全国に至って、読書のパーセンテージを上げていただきますことを期待しまして質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":213,"id":"exchange-095"},{"speaker":"のだて委員","kind":"質問・要望","question":"私からは、３６９ページの学校図書館運営費に関わって、学校司書と司書教諭の充実について質問します。学校司書の配置について伺います。これまで、学校司書が毎日いるように配置を求めてきました。学校司書の全日配置に向けて、予算化などを含めて、今、どんな取組みをしているのか、伺います。","respondent":"横山品川図書館長","answer":"その中で問題点を把握し、今後の動きについて検討する形とともに、今現在、週１５時間の配置の中で、それ以外については学校において学校ボランティアの方や父兄の方にご参加いただき、いろいろな方が関わって学校図書館を運営していただく形を取ってありますので。","voiceIndex":215,"id":"exchange-096"},{"speaker":"のだて委員","kind":"意見","question":"今、いろいろなスタッフの方など、アンケートをしたり話し合いをしているということでしたけれども、現段階でどういった形というか、どういう意見が出されているのか、できる範囲でご説明いただけたらと思います。","respondent":"横山品川図書館長","answer":"ですので、急に全日配置というような勤め方はなかなか難しい、また、収入の面、時間の面でも、増えてしまうのが急であると対応しづらいというのが、スタッフ、また事業者の意見でもあります。","voiceIndex":217,"id":"exchange-097"},{"speaker":"のだて委員","kind":"質問・要望","question":"いろいろなボランティアの方など、区内の学校でもいろいろな状況があるということですので、できる学校から始めていただきたいと思いますが、いかがでしょうか。教育上、司書のいる学校図書館が求められているということですので、教育委員会が責任を持って学校司書の全日配置を行うことを求めますが、いかがでしょうか。","respondent":"横山品川図書館長、工藤指導課長","answer":"学校ごとに事情が違いますし、また状況もそのときによって変わってくることなので、その学校で、今は大丈夫であるけれど、来年度にそれが望ましいかどうかというのは、また冷静な判断が求められるところですので、それは。そういった意味では、学校図書館の効果的な活用は引き続き学校教育の中で進めていきたいと考えています。","voiceIndex":219,"id":"exchange-098"},{"speaker":"のだて委員","kind":"質問・要望","question":"運営スタッフが配置されている１５時間のうち１２コマが授業で埋まってしまい、選書や書架整理、教材用の図書を選ぶ時間、掲示物や装飾、図書館だよりを作る時間などが取れないということです。しかし、そもそも学校司書が行うべき仕事ができているのでしょうか。現在の学校司書配置時間で、ボランティアなどができない部分について、十分だと考えているのか、伺います。","respondent":"横山品川図書館長","answer":"スタッフの配置につきましては、まず運営にあたって毎月１回、学校の副校長を中心に図書の先生、スタッフ、また学校ボランティアの方も時には参加して、次の月の運営について打合せを持つような形が義務づけられてあります。","voiceIndex":222,"id":"exchange-099"},{"speaker":"のだて委員","kind":"質問","question":"ボランティア等学校全体でということですが、そういう方ができない、司書としての専門性が活かされる部分というのがあると思うのです。そういったところで、しっかりとした十分な時間が取れているのかということを改めて伺いたいと思います。","respondent":"横山品川図書館長","answer":"スタッフのほうが司書の資格を持っている場合もかなり多いですが、各学校に司書教諭の先生が配置されております。学校の責任としては校長先生が学校図書館長ですので、その指揮の下、司書教諭の先生が取りまとめをする形で運営している状況です。","voiceIndex":224,"id":"exchange-100"},{"speaker":"のだて委員","kind":"質問・要望","question":"司書教諭が取りまとめしているのは分かりましたけれども、十分な時間が確保されているのかということなのです。小学校で１２学級以上ある学校は、３７校中３０校あります。運営スタッフや先生からも時間増の要望が上がっています。１２学級以上ある学校では、学校司書の配置時間を増やしていただきたいと思いますが、いかがでしょう。","respondent":"横山品川図書館長","answer":"以前にも申し上げましたとおり、将来的には調整の上で時間を増やすことを検討していきたいと思ってありますので、先ほどのアンケートや打合せの結果も踏まえて、丁寧に対応について検討し、計画を進めていきたいと思ってあります。","voiceIndex":226,"id":"exchange-101"},{"speaker":"のだて委員","kind":"質問・要望","question":"全日配置に向けて力を尽くしていただきたいと思うのですが、１２学級以上ある学校の大変さというのは今起きていることですので、ぜひ早めに配置していくようにということで求めておきたいと思います。次に、司書教諭について伺います。現在、変更があればご説明ください。司書教諭のスキルアップも必要だと思いますけれども、区の司書教諭の研修はどのように行われているのか、伺います。","respondent":"工藤指導課長","answer":"司書教諭につきましては、司書教諭の資格は持っているということで、またその研鑽につきましては、研修会という形を開いてはございませんけれども、適宜校長から、また学校運営のスタッフなどと協議しながら進めていくというところがあります。","voiceIndex":228,"id":"exchange-102"},{"speaker":"のだて委員","kind":"質問・要望","question":"研修をやっていないということですので、ぜひそういったこともやっていただいて、司書教諭と学校司書の連携で、創造的な授業をやっていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":230,"id":"exchange-103"},{"speaker":"塚本委員","kind":"確認","question":"この警報の、何が出ているから休校だというところでの判断は、過去、保護者が各自にというようなところで原則的にはなされているかと思いますけれども、一方で、なかなか見にくいというか、情報収集がなかなか的確にできなかったりする場合もあったりするということで、品川区のホームページ等で。","respondent":"矢部教育総合支援センター長","answer":"今年度より、広報広聴課と連携いたしまして、７時の判断は変わりませんけれども、特別警報と暴風警報の２つが出た場合は、休校というお知らせをホームページにしていただくようになっております。今年度はまだその事案が発生してございませんので、今後努めてまいります。","voiceIndex":232,"id":"exchange-104"},{"speaker":"塚本委員","kind":"質問","question":"中学生のスマホ持込みのことについてなのですが、ご案内かと思いますけれども、今年の７月３１日に文部科学省から、中学校のスマホ持込みに関する通知というものが都道府県、政令市に対して出されたと。原則禁止ということはありつつ、持ち込む場合の４つの条件というものを示したということになっております。このことに関して、都から区にどのように伝えられているのか、初めにお伺いします。","respondent":"矢部教育総合支援センター長","answer":"スマートフォン等の持込みについては、国からの指示に従って、特段、東京都からの通知はまだ認知してございません。","voiceIndex":234,"id":"exchange-105"},{"speaker":"塚本委員","kind":"質問","question":"東京都からということでしたけれども、そうすると、この４つの条件は品川区としてどのように捉えているかというところが、焦点というか、お伺いしたい点になってくるかと思います。","respondent":"矢部教育総合支援センター長","answer":"これまでどおり、中学校も小学校も原則、持込み禁止です。ただし、事案によっては、保護者と相談しながら個別に対応しているケースもあると理解しています。","voiceIndex":236,"id":"exchange-106"},{"speaker":"塚本委員","kind":"質問","question":"つまり、この４つの条件を満たしていれば、どうぞ、お持ち込みくださいというスタンスなのか、いや、そうではないのだと。何度か委員会等でもこの議論はしていますけれども、どのように教育委員会としてこの課題に対して答えていくのかということについて、１つの選択肢というか、検討すべき事案ではないのかなとも思っておりますので、そういったところも含めて、もう一度ご答弁をお願いいたします。","respondent":"矢部教育総合支援センター長","answer":"原則禁止にのっとって、これまでに引き続き、ただ個別の対応には応じていくです。防犯についてのお問合せですけれども、そちらにつきましても、中学生はブザーを配付していますので、それを活用して自分で身を守るという点で、登下校の安全を守りたいと考えております。","voiceIndex":238,"id":"exchange-107"},{"speaker":"塚本委員","kind":"質問・要望","question":"身を守るという部分ではなくて、保護者との連絡手段として、要望というかお声が出ているので、ブザーはちょっと、この問題の解決としては違うのです。その点についてお考えをお聞きしたいのと、それとは別に、災害時等、今、コロナの関係もあって、さらにそういった意味ではいろいろな懸念事項が世の中にある中で、保護者として子どもと連絡を取りたいということに応えていくことについて、もう一度。","respondent":"矢部教育総合支援センター長","answer":"２点目、連絡ツールとしましては、まず中学生ですので、自分の安全を守るということで大事だと思うのですが、学校の中で被災すれば学校での連絡になりますし、今後はタブレットも配付され、どのように活用されるか、検討の余地がありますけれども、様々状況に鑑みた上。","voiceIndex":240,"id":"exchange-108"},{"speaker":"塚本委員","kind":"質問","question":"そう意味では、その部分について、教員にお任せというところではなかなか難しいというか、そういうわけにもいかない部分が出てくるというところで、１つはＩＣＴ支援員というのが、いよいよ支援員を強力に配置してというところでの支援という体制は伺っておりますけれども、ＩＣＴ支援員というところの支援で事足りるものなのかどうか。","respondent":"工藤指導課長","answer":"教員の体制としては、各学校にＩＣＴ推進の教員を位置づけて、その教員に対する研修も踏まえながら、またその教員による伝達研修も行いながら、また様々なことで情報も共有しながら、授業の効果的な活用というのは図っていきたい、そのような体制を考えているところです。","voiceIndex":242,"id":"exchange-109"},{"speaker":"塚本委員","kind":"質問","question":"この辺はＧＩＧＡスクール導入にとって非常に問われるところだと思いますので、また改めて取り上げていきたいと考えています。あるいは、例えば校長会などをＺｏｏｍでやったりしたなどということがあったり、この先やるかもしれないのか。そういった、教員における現状のオンライン活用の様子というのをお伺いしたいと思います。","respondent":"工藤指導課長","answer":"副校長連絡会は、オンラインで配信して行うであるとか、そういったところで活用も進めてありますので、研修をオンラインで進めるということも併せて進めてありますので、そういったところで活用を図って、またその活用の仕方も共有を図っているです。","voiceIndex":244,"id":"exchange-110"},{"speaker":"塚本委員","kind":"質問","question":"教職員の方々がしっかりとそういった機器に慣れるというか、少しでも親しむというか、やはり慣れるということですか。そういう意味では、今、使えるところからどんどん活用していけるようにしていくということも、１つの方策かと思いますので、そういった部分では積極的に、今後とも教職員の間でも使っていくような場面をつくっていくようにお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":246,"id":"exchange-111"},{"speaker":"あべ委員","kind":"質問","question":"私からは、３５０ページ、学務費になるのか、３０人学級について少し。それから３５３ページの就学援助費、３５５ページ、生徒指導対策等経費から痴漢防止について、それから３６７ページ、学校ＩＣＴ活用経費、時間がありましたら、３５５ページの帰国児童・生徒等支援費についてもお伺いしたいと思います。それから、就学援助費。既に実施したこと、または計画していることがあれば教えてください。","respondent":"篠田学務課長、矢部教育総合支援センター長","answer":"３０人学級に絡みまして、今後の校舎改築等の対応です。基本的には、私どもでは将来的な人口推計を見据えながら、現状の学級編制を基本に、今後どうしていくかということで、校舎改築等につないで整備しています。委員ご指摘のとおり、コロナ禍で、外部の人を呼んでの講習というのはできておりませんが、生活指導主任会が定期的にありますので、今のような内容について一度確認しまして、また周知を広めていきたいと考えております。","voiceIndex":248,"id":"exchange-112"},{"speaker":"あべ委員","kind":"質問・要望","question":"各自、今年は特に時数がタイトであるということも承知しているので、あれをやれ、これをやれなど、なかなか言いにくいのですけれども、ただ、やはり大切に育てて卒業させた子どもが、憧れの高校に入ったのに、通学途中に痴漢に遭って、怖くて学校に行けなくなってしまうというようなことは、もうこれ以上起きないようにしてほしい。ぜひ工夫していただきたいと思うので、今後について一言頂ければと思います。","respondent":"矢部教育総合支援センター長","answer":"委員のご指摘のとおり、もう一度確認して、できる範囲の中で進めてまいりたいと思います。","voiceIndex":251,"id":"exchange-113"},{"speaker":"あべ委員","kind":"質問・要望","question":"６月の一般質問でも伺いましたけれど、病気やけがなど長期療養中の児童・生徒への活用は、検討状況はいかがでしょうか。ここは、ぜひ急いでやっていただきたい、整備していただきたいと考えています。それから、学校内の教員以外の講師あるいは学校図書館司書など、教員以外の方もぜひＩＣＴの力を活用していただくことで、より学校をパワーアップしていただきたいと思いますが、いかがでしょうか。","respondent":"工藤指導課長、矢部教育総合支援センター長、篠田学務課長","answer":"それで、持ち帰りに関しては、重さもありますので、そういったときには柔軟に、これまでの例えばルールを変えて、今、配備いたしたタブレットは。ただ、物が行くだけでは活用がうまくいきませんので、そこについては十分、間を詰めて丁寧に対応して、ぜひ円滑にできるようにと考えております。基本的に、今回のＧＩＧＡスクールに関しましては、全ての子どもと教員というのがベースになっていますけれども、現実にはそのほかの形で、いろいろな形で。","voiceIndex":253,"id":"exchange-114"},{"speaker":"あべ委員","kind":"質問・要望","question":"それぞれ取組みも進めていらっしゃるということで大変安心しましたが、やはり学校によって、まだまだ取組みの具合に差があると思います。それぞれグッドプラクティスを見習いながら、品川区全体の教育の底上げをしていただければと思います。外国人児童・生徒に対してもオンライン授業が始まっていると聞いております。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":257,"id":"exchange-115"},{"speaker":"鈴木（博）委員","kind":"質問","question":"本日は、３７５ページ、第１目学校管理費、保健運営費から、学校における新型コロナウイルス感染症について質問いたします。このマニュアルも踏まえながら、この間の品川区の、学校における新型コロナウイルス感染症対策についてお伺いしていきたいと思います。品川区はどの感染レベルに相当すると教育委員会は考えておられるのでしょうか。お知らせください。","respondent":"有馬庶務課長","answer":"基本的には、これまでの国の通知や都の通知といったものを踏まえまして、区では区立学校における感染症のガイドラインというものを設定しておりますので、それに基づいて、今、対応しています。","voiceIndex":259,"id":"exchange-116"},{"speaker":"鈴木（博）委員","kind":"質問","question":"品川区は、品川区の独自の基準と考え方で感染レベルを設定しているというお話と理解いたしました。以下、具体的に質問してまいります。品川区では子どもたちにどのように感染予防について教え、理解させているのでしょうか。特に教職員の目が届かないところでの注意事項など、具体的な取組みについてお示しください。","respondent":"矢部教育総合支援センター長","answer":"臨時休業中から、通知や学校ホームページによって、感染症予防策、３密を避けた行動等について、ガイドラインによって周知しています。現在は、区で作成している感染予防ガイドラインにのっとって、３つの密の回避を徹底すること。","voiceIndex":261,"id":"exchange-117"},{"speaker":"鈴木（博）委員","kind":"質問","question":"一般質問に引き続き、マスクについて再度お尋ねします。文部科学省の衛生管理マニュアル「学校の新しい生活様式」によれば、マスクは密接に対する処置であり、学校の教育活動においては、児童・生徒等および教職員は身体的距離が十分に取れないときはマスクを着用するべきと記されています。併せて、フェイスシールドやマウスシールドなどについても、教育委員会のご見解のご説明をお願いいたします。","respondent":"矢部教育総合支援センター長","answer":"ただ、お子さんによって（マスクを）したい、外したいというお子さんもいますので、個別に対応しています。","voiceIndex":265,"id":"exchange-118"},{"speaker":"鈴木（博）委員","kind":"確認","question":"ただし、医学的ファクトがない場合、例えば熱中症の危険がある場合など、マスクが必要ない場合、あるいは医学的に例えば荒れるとか、そういう場合というのは、無理にさせる必要はないということで、小児科医、臨床医の間では統一見解が出ております。次に、出席停止について少しお伺いします。皆勤賞なるものは、既に今、小学校ではなくなったと考えてもよろしいのでしょうか。その確認もお願いいたします。","respondent":"矢部教育総合支援センター長","answer":"皆勤賞につきましては、教育委員会が示したものではなく、各学校で、また、もしかしたらクラスでつくっている場合もあるかと存じますけれども、そこは学校の裁量で、それを楽しみに来ている子どもも実際にいましたので、そういう裁量になってあります。","voiceIndex":267,"id":"exchange-119"},{"speaker":"鈴木（博）委員","kind":"質問","question":"このためにわざわざ無理をして学校に行くような、非常に誤った風潮なども助長することになりますので、認めるのではなくて禁止する方向で、学校の対応をぜひお願いしたいと思います。先ほども質問がありましたが、コロナ流行下においても、児童・生徒の適切な栄養補給と食生活を支援するために、感染リスクに配慮しつつも積極的に進めていかなければならないと考えます。","respondent":"篠田学務課長","answer":"現状の学校給食についてご説明いたします。基本的には、一人ひとり個別に授業のスタイルで、間を取りながら前を向いて会話しないで給食を取るという形が子どもたちのほうの対応です。","voiceIndex":269,"id":"exchange-120"},{"speaker":"鈴木（博）委員","kind":"質問","question":"今回、決算特別委員会を通して行ってきた、私の新型コロナウイルス感染症に関しての一連の質問は今日で終わりますが、新型コロナウイルス感染症は高齢者では今でも非常に恐ろしい病気です。感染予防策は大切です。感染予防策それ自身を絶対化することなく、血が通い、温かみのある配慮を加えることによって、それで運営してこそコロナと共存する新しい生活様式だと確信して、私の質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":271,"id":"exchange-121"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私からは、３５２ページ、教育指導費に関連して、性教育について伺いたいと思います。性の正しい知識、それに伴った行動が重要だということで、性教育の充実を求めてきましたけれども、先日、アフターピル、緊急避妊薬を薬局で購入できるようにするかどうか、こうしたことの議論がＮＨＫなどでも報道されておりました。そこで注目が集まっているのが、日本の遅れた性教育です。区は遅いと思いませんか。","respondent":"矢部教育総合支援センター長","answer":"実際の指導には、水着の隠れる部分は見せたり触らせたりしないようにという指導は、日常的に小さな子でもやってあります。ＣＡＰやセーフティ教室の中でも、犯罪被害の防止に努めているところです。","voiceIndex":273,"id":"exchange-122"},{"speaker":"石田（ち）委員","kind":"質問","question":"その学習指導要領が問題というか、本当に遅いと私は思うのです。１４歳、１５歳で妊娠している状況です。産婦人科医の先生方からも、望んでいるならいいのですけれども、やはり望んでいない、そして予期せぬ、そうしたことが１０代には多いと。そうしたことも含めて教えてもらえたらと私も思っています。性の権利を守り、そして学び、男女ともに学んでいくことが必要だと思いますけれども、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"ただ、現状において、日本において、やはり一番大事なのは、暴力の加害や被害、また傍観者にならないということが一番基本だと考えておりますので、学年の発達段階に応じて進めてまいりますが、国も性被害防止については検討していますので。","voiceIndex":275,"id":"exchange-123"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"やはり、そうした性被害の防止についても、お互いの体を知り、そしてどうしたらどうなってしまうのかというのを、早い段階から教えていくことが必要だと思うのです。これは何回も言わせていただくのですけれども。性は、生きていく上では切り離せない、幅広く深いものですので、私はやはり包括的性教育をしていただきたいと。そこはいかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"学習指導要領にのっとるのは先ほどのとおりですが、教育会では、体育部門、保健部門がありますので、そちらのほうでの検討でいろいろな授業が展開される可能性はあります。","voiceIndex":277,"id":"exchange-124"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"幾らそこで、それは駄目なのだというのを教えても、全体的に体の仕組みから、どうするとどうなっていくのかということ、そして性的アイデンティティや性的指向ということも含めて早い段階から教えていかないと、結局、暴力につながっていってしまうと思います。ぜひその立場に立って、学校教育要領を含めて抜本的に見直していただきたいと思いますけれども、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"本区の学校教育要領も学習指導要領を基に進めてありますので、意見は分かりましたけれども、発達段階に応じて、今、計画的に進めているところですので、あくまで人権尊重を基盤にして、各教科・領域において指導してまいりたいと考えております。","voiceIndex":279,"id":"exchange-125"},{"speaker":"西本委員","kind":"質問","question":"ご見解を聞きますけれども、これ以上、生産者をいじめないでほしい。しっかりと法にのっとった形で、必要であるならば国が放射性物質のチェックをするという方向を示すべきであるわけであって、品川区が安全なものを提供しているということであるならば、放射性物質の検査についてはやめる方向でお願いしたいと思いますが、その見解をお聞きします。それから３５５ページ、教育指導費になるのでしょうか。","respondent":"篠田学務課長、品川財政課長、有馬庶務課長、矢部教育総合支援センター長","answer":"やはり検査をするということは、それなりに経費もかかりますし、また労力もかかってくるということがありますので、こういった実情を鑑みながら。今後、毎年１校から２校ぐらい、今、改築を進めているのですけれども、ここに対して充当していくために基金を積み立てていっているというものです。８３運動につきましては、委員ご指摘のとおり、今、小学校ＰＴＡ連合会が中心になって、推進委員会が発足してということですので。","voiceIndex":283,"id":"exchange-126"},{"speaker":"西本委員","kind":"質問・要望","question":"ですので、改めていただきたいと思います。積立金についてですが、これは５０億円というのが毎年積み上がっていくという、一定金額を積み上げていくというものなのか、あとは、今後増やしていくとか減らしていくなどというのは、どういう観点で、先ほど、年に１校、２校という形でということなのですが、その辺の計画、長期にわたっての計画があるのかを確認したいと思います。ここをお聞きしたいと思います。","respondent":"品川財政課長、矢部教育総合支援センター長","answer":"こういうところにも応じて、積立額というのは状況を見て変えていこうと考えています。今後、学校改築が続きますので、それを維持できるような形で、資金もしっかりと準備をしていきたいと考えております。直接電話で頂くこともあります。少なくとも、悩んでいる保護者が多いので、学校名が分かれば、こちらから連絡をして、学校のほうで丁寧に対応しています。","voiceIndex":288,"id":"exchange-127"},{"speaker":"西本委員","kind":"質問","question":"問題行動を起こす保護者の方々ですが、これは多分、認識されている部分はあるかと思うのです。私も幾つか相談を受けております。そして、一番心配なのは、お子さんたちなのです。そこのところの認識はどこまであるのでしょうか。その場合の、例えば弁護士を雇う、相談に乗るなどという体制は、どのぐらいまでできているのでしょうか。","respondent":"矢部教育総合支援センター長","answer":"子ども家庭支援センターとも連携しまして、必要に応じて、福祉や医療（の部門）とも相談して進めてまいります。","voiceIndex":291,"id":"exchange-128"},{"speaker":"こんの委員","kind":"質問","question":"私からは、３５１ページ、８３運動経費、３６１ページ、特別支援教育費、３６５ページ、図書館運営費からお伺いしたいと思います。８３運動経費は、関連して、ＰＴＡの方や地域の方々と区と協働で取り組む、児童・生徒の登下校における安全対策・防犯対策についてお尋ねいたします。","respondent":"有馬庶務課長","answer":"８３運動の見守りの効果ですが、これをどういうふうに検証するかというのは、なかなか難しい部分があるかと考えております。","voiceIndex":294,"id":"exchange-129"},{"speaker":"こんの委員","kind":"質問","question":"先週の総務費のところでも触れましたけれども、警視庁が発信している「メールけいしちょう」という不審者情報、こうしたメールはご存じでしょうか。昨年１年間で届いているメールけいしちょうは約１００件ありまして、これを換算すると、三、四日に１件、発生していることになります。こうした状況が見られます。こうした取組みは必要ではないかと考えるわけですが、いかがでしょうか。","respondent":"有馬庶務課長","answer":"最初の質問で、防犯の意識は、８３運動に関わってくれている方は、誰もがそういう防犯の意識ということで子どもを見守ってくれている、それは間違いありません。それをどういうふうにはかるかというところは難しいという説明をさせていただいたものです。","voiceIndex":296,"id":"exchange-130"},{"speaker":"こんの委員","kind":"質問・要望","question":"１つには、情報共有ができる環境もなくはないというところですが、それをさらに広げていくようなお考えで、情報を共有しないと、なかなかどこがどういうふうに見守っていいのか。せっかく防犯意識を持っていただいているのであれば、その見守りを効果的にしていただくような方策を、ぜひ今後、考えていただければと、要望で終わります。この事業に対する令和元年度の事業の総合評価は、Ａとなっておりました。","respondent":"矢部教育総合支援センター長、工藤指導課長","answer":"特別支援学級の数です。１３学級あります。それと、学級数は、令和２年度、固定級が２５学級、通級が７学級です。区内での異動の場合にも、経験者を配置する。初任者あるいは経験年数が浅い教員が提示されることもありますので、そういったバランスをよく見ながら、継続した支援ができるよう配置を行っているところです。","voiceIndex":298,"id":"exchange-131"},{"speaker":"こんの委員","kind":"質問・要望","question":"そういう状況の中だと分かったのですが、実態は、お子さん方、いわゆる児童・生徒に対応する先生の対応力と言うのでしょうか、保護者とのコミュニケーションの取り方というのでしょうか。その辺のところは、専門家の方が視察し、そして助言していく、指導していく中で、どのようなコミュニケーション、指導力といったことへの指導というのはあるのでしょうか。","respondent":"矢部教育総合支援センター長","answer":"ただ、そのときには、今、若手の特別支援教室の教員などもおりますので、ベテランと一緒に対応しているようなところです。そのほか、３年次までの教員には、一般的に研修が３年間ありますので、その中で特別支援教育の研修も行ってあります。","voiceIndex":301,"id":"exchange-132"},{"speaker":"こんの委員","kind":"提案","question":"今お話を伺って、とすると、なかなかコミュニケーションの取り方、また指導・育成は、それぞれの感じ方や、コミュニケーションは本当に取りにくい、難しいところでもあると思いますけれども、児童・生徒の育成には、保護者のご協力も大変に大事だというところも考えると、先生と保護者の方との信頼関係はお子さんにとっては本当に大事なところだと思いますので。","respondent":"横山品川図書館長","answer":"図書館で検討いたしまして、ティーンズの担当を中心に、ＳＮＳでの発信であるとか、ＹｏｕＴｕｂｅの利用だとかについて、現実的に検討できるかどうかというのを、今、計画立てて進めているところです。","voiceIndex":303,"id":"exchange-133"},{"speaker":"こんの委員","kind":"質問・要望","question":"学校図書館においては、著作権のことも、先ほどの答弁を聞いて理解しているところです。近い将来、著作権のことなどの課題がクリアになったならば、学校図書館の本がタブレットで見られる。こうした環境を作っていけるよう要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":305,"id":"exchange-134"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"学校地域コーディネーターです。そうすると、今までですと比較的、時間の動きが取れたような状況が、職員ということで拘束されてくるのではないかと想像するのですけれど、その辺のところは影響がないのかどうかということを１点確認させてください。その辺の規定があるのかどうかも確認させてください。そういうことがないと思うのですけれど、その辺の関係も教えていただければと思います。","respondent":"工藤指導課長","answer":"会計年度任用職員になったとしても、１年ごとの任用ではありますが、それを継続することは可能ですので、そういった意味では、同じ方、続けていただける方がそのまま続けていただけるような状況です。","voiceIndex":307,"id":"exchange-135"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"本当に、学校と地域をうまくつないでいる方なので、これからも校区教育協働委員会とも協力しながら、いい形で進めていっていただきたいと思います。その上で、今回、質問の中で、品川コミュニティ・スクールというのはあまり出ていなかったので、品川コミュニティ・スクールにかける品川区の思いがもしあれば改めて一言頂ければと思うのですが、よろしくお願いします。","respondent":"工藤指導課長","answer":"今、全校で展開しています品川コミュニティ・スクールですが、やはり地域とともにある学校づくりの中で、校区教育協働委員会の中には、卒業生、また地域の方も含まれるというところで、本当に学校が地域の中のコミュニティの拠点として。","voiceIndex":309,"id":"exchange-136"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"これも要望にします。２点目に、学力向上プラン推進事業の勉強合宿についてです。８年生が今、行っていると思うのですけれど、この取り組み状況を教えていただければと思います。","respondent":"工藤指導課長","answer":"勉強合宿についてのお尋ねです。ご指摘いただきましたように、８年生の夏季休業中に集中的に学習に取り組むという事業です。現在、義務教育学校６校と中学校、合わせて８校で実施しています。宿泊型で行っているのが４校、通学型が４校ということで取組みを進めているところです。","voiceIndex":311,"id":"exchange-137"},{"speaker":"鈴木（真）委員","kind":"質問","question":"分かりました。ただ、少し気になっているのは、今８校だけがやっている中で、やはり全校展開できないのかなという思いもあります。それから夏の間ですから、クラブ活動とか、いろいろな問題が絡んでくるとは思うのですけれど、やはり全員が受けられる体制も取ってほしいと、これは希望なのですけれど、その辺のお考えを教えていただければと思います。","respondent":"工藤指導課長","answer":"そういった意味では、先ほど申し上げた宿泊日数であるとか、例えば通学型から始めるとか、できるところからスタートするような工夫なども併せながら、また支援にあたる、指導にあたる人材の確保なども、併せて取組みを進めて、拡充を図っていきたいと考えています。","voiceIndex":313,"id":"exchange-138"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"それからもう一点、学芸大学との連携のプロジェクトです。これが、就学援助を受給しているご家庭の６年生の勉強の機会をつくってもらっていた中で、これは今年の予算には入ってきていなかったので、その辺の進め方について、指導という点でお考えを教えてください。","respondent":"工藤指導課長","answer":"学芸大学の連携事業ですが、こちらにつきましては、東京学芸大学と連携して、学習支援と、また学芸大学附属中学校への進学支援を行うという事業でございました。当初、予定していました３年目ということで、令和元年度におきまして学習支援については終了したところです。","voiceIndex":315,"id":"exchange-139"},{"speaker":"鈴木（真）委員","kind":"質問","question":"そうすると、昨年度でそれが終わってしまったのですけれど、これからの進学支援ということにどのようにまた取り組んでいくのかについてと、それから、現在、学芸大学附属中学校に行っているお子さんに対する、品川区教育委員会として何かフォローしなくていいのかというのも少し感じているのですけれど、やはり少し離れた学校に行っているところで、その辺は何か考えていらっしゃるのかどうか。","respondent":"工藤指導課長","answer":"そういった補充学習のところで、またそれは、自分が通っている学校で開かれている未来塾に通うことができるというところで、学習支援は行っていけるとは考えてありますが、いわゆる補充学習等につきましては、しっかりと取り組んでいきたいと考えています。","voiceIndex":317,"id":"exchange-140"},{"speaker":"高橋（し）委員","kind":"質問","question":"３５５ページ、教職員研修。教職員研修。この若手の教員の方にどのようなアドバイスをしていただけるでしょうか。もちろんないと思いますが、品川区ではこういうことはないのでしょうか。ほかの学校でも、全てのページは難しいかもしれませんけれども、このような取組みをお願いしたいと思いますが、お考えを伺います。あれば、工事の方あるいは教職員、児童・生徒にけがなどはなかったのでしょうか。","respondent":"工藤指導課長、矢部教育総合支援センター長、小林学校施設担当課長","answer":"やはりそういったところを、同じ学年で、あるいはチームの中で、しっかりと取り組んでいくという姿勢が必要であると考えますので。学校だよりの振り仮名等ですが、本当に優しい対応だと感じております。確かに時間はかかりますけれども、好事例として紹介していきたいと思います。改築工事での現場での事故というのは、ないものと記憶しております。","voiceIndex":320,"id":"exchange-141"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"先ほどの学級通信の例は品川区ではないと思いますので、もし仮にそういうことがあったとしたら、チームで指導していただきたいと思います。改築は承知しました。そういったところを地域未来塾でどのようにカバーしていらっしゃるのでしょうか。補習という観点でどのようにカバーしているか、また実施日数を増やすなどの、あるいは財政支援等で支援していただきたいと思いますが、いかがでしょうか。","respondent":"工藤指導課長","answer":"地域未来塾につきましては、学校再開と同時に各学校、予定に従いまして進めることができております。そういったところでは、放課後補充学習として、指導員の方からのサポートがありながら進めているところです。","voiceIndex":324,"id":"exchange-142"},{"speaker":"高橋（し）委員","kind":"質問","question":"授業については、授業時間数確保ということで、授業がかなりハードな形で進めていると思いますので、１つのフォローとして地域未来塾の活用をお願いいたします。次は学校ＩＣＴ化ですが、いろいろな委員の方から質問が出ておりましたので、そこと重ならないようにＩＣＴ支援員についてお尋ねします。どのような方が何人ぐらい学校を巡回しているのでしょうか。日数等は先ほど伺いました。","respondent":"篠田学務課長","answer":"現在は、ＩＣＴ推進校１０校を中心に回ってあります。推進校は毎月１回、それ以外の学校は学期に１回回っているという形です。回っているのは、民間のコンピュータ関係に詳しい方で、教育情報化コーディネータ２級という資格を持った方が回るという形で契約しています。","voiceIndex":326,"id":"exchange-143"},{"speaker":"高橋（し）委員","kind":"質問","question":"今、教育情報化コーディネータという資格をお持ちの方ということで、この資格をお取りになって、いろいろな人材派遣のところに登録し、学校を巡回している方が多いと伺っています。この後、タブレットが支給された場合に、どれぐらいの頻度で学校を巡回していただけるのでしょうか。","respondent":"篠田学務課長","answer":"したがいまして、かなり手厚くやっていく必要があるとは考えてあります。予算との絡みもあるものですから、今のところ、様々検討しているところではありますけれども、少なくとも今まで以上の形での配置をしていきたいと考えているところです。","voiceIndex":328,"id":"exchange-144"},{"speaker":"高橋（し）委員","kind":"質問","question":"それともう一つは、機械が調子が悪いとか、つながらないとかだけではなくて、やはりＩＣＴ支援員の一番大事なところは、熊本市の教育委員会の方がおっしゃっていましたが、授業の教材づくりにどこまで協力できるかということで、学校の授業の中身と、それを授業でどういうふうにするかということの理解がある方が、ＩＣＴ支援員になり、そして教員が教材をつくるところでアドバイスし。","respondent":"篠田学務課長","answer":"教員と一緒に教材等の作成ですけれども、これは現実に、今の支援員もかなり、各学校を訪問した際には、一緒に教材研究・作成等を手伝っているところがありますので、引き続き今後もそういった対応が取れるような体制を取っていきたいと考えているところです。","voiceIndex":330,"id":"exchange-145"},{"speaker":"高橋（し）委員","kind":"意見","question":"週１日だと８,０００万円余ということですので、手厚くお願いいたします。","respondent":"篠田学務課長","answer":"これから、今まで入られた方も加えて、新たな方も入ってこられますので、きちんと学校と連携した形で、実のあるものとなるように、私どもも注視してまいりたいと思っているところです。","voiceIndex":332,"id":"exchange-146"},{"speaker":"須貝委員","kind":"質問","question":"卒業を迎える学年の児童・生徒に３月末までに指導すべき内容の指導を行うことができなかった場合、当該児童・生徒の卒業を認定するのかを教えてください。そして、児童・生徒の学習保障は、実際、本当にできるのでしょうか。学年ごとに必要な学習が身についていると、どのようにして判定するのですか。そして、判定テストでも行って、身についていない児童・生徒がいた場合、補習や再テストを行うのですか。","respondent":"工藤指導課長","answer":"学習の保障に関するお尋ねです。４月当初から臨時休業が続いたことで、授業日数としては３４日間ほど不足したところがあります。","voiceIndex":335,"id":"exchange-147"},{"speaker":"須貝委員","kind":"質問","question":"きちんと答えてください。だったら、授業がきちんとできていない、身についていないということではないのですか。もう一つ質問しますので、その後にお聞かせください。自主欠席を行うことで、児童・生徒の学習にさらに遅れが生じることが予想されますが、この辺について学習保障はきちんとできるのですか。教える日数が少ない。だったら、子どもたちはどういうふうにされるのですか。教えてください。","respondent":"工藤指導課長","answer":"必要な事項については指導しています。様々な理由で出席停止扱いということで、学校に登校しない場合でも、各学校の担任からは課題を渡し、その課題について添削する。そういったところで学びを止めないという動きは、学校がしっかりと取り組んでいるところがあります。","voiceIndex":337,"id":"exchange-148"},{"speaker":"須貝委員","kind":"質問","question":"今、日数が少なくて、いや、家庭でテキストを持ち込んでやると。だったら、学校は要らなくなるのではないですか。だったら、補習なり何なりきちんと、やはり教育委員会としてもっと、夕方に勉強、補習をするとか、どこかで補うとか、土曜日も今、休んでいるわけですけれど、そういうのも使って、できるだけ遅れないようにやるべきだと私は思うのですが、もう一度お考えをお聞かせください。","respondent":"工藤指導課長","answer":"いわゆる知識・理解などの学力だけではなく、コミュニケーションを取りながら、対話をしながら進める学習というのは非常に重要であることは、私どももコロナ禍の中で再度認識したところがあります。","voiceIndex":339,"id":"exchange-149"},{"speaker":"須貝委員","kind":"質問・要望","question":"私がしっかりと考えてほしいのは、学力格差が広がってしまうのです。それについては、私はしっかりと考えていただきたいと思います。通常で、今の状態でも格差がある。その中で、１つここでお聞きしたいのですが、オンライン教育・授業のメリット・デメリットを教えてください。品川区はオンライン授業を発展させていくつもりなのか、そしてデメリットについてどういうふうにお考えか、教えてください。","respondent":"工藤指導課長","answer":"オンラインで行う教育というのは様々な展開が考えられるところがあります。現状、オンラインで取り組むというところで、今、学校で進めているもので言えば、ゲストを招いたような学びというのは、コロナ禍の中では非常に難しいところがあります。","voiceIndex":341,"id":"exchange-150"},{"speaker":"須貝委員","kind":"質問","question":"だったら、こういうことをどうして教育委員会は考えていないのですか。これは民間企業もそうなのです。今、テレワーク、オンラインから、やはり対面式にするべきだという会社が増えつつあります。ですけれど、その辺も考えて子どもたちの教育というのを見ていく、そしてずっと考えて見守っていくということが、教育委員会として大事なことだと私は思うのですが、いかがですか。ご見解をお聞かせください。","respondent":"工藤指導課長","answer":"やはり有効な点は教育活動に取り入れながら、学校という場で授業を行いながら育むべき資質・能力を最も大事にしていくというのは、これまでと同様に変わらずに進めていきたいと考えています。","voiceIndex":343,"id":"exchange-151"},{"speaker":"須貝委員","kind":"質問・要望","question":"今、そういうお話をお聞きしました。きちんと医学会で報告もされています。やはりそういうところも勉強していただいて、きっとやっていると思うのですが、やはり将来、この子どもたちをどういうふうに学ばせていくのだ、そして、社会へ立派に飛び立てるようにできるのだということを考えながら、教育というのを見ていただきたいと私は思います。何かご意見があったら、最後に一言言ってください。","respondent":"工藤指導課長","answer":"頂いたご意見がありますけれども、私どもは、やはりオンライン教育というもののよさを活用しながら学校教育を進めてまいります。","voiceIndex":345,"id":"exchange-152"},{"speaker":"安藤委員","kind":"質問・要望","question":"３６３ページ、教科書採択事務、３７３ページ、普通教室増設工事等に触れながら、少人数学級について伺います。伺いますが、教科書採択はイニシャルでなく教科書会社名で報告・審議することと、あと教科書展示の区民意見の報告内容は、委員が採択する上で十分な資料になり得るような、意見総数など数字の報告も含めて充実すること、以上２点を改めて求めたいと思いますが、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"１点目のほうは、分かりやすい教科書採択に向けまして、私どもも次回の採択に向けて検討してまいりますが、１つは、イニシャルでというのは、小学校でしたら１年から６年までの教科書に何社も手を挙げて発行しているものですから、物凄い数が机の上に乗りまして。","voiceIndex":348,"id":"exchange-153"},{"speaker":"安藤委員","kind":"質問・要望","question":"今の説明を伺っても、私は、イニシャルで、何でわざわざ傍聴者が分かりづらいやり方をするのかというのは、言葉は悪いですけれど、へ理屈にしか聞こえないというか、教育委員がその場で、そんなにもう、一から十まで全部の教科書を読み上げているのかというと、そんな実態はないと思いますし、やはりどういう教科書が採択されるかというのは、別に立場がどうであれ、住民の関心事なのです。大事な関心です。","respondent":"篠田学務課長","answer":"ただ、やり方ですけれども、様々な形で、今、学校にある多目的室ですとか、あるいは少人数学級用に今、設置しているような部屋で、そのまま部品だけを入れれば使えるような部屋もあるのですけれども、やはり中を工事で改築した上でないと教室を転用できないところに関しては。","voiceIndex":350,"id":"exchange-154"},{"speaker":"安藤委員","kind":"質問","question":"もう一点伺いたいのですが、これらのように、現状、普通教室増設に使える多目的室などの教室は、これから改築していくというところはあるでしょうけれど、区内全体で、まだ改築していないところも含めてどれだけあるのか、伺いたいと思います。","respondent":"篠田学務課長","answer":"実際には、普通教室化するための部屋ということではございませんで、いろいろな形で活用していますので、必ずしもきちんとした形での把握は難しいと考えているところではあります。","voiceIndex":352,"id":"exchange-155"},{"speaker":"安藤委員","kind":"質問","question":"伺いますけれど、本来なら２６人なのに３９人、本来なら３０人なのに小学校１年生から４０人というのは、加配をしたとしても、子どもにとっても教師にとってもよくない選択だと思いますが、いかがでしょうか。なぜ素直に学級数を増やさずに、加配を選択しているのか、やむを得ない理由でもあるのか、あるならその解決に区教育委員会は援助しているのか、伺いたいと思います。","respondent":"篠田学務課長","answer":"１年生に関しましては、学級編制、法律でも３５人と定められているところですけれども、特例的に４０人での対応も可能であるという形です。それに基づいて、委員ご指摘のような事例が発生しています。","voiceIndex":354,"id":"exchange-156"},{"speaker":"安藤委員","kind":"質問","question":"１年生から４０人というのは、考えられないといいますか、そういうところにこそ、お金を使うべき。私は、そういう課題があるのだったら、何かその解決に区教育委員会は援助しているのかと伺いましたので、伺いたいと思います。そして、文教委員会などでもありましたけれど、区が独自に加配する区費講師、そういう方もいらっしゃるということなので、その人数も伺いたいと思います。","respondent":"篠田学務課長、工藤指導課長","answer":"私どももできるだけそういう対応は取っていきたいとは考えているところですけれども、先ほど委員からご指摘のあった第二延山小学校や小山小学校というのが、実は改築が済んでしまっている学校という特殊要因がございまして。区で少人数指導を進める、また、あるいは教科担任制を進めるために区費講師として任用している者は５９名です。","voiceIndex":356,"id":"exchange-157"},{"speaker":"安藤委員","kind":"質問・要望","question":"こうした費用と人材措置をさらに強めた上で、区独自にクラスの規模を減らすということのために充てるべきだと私は思います。伺いますが、少人数学級を見据えて、また現在の加配や区独自教員なども活かし、区独自で学級規模を減らすことを目標にして、教室の増設、学校の増設、教員の増員を検討するよう求めますが、いかがでしょうか。","respondent":"篠田学務課長、工藤指導課長","answer":"ですので、そうなりますと当然、学校の環境が悪化するといったこともありますし、委員から学校の増設というお話もございましたけれども、学校を増設するにあたっては、１つの小学校を造るには、最低でも七、八千平米の土地が必要ですし。先ほど報告いたしました、区でつけています講師や、少人数指導また教科担任制を推進する上での取組みは、引き続き進めていきたいと考えています。","voiceIndex":359,"id":"exchange-158"},{"speaker":"安藤委員","kind":"質問・要望","question":"コロナ禍を経て、大きく考え方も変わってきております。子どもたち第一に、ぜひ少人数学級に、区として前進していただければと要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":362,"id":"exchange-159"},{"speaker":"たけうち委員","kind":"質問・要望","question":"私からは、３５５ページ、生徒指導対策費に関連して、また３６６ページ、学校管理費に関連して伺います。それは、５年生と７年生というのは、なぜそうなのかということの理由が分かれば教えてください。予算特別委員会で、会派の委員から、あくつ委員長なのですが、質問させていただきまして、隣の都営住宅との関係で、あそこは台場と言うぐらいですから、非常に海抜が低いという中で、小学校が３階建て。","respondent":"矢部教育総合支援センター長、小林学校施設担当課長、篠田学務課長","answer":"委員ご質問の１番目と３番目についてお答えいたします。１点目、スクールカウンセラーの全員面接です。現在、取付け位置および取付けの方法などを検討しております。今後、都なども含めて協議して、取り付ける方向で考えていきたいと考えています。新型コロナに感染した児童・生徒の数ですけれども、昨日時点で、今、１０名です。学校の数で言いますと５校です。","voiceIndex":364,"id":"exchange-160"},{"speaker":"たけうち委員","kind":"質問・要望","question":"スクールカウンセラーについては、では５年生と７年生、東京都のほうからそういうお話だということ。それで、今回のコロナ禍を受けて、例えば今までの相談の数に比べて今回少し増えてきているのだとか、具体的な数の報告なども取られているのかどうか、分かれば教えてください。都営なので、勝手にできないので、その上で、またさらにやりますということだと思うのですけれど、一応確認させてください。","respondent":"矢部教育総合支援センター長、小林学校施設担当課長","answer":"続きまして、スクールカウンセラーの実施状況ですが、昨年度は５２人の配置で、１万６,５１０件という数字が上がってありますが、４月から６月についてはお子さんがいないということもありまして、ほぼ実績はございません。そのとおりでございまして、今後、取り付けていくよう進めてまいりたいと考えております。","voiceIndex":368,"id":"exchange-161"},{"speaker":"たけうち委員","kind":"質問・要望","question":"スクールカウンセラーについては、よく分かりました。きちんと件数も確認されているということで安心しました。それで、今お聞きしたところですと、５年生・７年生だけではなくて、全校に週１回ですか、配置されているので、５年生・７年生以外のところでも、相談したければ対応できるということですよね。台場小学校は分かりましたので、ぜひとも進めていただければと思いますので、よろしくお願いします。","respondent":"矢部教育総合支援センター長","answer":"思い出づくりのほうは、これまでどおり、学校の工夫を活かしてしっかりと努めていきたいと考えております。","voiceIndex":371,"id":"exchange-162"},{"speaker":"大沢委員","kind":"質問・要望","question":"３５３ページ、教育指導というか、受験指導について伺います。それと、図書館かとは思ったのですけれども、先ほど品川図書館長のお話の中で、青空文庫を利用したことによって、読書をする、何か習慣というか、大いに効果を上げているということなのですが、そこの取組みについて、今、通告した質問の前に聞かせていただきたい。","respondent":"横山品川図書館長","answer":"こちらについては、有識者の呼びかけで、名作を中心に１万６,０００点ほどの、著作権が切れた本等をストックしているもので、こちらは誰でもアクセスできるような状態になっているところなのですが。","voiceIndex":374,"id":"exchange-163"},{"speaker":"大沢委員","kind":"質問・要望","question":"すみません。泉鏡花があったり露伴があったり藤村があったりということで、ここのところはどういうふうに、そういう新聞の記事が載っているわけですから、利用しない手はないと思うのですけれども、今後そこのところをうまく利用しながら、夏目漱石もいっぱい載っていますので、三部作も載っていますので、これは大いに利用していただきたいと思うのですけれどもいかがでしょうか。","respondent":"横山品川図書館長","answer":"」という動画を配信したり、塗り絵とか、それぞれの小さな子どもから取り組めるようなもの、またサイトも青空文庫だけでなく、国際子ども図書館や、福井県立恐竜博物館や、ＪＲ西日本のペーパークラフトなど、いろいろなものを紹介する形で、切り口として、読書ではないですが。","voiceIndex":376,"id":"exchange-164"},{"speaker":"大沢委員","kind":"質問・要望","question":"少しあれなのですけれども、コロナにおいて、中学３年生の受験指導について伺いたいと思いますが、歳入のところで質問させていただきましたけれども、私は、現場、そして生徒、もう一つ、塾ということで、お話を聞いた部分がありまして、これは主観もあるでしょうけれども、大体、今、先生方、生徒も、そのようなことを感じていらっしゃるのではないかと思いまして、一つ一つ伺ったことを。","respondent":"工藤指導課長","answer":"ですから、指導面におきましては、先ほど指摘がございましたように、理科の場合には、一部の単元の中で、さらにその一部を除外するという表記といった、東京都教育委員会からの説明です。ですので、やはりその内容も全て含めて履修をしっかりと行う。","voiceIndex":378,"id":"exchange-165"},{"speaker":"大沢委員","kind":"意見","question":"主人公である生徒の声なのですけれど、９年生。範囲を狭くして受験生の負担を減らした意味がなく、かえって曖昧な範囲をめぐって余計な心配が増えただけだと思う。緊急時だからこそ、範囲を狭くしたのなら、国立・公立・私立で足並みをそろえてほしい」ということで、主人公である受験生の声ですけれども、これについてはどういうふうにお考えになりますか。","respondent":"工藤指導課長","answer":"確かにそのようなお声があるということは認識しているところでもあります。ただ、学校におきましては、指導内容をきちんと定着させるという観点で、生徒に対しても指導して、確実に定着するというところをもって安心していただければと考えています。","voiceIndex":380,"id":"exchange-166"},{"speaker":"大沢委員","kind":"質問・要望","question":"塾なのですけれども、塾は、区の範囲外なのですが、塾の先生、たまたまそこだけだったので、あまり重く捉えていただかなくて結構なのですけれども、都の教育委員会に範囲確認の電話をしてもらちが明かないというようなことなのですが、これはもう結構ですけれども、ぜひとも東京都と、そこのところを密に取っていただきたいと思います。","respondent":"工藤指導課長","answer":"そういったことの関連で、やはり児童・生徒のよりよい成長のためにお互い協力して進めていくということが必要であると。そういった役割というのは、やはり子どもを中心にしてお互い協力していくことだと認識しています。","voiceIndex":382,"id":"exchange-167"},{"speaker":"大沢委員","kind":"質問","question":"ところが、最近というか、もう近年になりますか。最近ということではなく近年でありますが、親と先生がお互いに、何というのでしょうか、干渉するような、干渉し過ぎてしまって窮屈になってしまっているようなところが散見されると、私は感じるところがあるのですけれど、その辺は、現場をご覧になっていて、どういうふうに課長は考えられ、お感じになられているのか、教えてください。","respondent":"工藤指導課長","answer":"ただし、声をかけることは非常に大事であるとか、反応がなくても声かけを続けることが大事であるとか、そういったポイントを絞りながら、つかず離れず、また、つくときはつくと。やはり干渉する度合いなども必要に応じて助言したりして行っているところです。","voiceIndex":384,"id":"exchange-168"},{"speaker":"大沢委員","kind":"意見","question":"まさに私も同感でありますが、近年、やはり携帯電話とか、いろいろな文明の利器のさらなる普及によって、つかず離れずが逆に過干渉になって、子どもも先生方も親御さんも疲れ切っているという部分が大いにあるのではなかろうかと私は思っています。そこで１つ、主人公である子どもたちには、やはり逃げ場が必要だと思うのですけれども、逃げ場について、課長はどのようにお考えになりますか。","respondent":"工藤指導課長","answer":"誰か一人でもつながることが、その子の未来を開くことになると信じて進めていくことだと思ってあります。","voiceIndex":386,"id":"exchange-169"},{"speaker":"大沢委員","kind":"意見","question":"やはり人間である以上、息抜きも必要であると思います。綱を引っ張った状態では、いつかはほころびが出るわけでありますから、そうではなくて、ぜひとも幾らか余裕を持った教育、余裕を持った子どもたちに対する接し方であってほしいし、そういう知識であってほしいと思います。希望で終わらせてもらいます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":388,"id":"exchange-170"},{"speaker":"石田（秀）委員","kind":"提案","question":"先ほど来出ている思い出づくりのことについて、伺いたいと思います。そういうことも含めると、やはり教育委員会の中で提案していくということが必要だと私は思っています。それで、教育委員会に聞くと、いや、まず学校から提案してくれと。これがバス、陸です。だけど、そういうところでやれるというのも１つの提案であって、こういうところをぜひ考えていただきたいと思いますが、ご見解を教えてください。","respondent":"矢部教育総合支援センター長","answer":"現在、学校では、コロナ禍の中で感染予防対策を講じながら、子どもたちの学びの保障、不安やストレスへの対処に努めております。そのような中で、移動教室などの行事はほとんどが中止となっており、６年生の今後の支援は特に大切であると認識しています。","voiceIndex":390,"id":"exchange-171"},{"speaker":"石田（秀）委員","kind":"提案","question":"今言ったように、学校が相談するのではなくて、教育委員会が、こういうことがあるから、予算もあるから、やってあげたらと言ってやらないと、では提案しろと各学校にみんな言って、「こういうことをやってよ」と言うのか。できない。そこの考え方を変えてくれという質問をしているので、もう一回答弁をお願いします。","respondent":"中島教育長","answer":"まさに、あと残り半年の中で、教育委員会が全ての子どもたちを集めて何かをするなどということは、先ほどもお話がありましたように、なかなか今、現状としては難しい。しかしながら、それぞれの学校の単位で実施できるものというのは、幾つか出てくるのではないかと考えます。","voiceIndex":392,"id":"exchange-172"},{"speaker":"石田（秀）委員","kind":"提案","question":"ぜひよろしくお願いします。そういうことで、各学校もそういうメニューがあれば提案できると思いますので、ぜひそういうところに予算をつけていただいて、集大成の部分で子どもたちに何かの行事をやれる。それはぜひお願いしたいと思いますので、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":394,"id":"exchange-173"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1494#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":128446,"voices":395}},{"id":"r02-20201016-4","meetingId":"r02-c-settlement","date":"2020年10月16日","dateIso":"2020-10-16","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時１８分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を115件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"湯澤副委員長","kind":"質問・要望","question":"発生が確認されてから約１年が経った今でもいまだに有効とされる治療法は模索中であり、収束の見通しが立つまでウイルスとの戦いを続け、乗り越えていかなければなりません。我々品川区議会自民党は、これまで数回にわたり濱野区長へ緊急政策要望を行い、多くの要望に応えていただきました。併せて、区は今後どういった支援策を行っていくのかも教えていただきたいと思います。","respondent":"久保田地域振興部長","answer":"融資あっ旋「経営変化対策資金２０２０」につきましては、区内中小企業の経営基盤の下支え支援としまして、今年度末までは継続して実施してまいります。次年度につきましては、新型コロナウイルス感染症による経済状況への影響などを考慮し、検討してまいります。","voiceIndex":2,"id":"exchange-001"},{"speaker":"湯澤副委員長","kind":"提案","question":"国や東京都でも支援は多く行っておりますが、失業者を出さない、倒産をさせないためにも、可能な限り区独自の支援を引き続き行っていただきたいと思いますので、ぜひご検討をお願いいたします。支援を受けたいと思ってもよく分からないという方がいらっしゃいました。区民により分かりやすいよう、フローチャートやチャットボットの活用を提案いたしますが、ご見解をお知らせください。","respondent":"久保田地域振興部長","answer":"フローチャートやチャットボットの活用につきましては、区の事業でも取入れているものがありますので、引き続き研究してまいりたいと考えているところです。","voiceIndex":4,"id":"exchange-002"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"どれだけ役立つ支援でありましても利用されなければ役に立ちませんので、ぜひ支援を必要としている区民に分かりやすく示せるよう努力していただきたいと要望します。ＰＣＲ検査の充実を図るため、会派から要望しておりました品川区ＰＣＲ検査センターが５月１２日に区役所第二駐車場内に設置され、ＰＣＲ検査専門の施設として、病院内での感染リスクの軽減にも役立っていると思います。","respondent":"福内品川区保健所長","answer":"濃厚接触者と判定された場合は、保健所からの連絡に基づきＰＣＲ検査を受けるとともに、検査で陰性であっても感染の可能性が否定できないため、新型コロナウイルス感染症の潜伏期間にあたる１４日間の自宅待機をお願いしています。","voiceIndex":6,"id":"exchange-003"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"今お話しいただいたような新型コロナウイルス感染症への新しい取組みについて、区民はどこで情報を確認すればよいのでしょうか。新型コロナウイルス感染症に対する不安から誰かを傷つけてしまったり、命を絶ってしまうケースがあると報告されておりますが、心のケアについても対策があれば教えていただきたいと思います。","respondent":"福内品川区保健所長","answer":"心のケアについては、自殺対策も含め、日頃の普及啓発を継続的に実施していくことが重要と考えています。","voiceIndex":8,"id":"exchange-004"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"品川区ＰＣＲ検査センターの設置期間は来年３月までとなっておりますが、収束のめどが立たないような場合には設置の継続を要望したいと思いますが、いかがでしょうか。品川区においても既に１０月１日より、６５歳以上の方は無料で優先的に受けられるとされておりますが、周知は徹底されておりますでしょうか。区民に対する供給量は十分であるとお考えでしょうか。ご見解をお知らせください。","respondent":"福内品川区保健所長","answer":"ＰＣＲ検査センターの継続についてですが、今後につきましても感染状況に応じ、必要な方に必要な検査を迅速に対応できるよう、感染状況や区内の医療機関での検査状況、実施状況等も勘案しつつ、医師会と協議を行ってまいります。","voiceIndex":10,"id":"exchange-005"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"義務教育過程におけるオンライン教育について、お尋ねいたします。ＧＩＧＡスクール構想では、当時生徒１人１台の端末配備を２０２３年度中に計画していましたが、文部科学省より新型コロナウイルス感染症緊急経済対策の一環として、２０２０年度中の配備と大きく前倒しすることとなり、我が会派からもタブレットの早期確保、Ｗｉ－Ｆｉ機能の拡充、周辺機器の早期整備を要望してまいりました。","respondent":"齋藤教育次長","answer":"オンライン授業の構想ですが、同時双方向性を最大限活用し、再度の学校休校となった場合でも学びの保障に努めるほか、病気や不登校の児童・生徒に対してもオンデマンドで学習動画を配信するなど、全ての児童・生徒が一人も取り残されることがなく。","voiceIndex":12,"id":"exchange-006"},{"speaker":"湯澤副委員長","kind":"質問","question":"推進校や教員同士の会議などで既にＺｏｏｍを活用しているとお聞きしましたが、通信が途切れるなど今後の課題となるような事例はなかったでしょうか。併せて、今月新型コロナウイルス感染症による学年閉鎖をされた学校があり、対象となった生徒たちにはオンライン授業を行ったと伺いましたが、授業は不具合なく行えたのでしょうか、お知らせください。","respondent":"齋藤教育次長","answer":"今後のスケジュールですが、当初６年生・９年生は１２月から、その他の学年は２月中の配付を予定しておりましたが、配送に課題があり、６年生・９年生の配付が年明けになる可能性もあります。９年生には当初の計画どおり配付できるよう調整しています。","voiceIndex":14,"id":"exchange-007"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"特に要望の強かった受験を控える９年生、そして６年生などに対して優先的に取組んでいただけたことには本当に感謝申し上げます。Ｚｏｏｍによる様々な課題に関しましてはしっかりと解消し、今後につなげていっていただきたいと思います。オンライン環境についてですけれども、事情によって家庭内の通信環境が整えられない世帯に対して、通信費用を含めた支援を要望いたします。","respondent":"齋藤教育次長","answer":"塾に通うことなく、これまで以上に学習の定着が図れるものと考えております。保護者へのＺｏｏｍの指導ですが、使い方、ルール、トラブル対応のマニュアルを提供して丁寧にご説明するほか、ＺｏｏｍをＰＴＡ活動でご利用いただけるよう、ＰＴＡとの連携を深めてまいります。","voiceIndex":16,"id":"exchange-008"},{"speaker":"湯澤副委員長","kind":"質問","question":"新型コロナウイルス感染症により在宅避難を選択し、食料や簡易トイレなどを消費してしまった場合は、どのようにすればよいのでしょうか。し尿などの不衛生なごみはどこに廃棄すればよいのでしょうか。そして、新型コロナウイルス感染症陽性者や経過観察中の方は、避難所に避難をしてよいのでしょうか。それぞれお知らせください。","respondent":"滝澤災害対策担当部長","answer":"避難所の在り方について、ご説明申し上げます。","voiceIndex":18,"id":"exchange-009"},{"speaker":"湯澤副委員長","kind":"質問","question":"品川区においてそのような心配はないでしょうか。７年前の本日、大島では台風による甚大な被害がもたらされました。例えば企業、お寺、神社、ホテル・旅館、高校といった耐震性の高い施設の管理者と協定を結び、災害時には避難所として活用させてもらうことも、ウィズコロナ時代の避難所の在り方ではないかと考えますが、区の見解をお知らせください。","respondent":"滝澤災害対策担当部長","answer":"併せまして、帰宅困難者の一時滞在施設として利用する事業者においても避難所として利用できないかということで調整をしておりまして、引き続き避難所の拡大について検討してまいりたいと思います。","voiceIndex":20,"id":"exchange-010"},{"speaker":"湯澤副委員長","kind":"質問","question":"ホテルや企業、そしてお寺などともそういった協定を結んでおられるということでありますが、区内には耐震性の高い施設がまだまだたくさんありますので、発災時に避難所難民が出ないように、区民の生命を守る避難所、避難場所の充実に前向きな検討をお願いいたしまして、私からの質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-011"},{"speaker":"鈴木（真）委員","kind":"質問","question":"私からは、まず、長期基本計画についてお伺いします。その中で、品川区にとっては長期的な視点による施策の推進も重要な問題であります。長期基本計画が本年４月からスタートしました。品川区基本構想に掲げた「輝く笑顔住み続けたいまちしながわ」に向けて策定されたこの新長期基本計画の特徴と、今後の区政課題について、改めてお伺いをいたします。","respondent":"堀越企画部長","answer":"総論部分を新設いたしまして課題ですとか視点などの大きな考え方を明示するとともに、計画体系といたしまして、区民の生活に根差した分かりやすい政策分野として、地域、人、安全の３つを掲げ、それぞれ連携して取組むことで。","voiceIndex":24,"id":"exchange-012"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"人口も、今お話がありましたが、ここ２か月品川区は多少減少しております。そのような状況が出てきているし、一方で９月補正によりまして、品川区の予算も約２,５０３億円という大きな金額になってまいりました。通常であれば実施計画に基づいて予算編成をされていくわけですが、実施計画がまだできていない中で、来年度予算に向けてはどのように編成していくのか、その点についてもお聞きしたいと思います。","respondent":"堀越企画部長","answer":"その内容ですが、長期基本計画の実現に向けて、重点的に実施する事業を示すものとして策定したいと考えてございまして、内容については、やはり大きな方向性ですとか有効性等の進捗管理を行いながら推進するものと捉えてあります。","voiceIndex":26,"id":"exchange-013"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"今、お話しいただきましたように、方向性の中で災害対策とかオリンピックということが重点項目に出てくると思うのですが、もちろん区内の皆様の生活の安定、この辺を強調した予算を作っていっていただきたいと考えています。その辺について、両面でのお考えを教えてください。","respondent":"堀越企画部長","answer":"長期基本計画と言ってみれば対になっているものというのでしょうか、そういった考え方でやっていきたいと思ってございまして、予定といたしましては、やはりこれも新型コロナウイルス感染症の状況を見ながら実施計画の策定作業をしっかりと再開し。","voiceIndex":28,"id":"exchange-014"},{"speaker":"鈴木（真）委員","kind":"質問","question":"来年度に向けてですが、先ほどお話がありましたようにオリンピックという一大イベントもこれから見込まれております。その中で、やはり新型コロナウイルス感染症との戦いというのは区政の最大の関心事になると思います。長期基本計画に関する質問の最後にあたりまして、今後の区政運営に向けて区長のお考えをお聞きしたいと思いますが、いかがでしょうか。","respondent":"濱野区長","answer":"したがいまして、この新しい長期基本計画を着実に推進することが大事なことでありまして、そのためにも限りある財源を最大限に有効活用して、区民が求めておられる大切なサービスを実施していくことが求められていると考えています。","voiceIndex":30,"id":"exchange-015"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"次の質問に移っていきますが、その施策の中で、まず障害者施策についてお伺いしていきたいと考えています。障害者施策の拠点施設として、昨年１０月に障害児者総合支援施設「ぐるっぽ」が開所しました。改めて障害者施策についての区のお考えと、品川児童学園を障害児者総合支援施設とした目的について、お伺いをいたします。","respondent":"伊崎福祉部長","answer":"そのために、障害者の方のライフステージを通して総合的・継続的な支援を実施し、障害者の方が住み慣れた地域で安心して暮らし続けられるよう、施策を進めているところです。","voiceIndex":32,"id":"exchange-016"},{"speaker":"鈴木（真）委員","kind":"質問","question":"基本方針として、ライフスタイル、総合的・継続的な支援というお話がございました。その辺につきまして、区のお考えをお聞きしたいと思っています。職員の方はいろいろご苦労もあると思うのですが、障害者施策を推進する上で、担当者の方というのはどのように現場を体験しているのか、その点についてもお聞きしたいと思います。","respondent":"伊崎福祉部長","answer":"障害児者総合支援施設は、地域生活支援拠点として、障害児者の地域生活を総合的に支援する機能を持つ圏域での中核となる施設です。区内の事業所との連携を密にして、地域全体の福祉サービスの向上を図ることが重要だと考えております。","voiceIndex":34,"id":"exchange-017"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"施設関係ですが、以前の委員会とかでもいろいろとお話をお聞きしたし、今のお答えの中にも出てきていたと思うのですが、障害児者総合支援施設は、地域生活支援拠点に求められる機能についての整備・充実を図っていくということで今までお話しいただいております。","respondent":"伊崎福祉部長","answer":"しかしながら、地域生活支援拠点としまして、今後も増え続ける障害者の高齢化・重度化、それから医療的ケアへの対応、親亡き後を見据えた相談支援の充実、緊急時の受入れ対応、専門的人材の育成等の機能を持っていただきたいと考えております。","voiceIndex":36,"id":"exchange-018"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"新しい指定管理者がこれから選定されるわけですが、今、３つの法人が別々に指定管理を受けている中で、今度は一つの法人になると。ですから、全く新しい法人に変わってしまう、新しい事業者に変わってしまうわけですね。選定にあたりましては、その辺も含めて公平な視点を活かしていっていただきたいと思いますので、その辺の区としてのお考えについてお聞きしたいと思いますが、いかがでしょうか。","respondent":"伊崎福祉部長","answer":"ですので、これから公募するところですが、施設、事業ともに一体的に管理運営ができる体制としてまいります。利用者につきましては、相談から支援まで、総合的・一体的なサービスの提供をできる体制とすることで、より利用しやすい施設になるよう改善を図ってまいります。","voiceIndex":38,"id":"exchange-019"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"障害者施設の拠点として、例えばボランティアの育成などにも努めていっていただきたいと思うのですが、その辺についてのお考えはいかがでしょうか。この点につきましても強く求めてまいりますが、また医療的ケアという点も進めていっていただきたい、医療面の充実も図っていただきたいと思いますが、この点についてもお考えをお聞きしたいと思います。","respondent":"伊崎福祉部長","answer":"障害児の方の早期発見・早期療育につきましては、引き続き運営事業者等と協議をしながら、改善を図れるよう取組んでまいります。さらに医療的ケアの充実につきましても、施設において医療的ケアの対応ができるよう、運営事業者の支援をしてまいります。","voiceIndex":40,"id":"exchange-020"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"この施設を活用していただいて、障害者施策をどんどん進めていっていただきたいと思いますので、その点も要望させていただきたいと思います。障害者施策の質問の最後にあたりまして、就労支援関係についてお聞きしたいと考えています。一般的に解雇という問題も出ているので一概には言えない問題ですが、品川区の中で障害者の解雇という問題が出ているかどうか、その点についてまず１点教えてください。","respondent":"伊崎福祉部長、榎本総務部長","answer":"今後も就労を希望する障害者の方の就労機会の拡大と定着が図れるよう、障害特性に応じた多様な就労形態を検討するとともに、民間企業に対して障害者の雇用拡大に向けて、障害者理解の促進を進めていく、求めてまいります。今後の方策として、もちろん特別区選考での採用を進めていくのですけれども、それ以外に、今国においてチャレンジ雇用という制度を活用しているものがありまして、その点を研究しながら。","voiceIndex":42,"id":"exchange-021"},{"speaker":"鈴木（真）委員","kind":"質問","question":"それと、その先のチャレンジ雇用のお話もございましたけれども、品川区でチャレンジした３年間を越えた後の就労先の確保についてのお考えについて、もう一度お答えをお願いしたいと思います。","respondent":"榎本総務部長","answer":"それと、特別区制度の採用は、勤務時間が３８時間４５分と長い採用時間になりますので、それだとちょっと障害者の方の特性を考えると難しいという場合には。","voiceIndex":45,"id":"exchange-022"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"その点を目指して、これからの施策の展開をよろしくお願いしたいと思います。３点目、最後に広町地区のまちづくりについてお伺いしていきたいと考えています。現在の検討状況、また今後のスケジュール感についてお聞きしたいと考えています。特にＪＲ東日本の建築計画に関するスケジュールなども可能な範囲でお答えいただきたいと思いますが、よろしくお願いいたします。","respondent":"末元都市整備推進担当部長","answer":"ＪＲ東日本の建築計画についてですが、具体的な計画はＪＲ東日本の社外秘の情報となるため差し控えしますが、都市計画手続きに必要な地元説明会の開催に加え、建築物の規模によっては環境アセスメントの調査計画書の縦覧や説明会の実施など。","voiceIndex":47,"id":"exchange-023"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"事業計画は、ＪＲ東日本の問題もありますので、その辺は了解しますが、なるべく早く皆様に周知できるような形をとっていただきたいということを要望しておきます。先日大井町駅周辺地域まちづくり方針の素案が示されましたが、これと広町地区の整備推進の関係、その推進とともに他の地区のまちづくりへの影響についてもお考えをお聞かせください。","respondent":"末元都市整備推進担当部長","answer":"本方針決定後、これを踏まえ、検討が進んでいる広町地区の整備を先行し、その他の大井町駅周辺各地区については、まちづくりの検討熟度に応じて段階的に整備を進めていくものと考えております。","voiceIndex":49,"id":"exchange-024"},{"speaker":"鈴木（真）委員","kind":"意見","question":"最後に、広場にはバス停も作っていくということですが、その役割分担、大井町駅の東口、西口の関係についてお答えをお願いしたいと思います。","respondent":"末元都市整備推進担当部長","answer":"現在バス路線が大井町駅に入っておりますが、具体的なバス事業者との調整については、今後事業の進捗に応じて協議を進めていく予定です。既存バスの乗り入れですとか、大崎駅からの長距離バス乗り場の可能性も含めて協議してまいります。","voiceIndex":51,"id":"exchange-025"},{"speaker":"せお委員","kind":"質問","question":"テーマは新型出生前診断における支援について、児童発達支援センターについて、就学相談について、３点を順次伺います。新型出生前診断における支援について伺います。昭和大学病院産婦人科診療科長の関沢明彦教授からは、現在カウンセリングなどを実施していない営利目的のＮＩＰＴ無認可施設が約１３０カ所あると言われているという現状を伺いました。そこでお聞きします。２点お聞かせください。","respondent":"福内品川区保健所長","answer":"保健センターでは、子どもを安心して産み、育てるために、妊婦全員を対象として、妊娠期のネウボラ相談事業を実施しています。相談事業では助産師が中心となり、妊娠中の様々な不安にお答えしています。ハイリスクの妊婦に対しては、保健師が妊娠期から支援にあたっております。","voiceIndex":54,"id":"exchange-026"},{"speaker":"せお委員","kind":"質問","question":"委員長の許可を得たので、提示します。こちらのブックレットは、妊娠継続をするときに読んでほしい月編と、赤ちゃんとお別れする選択をするときに知っておいてほしいことが書かれている星編に分かれています。そこで質問します。これらを知る機会は現在区で設けているでしょうか。ですから、妊娠中から子育てまで継続した支援が大切となってきますが、区ではどのように取組んでいくのか、見解を伺います。","respondent":"福内品川区保健所長","answer":"そのため、保健センターではこれまでに助産師、保健師、新生児訪問指導員を対象に、支援者として知っておくべき出生前診断の実際に関する研修を実施しておりまして、今後も様々な機会を活用し、スキルアップを図ってまいります。","voiceIndex":56,"id":"exchange-027"},{"speaker":"せお委員","kind":"質問・要望","question":"次に移ります。ですので、現状を確認させていただきたく質問いたします。品川児童学園にて未就学児が児童発達支援を受ける際、基本的な流れとしては、子ども発達相談室で相談をしてから通園などのサービスが開始されると認識しておりますが、その認識でよろしいのでしょうか。さらに、子ども発達相談室の５か月待ちを解消するために、新しく改善を図った点はありますでしょうか。以上３点、お聞かせください。","respondent":"伊崎福祉部長","answer":"困ったときにはいつでも電話で対応する旨をお伝えしております。","voiceIndex":58,"id":"exchange-028"},{"speaker":"せお委員","kind":"質問","question":"この点は理解いたしました。現在、基本的な通園の基準は何でしょうか。お聞かせください。ふだんは幼稚園・保育園に通って、空いている曜日や時間で児童発達支援を利用するという形を基本にすべきであって、つまり並行通園が一般的であるべきですが、品川区の見解をお聞かせください。","respondent":"伊崎福祉部長","answer":"区といたしましては、必要な児童に必要な療育が受けられるよう対応していくべきと考えており、運営事業者に対して、並行通園の実施の検討を進めてもらっているところです。","voiceIndex":60,"id":"exchange-029"},{"speaker":"せお委員","kind":"質問","question":"次に移ります。最後に就学相談についてお聞きします。この一連の流れは果たして相談なのでしょうか。そこで質問します。さらに、就学相談とはそもそも何をする場所かという説明は、いつどのように行っているのでしょうか。その中で、区立学校の説明だけではなく、都立特別支援学校、こちらは判定で支援学校と言われることもありますので、特別支援学校の説明もされているのか、３点お聞かせください。","respondent":"齋藤教育次長","answer":"就学相談の説明につきましては、次年度に公立学校への入学、進学を控え、通級指導学級の利用や特別支援学級の在籍、または都立特別支援学校への入学を検討したいご家族に対して、必要な情報を６月から区のホームページや広報で掲載してお知らせいたします。","voiceIndex":62,"id":"exchange-030"},{"speaker":"せお委員","kind":"質問","question":"そのアンケートの結果を踏まえて、ここから３点質問します。就学先を決定する上での適切な情報提供やご案内はどのようにされていますでしょうか。そして、就学相談中には通常学級や支援学級の見学はもちろんのこと、希望するご家族が必ず体験授業をできるように整え、その案内も必ずすべきだと考えますが、見解をお聞かせください。","respondent":"齋藤教育次長","answer":"情報提供についてのお尋ねですが、まず、心理検査を未実施のお子さんの場合には事前に検査の内容をご案内し、実施後に臨床心理士から結果の説明をいたします。","voiceIndex":64,"id":"exchange-031"},{"speaker":"せお委員","kind":"質問","question":"最後にお聞きいたします。さらにアンケートにおいて、「就学相談によって悩みや不安は解消されましたか」の質問には、約１０％の方が「悩みや不安は解消された」、約４０％の方が「解消されてはいないが、自分の悩みは伝えられた」とする一方で、約３５％の方が「悩みや不安が全く解消されなかった」、約１５％の方が「悩みや不安について話をする機会がなかった」と答えています。","respondent":"齋藤教育次長","answer":"お子さんの就学先は最終的には保護者で決定していただくものですので、相談の結果や理由を書面で連絡することはしておりませんでしたが、今後もお子さんやご家族に寄り添った対応の在り方について検討してまいります。","voiceIndex":66,"id":"exchange-032"},{"speaker":"せお委員","kind":"意見","question":"今のご答弁にも環境が大きく変わるところだというお話がありましたが、お子さんにとってライフステージが大きく変わる節目の段階であって、小学校に入学する場合は、それが初めて変化を経験する場所かもしれません。だから悩むのです。ご家族の考え方やライフスタイル、状況に寄り添い、子どもが幸せに過ごせる場所を一緒に考えていただけるような就学相談となり、そのような品川区となることを望みます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":68,"id":"exchange-033"},{"speaker":"渡部副委員長","kind":"質問","question":"せお委員に引き続き、総括質疑を続けます。初めに、本年実施の国勢調査について伺います。今年は５年に一度実施される国勢調査の年で、区民の皆様にご協力いただいているところです。大正９年の第１回調査から数えて２１回、１００年の節目を迎えます。品川区の国勢調査の結果、人口世帯の実績を教えてください。住基人口と国勢調査によって得た結果を比べての違いについてもお聞かせください。","respondent":"久保田地域振興部長","answer":"例えばですが、進学のために上京した学生が、様々な事情により住民票を移していないといったことが考えられるところです。","voiceIndex":70,"id":"exchange-034"},{"speaker":"渡部副委員長","kind":"確認","question":"近年は大型マンションへの対応やプライバシー意識の高まりなどがあって、今回に至っては新型コロナウイルス感染症の流行下での調査ということで、調査実施に際し、区も調査員の方も様々な苦労があったのではないでしょうか。調査員の方々からも様々な声は伺いました。今回の国勢調査のボリュームを確認させてください。調査区の数はどのぐらいありましたでしょうか。調査員の確保について伺います。","respondent":"久保田地域振興部長","answer":"調査開始時の実数につきましては、町会・自治会からは１,８５０人、マンション管理会社や管理組合、社会福祉施設からは９０人、区登録調査員が１２２人、公募が４２人となり、このほかに業務委託契約などが１８人いらっしゃいました。","voiceIndex":72,"id":"exchange-035"},{"speaker":"渡部副委員長","kind":"質問","question":"町会の皆様に感謝するとともに、大変うれしく思います。さて、ここ数回は調査ごとに変更点があるように思います。前回調査と比較し大きく変わった点や、区として工夫を凝らした点は何かございましたでしょうか。新型コロナウイルス感染症対策で調査員の負担軽減策も大変重要であったと考えますが、どのような対策を取られましたでしょうか、教えてください。","respondent":"久保田地域振興部長","answer":"変更点についてですけれども、今回の国勢調査は大規模調査にあたりまして、前回の調査と比べまして世帯に関する事項が２つ増えてあります。具体的には在学、卒業等の教育状況、就業・通学地までの利用交通機関という項目が増えております。","voiceIndex":74,"id":"exchange-036"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"調査員の方に対する対策を相当取られていたということで安心いたしました。これに限らず万全の対策をしっかりと取っていただいて、この取組みを引き続き進めていただくよう要望いたします。調査票による回答数、インターネットによる回答数、未回答数はどのようになっておりますでしょうか。未回答者へのアプローチはどのようになさっているでしょうか、教えてください。","respondent":"久保田地域振興部長","answer":"広報しながわ１０月２１日号や区ホームページにおいても、回答への協力をお願いしたところです。","voiceIndex":76,"id":"exchange-037"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"今お伺いしていて、回答率が相当いいようで、この件につきましては安心いたしました。時代の流れでしょうか、インターネット回答というのも前回と比較して伸びているし、次回以降の調査ではさらなる伸びがあるのかと考えています。私自身、この国勢調査というのが国の基幹調査として大変重要であると考えています。最後に、区としてこの国勢調査の大切さや重要な点について教えていただきたいと思います。","respondent":"久保田地域振興部長","answer":"は今回の国勢調査を着実に実施するとともに、国勢調査を含めました各種統計調査を正確かつ確実に進めてまいりたいと考えているところです。","voiceIndex":78,"id":"exchange-038"},{"speaker":"渡部副委員長","kind":"質問","question":"いかんせんまだ中途でありますので、引き続き対応をお願いしたいと思います。次の質問に移ります。行政手続のデジタル化について伺います。区ではこの間、様々な業務改善がなされております。ここから２点伺います。１点目は、地方公共団体のデジタル化で示された、システム等の共同利用の推進の観点から伺います。ここで質問しますが、これらの説明は区でいつ頃国からどのように受けましたでしょうか。","respondent":"堀越企画部長","answer":"このデジタル化の推進のいわゆる標準化に関する国からの説明についてですが、これまで国主催の説明会等が開催された実績はございません。全体的なデジタル庁等の考え方というのは、今、国のほうでも検討が進められております。","voiceIndex":80,"id":"exchange-039"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"２つ目は、行政手続のオンライン化の推進について伺います。区からは、国のマイナンバーカード管理システムのサーバー増強を強く求めていただきたいとともに、４０万人の人口に見合った台数の登録機を区として設置するよう強く要望いたします。ないようであれば、検討を進められたいと考えますが、いかがでしょうか。そして今後発行できるような可能性があるのか、教えてください。","respondent":"堀越企画部長","answer":"そのシステムですが、今申し上げたリプレイスが今月中に完了する予定でございまして、来年の１月より、コンビニ等で設置されたマルチコピー機において戸籍証明書の取得が可能になるような形で、今、鋭意準備を進めているところです。","voiceIndex":82,"id":"exchange-040"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"人事について伺います。新型コロナウイルス感染症による影響、デジタル化により人の手を介さずに行える業務が増えたり、さきのマイナンバーによる行政手続の簡素化、窓口の混雑回避策などによる、今後の人材適正配置について伺います。このような場合に、区役所は急激に業務負担が発生した際の応援体制が組まれているかと思いますが、どのような対応がされましたでしょうか、教えてください。","respondent":"榎本総務部長","answer":"一番多かったのは４月です。その場合の応援態勢ですけれども、新型コロナウイルス感染症の関係で事業等を中止したところがありますので、そういったところで施設を閉じたりとか、そういうところから適宜応援を求めるという形で対応したところです。","voiceIndex":84,"id":"exchange-041"},{"speaker":"渡部副委員長","kind":"提案","question":"今も対策を取られていて、これからも様々な対策を取り続けられるということで、何とかこの混雑解消に努めていただきたいと思います。２つ提案します。この２つを提案しますが、お考えをお聞きするとともに、先ほどお話しいただいた混雑解消の観点から、何かそれ以外、区民サービス向上に向けた取組みがもしおありのようであれば、お聞かせください。","respondent":"久保田地域振興部長","answer":"ＬＩＮＥによる事前入力、自動発行機なども取入れまして、これらの混雑解消への取組みを進めてまいりたいと考えております。","voiceIndex":88,"id":"exchange-042"},{"speaker":"渡部副委員長","kind":"質問","question":"子育て支援、とりわけ乳幼児をお持ちの家庭への支援について伺います。その結果、一人で抱え込んでしまう方もいらっしゃるのではないでしょうか。ここで乳幼児家庭に対する現在の児童センターの利用状況を伺います。区立学校は通常に戻りましたが、児童・生徒の居場所としての役割も制約があると考えますが、バンドやダンスの活動状況と合わせて利用状況をお教えください。","respondent":"柏原子ども未来部長","answer":"児童センターにおける現在の利用状況等です。最初に、乳幼児の部分ですけれども、コロナ禍におきまして緊急事態宣言解除後ですけれども、６月からチャイルドステーション事業をスタートさせました。","voiceIndex":90,"id":"exchange-043"},{"speaker":"渡部副委員長","kind":"質問","question":"大変ですね。ただ、利用したい方も大勢いらっしゃいますので、感染症対策を何とか講じた上で、多くの家庭や児童・生徒が気軽に訪れて活動ができるよう、何か新たなお考え等はないでしょうか。私自身は、公園などを利用した屋外の活動や様々な子育てサークルの方々などを紹介して参加していただく、広げていくなどの必要があるかと考えるのですが、その辺のお考えをお聞かせください。","respondent":"柏原子ども未来部長","answer":"そのほか、子育てサークルというところで、地域のほうで子育てをされている方の交流会というのを来月実施しようというところで検討していますので、そういったところでの交流の場であったり、それぞれの活動の紹介というのはやっていこうと考えていますので。","voiceIndex":92,"id":"exchange-044"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"ぜひいろいろと進めていただきたいと思います。今、子育てサークルというようなことでございましたが、このようなボランティア団体の方々についての支援を伺います。品川区には社会福祉協議会の中にボランティアセンターがありますが、子育て支援において、団体とボランティアセンターとの連携事例やその効果などがもしあるようでしたら、教えてください。","respondent":"柏原子ども未来部長","answer":"こちらは区とも連携してやっているところではありますけれども、子ども食堂を運営している団体、事業者との横のつながりであったり、そういった方々と実際ボランティアをやる方とのつながりという広がりができてきておりますので。","voiceIndex":94,"id":"exchange-045"},{"speaker":"渡部副委員長","kind":"提案","question":"ここからちょっと提案といいますか要望の形になるのですけれども、区内には様々なボランティア団体というのがあって、在宅子育て支援もそうですが、社会福祉協議会と連携して気軽に参加できるボランティアの仕組みというのを新たに構築されていくのがいいのかと、進めていただきたいと望みます。最後に、教育について伺います。この間の学校教育の状況、また家庭における学習について伺います。","respondent":"齋藤教育次長","answer":"学校休校中の特徴的なことのお尋ねですが、１つ目は、区では入学式、始業式をソーシャルディスタンスを確保しながら実施したことです。","voiceIndex":96,"id":"exchange-046"},{"speaker":"渡部副委員長","kind":"確認","question":"何かあった場合は、引き続きよろしくお願いいたします。長い休みの中で、個人の学力差が出たのではないかと心配しています。各家庭での取組みに学校が介入することはなかなかできませんが、実際の状況はいかがだったのでしょうか。学校再開後、学力低下が確認できた児童・生徒に対しては、何かしらのアクションが学校でなされていたのかどうか、教えていただけますか。","respondent":"齋藤教育次長","answer":"ただ、学校再開後に回収した課題や学校再開後の確認テストで学力に課題が見られた児童・生徒には、放課後で個別に指導したり、品川地域未来塾で学習支援をするなど、きめ細かく対応したところです。","voiceIndex":98,"id":"exchange-047"},{"speaker":"渡部副委員長","kind":"質問","question":"再開後すぐ定着度調査をされているというのはすばらしいことだと思います。今後ガイドライン等を作成して運用につかれると思いますが、幾つか伺います。この間のＩＣＴの推進校での取組みを全校で継続すべきと考えますが、教育委員会としてのお考えをお聞かせください。とりわけ先ほどもありましたが低学年が家庭で活用するには保護者の助けが必要になってしまうと思いますが、併せてお聞かせください。","respondent":"齋藤教育次長","answer":"教育委員会といたしましては、保護者に使い方、ルール、トラブル対応のマニュアルを提供するほか、連絡帳機能やＰＴＡ活動でご利用いただけるよう丁寧に説明いたします。","voiceIndex":100,"id":"exchange-048"},{"speaker":"新妻委員","kind":"質問","question":"品川区議会公明党を代表して、塚本よしひろ委員とともに総括質疑を行います。大きく防災とワンストップ窓口について伺います。初めに、風水害と地震がコロナ禍で発生した場合の避難について伺います。昨年の台風１９号で、品川区は自主避難施設を開設しましたが、地震時の避難所である区民避難所へ避難された方がいました。現在までどのように区民への周知が図られたのかお知らせください。","respondent":"滝澤災害対策担当部長","answer":"昨年の台風において課題となりました自主避難施設の区民への周知要領についてですが、昨年度の防災会議において、自主避難施設の定義や役割をお伝えし議論するとともに、区ホームページや広報しながわなどを活用して、避難要領に係る周知・啓発を実施してまいりました。","voiceIndex":105,"id":"exchange-049"},{"speaker":"新妻委員","kind":"質問・要望","question":"ただいま３つの避難所があるということのご説明がありました。しかし、まだまだ区民には周知が足りないと感じております。そこで、自主避難施設、避難場所、避難所とは何かを分かりやすく掲載した冊子やリーフレットなどを作成し、配布することを要望いたしますが、見解を伺います。","respondent":"滝澤災害対策担当部長","answer":"検討内容が整い次第、変更を伴う際は、冊子の作成を含めてあらゆる手段を講じて区民に対し周知徹底を図ってまいります。","voiceIndex":107,"id":"exchange-050"},{"speaker":"新妻委員","kind":"提案","question":"どうぞよろしくお願いいたします。先日の款別審査の土木費でも会派から確認いたしましたが、昨年は１８７万円、本年は４８０万円を予算化しています。そこで、公明党が平成３０年第３回定例会の一般質問で提案している、区が指定している目黒川の氾濫や土砂災害による対象区域において、地震とは別に浸水、高潮、土砂災害を想定した避難訓練の実施を改めて提案いたしますが、それぞれ見解を伺います。","respondent":"滝澤災害対策担当部長","answer":"要支援者以外を対象とした訓練につきましては、先ほど説明をしました区民目線で分かりやすい避難要領の研究と併せて、広域化する風水害避難のための訓練要領について、その実施要領を具体化してまいります。","voiceIndex":109,"id":"exchange-051"},{"speaker":"新妻委員","kind":"提案","question":"それぞれ継続してお願いしたいと思います。次に、マイ・タイムラインについて伺います。新たな生活様式の中でもマイ・タイムラインの周知啓発に努めていただきたいと要望します。そこで、品川区公式ＬＩＮＥの中にある防災についてのコーナーに、マイ・タイムラインを作成できるサイトの東京マイ・タイムラインを分かりやすく掲載することを提案いたします。見解を伺います。","respondent":"滝澤災害対策担当部長","answer":"しながわ防災学校においては、今年度、風水害対応における家庭・区民コースにおいて、マイ・タイムラインの作成を実施予定でありましたが、新型コロナウイルス感染症の影響で中止となりました。","voiceIndex":111,"id":"exchange-052"},{"speaker":"新妻委員","kind":"質問","question":"いち早く対応していただければと思います。次に、避難所について伺います。公明党は、８月に地震の際に避難する区民避難所の視察で御殿山小学校を訪問しました。定期的に行う訓練は防災意識を維持、高めるために重要であり、コロナ禍だからこそ防災訓練を行う必要があると考えます。ウィズコロナ時代の新たな避難所運営を行う地域の声をどう受止め、対応しているのか伺います。","respondent":"滝澤災害対策担当部長","answer":"共助による避難所運営の負担を軽減するために、症状のある避難者など、感染の恐れの高い避難所エリアの運営については、区の職員が実施することを基本に考えており、区の職員に対しては防護服の着脱を含めた感染防止のための訓練を庁内で実施しております。","voiceIndex":113,"id":"exchange-053"},{"speaker":"新妻委員","kind":"提案","question":"品川区においても、しながわ防災体験館で３密を避けるための避難所のイメージを展示するなどの検討をされてはいかがでしょうか。そして、コロナ禍に関するマニュアルの実効性が高くなるよう、防災区民組織や区民がコロナ禍の避難所をイメージできるような動画を作成し、ホームページへの公開や防災体験館での活用を提案いたします。併せて見解を伺います。","respondent":"滝澤災害対策担当部長","answer":"動画の作成についてですが、新型コロナウイルス感染症に対応する避難所訓練を１２月の区内一斉防災訓練で区民避難所において実施する予定でありますので、訓練の実施要領を踏まえて、その際に動画を作成することの可能性についても検討してまいります。","voiceIndex":115,"id":"exchange-054"},{"speaker":"新妻委員","kind":"意見","question":"タブレットにつきましては、ぜひ活用をお願いしたいと思います。９月初旬の台風１０号の発生に伴い、九州地方では親戚や知人宅に加えて、ホテル宿泊で避難する人が多くいました。災害社会工学を専門とし、「釜石の奇跡」で著名な東京大学の片田敏孝特任教授は、コロナ禍における厳重な警戒が呼び掛けられた台風１０号は、住民が避難所以外の選択肢を考えるきっかけになったと言われています。","respondent":"滝澤災害対策担当部長","answer":"区と都の役割としては、区が具体的な宿泊や食事支援の協定を締結する一方、都は利用可能なホテル情報の提供や利用のための相互調整支援を実施するものであります。","voiceIndex":117,"id":"exchange-055"},{"speaker":"新妻委員","kind":"質問・要望","question":"ホテルの活用も有効かと思いますので、また一層の拡充に取組んでいただきたいと思います。ここ数年のそれぞれの利用実績をお知らせいただき、それぞれの利用状況の課題をどう捉えているのか伺います。そして、安心して在宅避難ができるよう、家具転倒防止器具取付助成の対象者拡充や、希望する方へ食器類の飛び出しを防止する器具などの無償提供を求めますが、いかがでしょうか。","respondent":"中村都市環境部長、伊崎福祉部長、滝澤災害対策担当部長","answer":"本事業の実績ですけれども、平成２９年度が２件、平成３０年度が３件、令和元年度が１件となっております。一層のＰＲが課題であると認識しています。周知方法につきましては、広報紙やホームページなどでお知らせをしているところですが、まだまだ行き渡っておりませんので。在宅避難の有効性は、近年クローズアップしてきており、また一方で、区民の居住環境は様々ありますことから、在宅避難を進める上で。","voiceIndex":119,"id":"exchange-056"},{"speaker":"新妻委員","kind":"質問","question":"在宅避難をするため、家庭内での被災をしないという取組み、今後も一層よろしくお願いしたいと思います。次に、行政サービスのワンストップ窓口、書かない窓口についてです。款別審査でも伺いましたが、証明交付窓口のリニューアルをした目的と評価、そして課題をお知らせください。このことによって区民の利便性の向上と負担軽減がどのようにされるのか伺います。","respondent":"久保田地域振興部長","answer":"評価としましては、複数の証明書を一度に取得する場合に、申請書に何度も同じことを書かなくて済むということが挙げられます。課題としましては、知られていないということがありまして、利用頻度が１日に数件程度ということで、さらなる周知が必要であると考えています。","voiceIndex":123,"id":"exchange-057"},{"speaker":"新妻委員","kind":"意見","question":"ＬＩＮＥのサービスがこれから始まると思います。周知も課題ですが、このＬＩＮＥの事業が始まるにあたっての周知、何かお考えがありましたらお知らせください。","respondent":"久保田地域振興部長","answer":"それ以外にも、区ホームページの手続きページやチャットボット経由での紹介など、あらゆる手段を使いまして周知を図っていきたいと考えています。","voiceIndex":125,"id":"exchange-058"},{"speaker":"新妻委員","kind":"提案","question":"伺います。平成２９年予算特別委員会の総括質疑で、私は別府市のおくやみコーナーを紹介し、品川区でも導入をと提案した経緯がありますが、現庁舎において手続きに不慣れな外国人や高齢者の負担を軽減する、また子育て世帯の転入の際には、子どもの申請などに係る手続きの簡素化など、書かない窓口の設置を要望いたします。それぞれ見解を伺います。","respondent":"堀越企画部長","answer":"今後、様々な先行自治体の例も参考にさせていただきながら、現庁舎で対応できる部分というような形にはなりますけれども、具体的な方法について様々検討していきたいと考えているところです。","voiceIndex":127,"id":"exchange-059"},{"speaker":"新妻委員","kind":"質問・要望","question":"現庁舎での行政サービスの向上をもう一歩要望いたしまして、私の総括質疑を終わります。塚本委員に引き継ぎます。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":129,"id":"exchange-060"},{"speaker":"塚本委員","kind":"質問","question":"区議会公明党を代表して、新妻委員に引き続き、総括質疑を行います。初めに、新型コロナウイルス感染症のＰＣＲ検査について質問します。ＰＣＲ検査の受皿が拡大される中、検査のありようについては様々な意見があります。加えて、行政検査とスクリーニング検査について、感染拡大を最小化するために、それぞれの検査をどのような方針で実施することが効果的であると考えているか伺います。","respondent":"福内品川区保健所長","answer":"スクリーニング検査につきましても、地域や施設の感染状況も踏まえ実施することが効果的と考えております。","voiceIndex":131,"id":"exchange-061"},{"speaker":"塚本委員","kind":"質問・要望","question":"区の保健所では、高齢者施設や学校で陽性者が出た場合、今ご説明があったとおり、濃厚接触の範囲を超えて積極的にＰＣＲ検査を実施し、感染拡大防止に努めています。その現状について、区はどのように認識しているか伺います。東京都への要請や各種医療機関への働きかけなど、あらゆる手を尽くして医師免許を持つ職員を確保するよう求めます。区の見解を伺います。","respondent":"福内品川区保健所長、榎本総務部長","answer":"対象が１００名近くなど多い場合は、非常勤医師の活用も含め、２チームの編成が必要となります。保健所の所長以外の医師は保健予防課長１名のため、管理職業務等の合間や休日に対応しており、迅速性の担保が課題となっております。医師の確保の関係です。品川区における医師不足につきましては、十分認識しており、これまでも東京都へ要望してきたところです。今回、新型コロナウイルス感染症への対応にあたり、その必要性をこれまで以上に認識したところであります。","voiceIndex":133,"id":"exchange-062"},{"speaker":"塚本委員","kind":"質問・要望","question":"今の医師不足というか、庁内のＰＣＲ検査は待ったなしの中で、医師の不足ということでの体制確保へのご答弁、総務部長のほうからいただいたということは、ひとつ私としても評価したいというか、品川区保健所だけの問題ではなくて、ＰＣＲ検査体制の行政検査の整備の推進というか強化は全庁的にやっていただきたい部分であるというふうに思っておりますので、今、品川区は、今日のデータで見ると。","respondent":"伊崎福祉部長","answer":"受診後に専門医療機関や区の支援策に適切につながるような認知症ケアパスの仕組みも考えてまいります。さらに、家族、地域へのフォロー体制としましては、認知症カフェをご案内するなど、適切な対応に努めてまいります。","voiceIndex":136,"id":"exchange-063"},{"speaker":"塚本委員","kind":"意見","question":"今、６５歳以上に対しての検査というか、行っていただくというご答弁をいただきました。来年度、迅速にというか、スムーズにこれをスタートできるように、ぜひこの事業の推進をよろしくお願いしたいと思います。令和元年度の区の施設整備の状況を見ると、地域密着型サービス施設等整備費助成は１億４,４７９万円余の決算となっていて、着実に整備を進めていると、このように認識しております。","respondent":"伊崎福祉部長","answer":"重度の方につきましては、認知症デイサービスなどをご利用いただくなど、認知症になっても在宅生活を継続できるよう、サービスの提供に努めてまいります。","voiceIndex":138,"id":"exchange-064"},{"speaker":"塚本委員","kind":"提案","question":"認知症ケアを一層充実させるため、在宅介護支援センターにある総合相談窓口で伴走型で相談者に常に寄り添い、所管をまたぐ様々な相談に応じることができるよう、窓口機能を充実すること、また、地方の施設や遠隔地にいる当事者と家族をつなぐＩＣＴ等の活用、そして支える家族同士の情報交換や悩みを共有するコミュニティの構築、こういったことを提案いたしますが、区の見解を伺います。","respondent":"伊崎福祉部長","answer":"複雑化、多様化する相談に対応するため、在宅介護支援センターや支え愛・ほっとステーションなど、現在ある様々な相談機能を踏まえた上で、重層的な支援体制整備に向けて総合的な相談窓口機能の検討を進めてまいります。","voiceIndex":140,"id":"exchange-065"},{"speaker":"塚本委員","kind":"質問・要望","question":"ぜひ認知症施策の一層の推進をお願いいたしまして、次の質問に移りたいと思います。新型コロナウイルス感染症を想定した新しい生活様式が求められる中、日本社会のデジタル化の後れが顕在化しました。商店街についてです。区は、五反田バレーと商店街の連携も進める中で、ポストコロナを見据えた商店街のにぎわい創出や運営効率化について、デジタル活用による施策をどのように展開するのか見解を伺います。","respondent":"久保田地域振興部長","answer":"しかしながら、商店街では、ＩＴを活用することについての情報が不足しているといった現状がございまして、こうした課題を解決するために、ＩＴツールの試験導入や、また五反田バレーとの連携も進めまして、商店街のにぎわいや運営の効率化を図るためにも。","voiceIndex":142,"id":"exchange-066"},{"speaker":"塚本委員","kind":"質問・要望","question":"教育についてです。品川区は、第２回定例会で成立した補正予算で、学習用タブレット端末２万４,０００台の予算を計上しました。次に、機器の操作などの支援にはＩＣＴ支援員が配置されますが、品川区の教育要領に基づいた単元の中で、一人ひとりに個別最適化された学習を行うためには、授業の組み立て方など、教員の大きな意識改革が必要と考えますが、区の認識を伺います。区の見解を伺います。","respondent":"齋藤教育次長","answer":"授業での活用状況を学校評価に加えることで、十分に検証を図りつつ、活用を推進してまいります。ＩＣＴ推進教員への支援についてのお尋ねですが、各学校では、ＩＣＴ推進教員と学年主任を中心に活用検討組織を立ち上げ、教職員の意欲とスキルアップを図ることを目指しております。","voiceIndex":144,"id":"exchange-067"},{"speaker":"塚本委員","kind":"質問・要望","question":"来年度になるかと思いますが、ぜひ、各学校が同じようにスタートを切れるよう進めていっていただきたいと思います。次に、医療のオンライン化についてです。区は、医療のオンライン化についてどのように考えているのか、見解を伺います。さらに、医療のオンライン化について、区内の医療機関から要望などがあった場合、区として支援の考えがあるか伺います。","respondent":"福内健康推進部長","answer":"今般、初回診療時からのオンライン診療の恒久化について検討が進められており、日本医師会からは、安全性と信頼性を確保するため、かかりつけ医が関わるなど、医師と患者の面識があることを前提にすべきとの考えが示されております。","voiceIndex":146,"id":"exchange-068"},{"speaker":"塚本委員","kind":"質問・要望","question":"行政のデジタル化が求められておりますが、そのためには、なりすましを防止する確かな個人認証システムが必要です。今後、行政機関の個人認証システムは、マイナンバーカードに集約するべきと考えますが、区の認識を伺います。区として今後の行政サービスのデジタル化に伴い、マイナンバーカードと東京電子自治体共同運営サービスをどのように整理していくのか伺います。","respondent":"堀越企画部長","answer":"個人認証の関係等ですけれども、区も行政手続のオンライン化は積極的に進めていきたいというふうに考えているところです。その上で、やはりなりすましの防止、セキュリティ対策をしっかりと構築していかなければならないと思ってあります。","voiceIndex":148,"id":"exchange-069"},{"speaker":"塚本委員","kind":"質問・要望","question":"デジタル・ディバイド解消のため、例えば品川区のほぼ全域に張り巡らされている品川ケーブルテレビの通信インフラを活用して、難しい技術を単純な操作で使えるよう、情報弱者の立場に合わせたインターネット環境の提供など、思い切った施策を検討していただきたいのですが、区の見解を伺います。そのために、権限と実効性のある体制をつくり、全庁的な検討を開始するよう求めます。区の見解を伺います。","respondent":"堀越企画部長","answer":"今ご質問いただいていますＩＴツールを活用した形でのワンストップを図っていくという点。それから最後に、やはり各部、職員がしっかりと連携して対応していくというような多角的な視点からしっかりと検討に努めていきたい、このように考えているところです。","voiceIndex":150,"id":"exchange-070"},{"speaker":"塚本委員","kind":"質問","question":"コロナ禍を乗り越えた先に品川区が先進的なオンライン・シティとなることを願い、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":152,"id":"exchange-071"},{"speaker":"おくの委員","kind":"質問","question":"どうぞよろしくお願いいたします。私からは、この３月末から本格運用が始まり、区民の暮らしを大きく変えている羽田新飛行ルートについて質問いたします。騒音の問題です。このような受止めでいいのでしょうか。７７.１デシベル、７９デシベルという騒音は、住民にとってあまりにもうるさい騒音です。想像していた以上にうるさい。そこで伺います。いかがでしょうか。これもいかがでしょうか。伺います。","respondent":"中村都市環境部長","answer":"現在までに電話やメールなど様々な方法で区民の皆様から影響についてご意見をいただいておりまして、これも国に伝えているところです。引き続き、区としまして、区民の皆さんの意見をしっかりと聞き、区民の立場に立って国に対し必要な対応を求めてまいるという考えです。","voiceIndex":154,"id":"exchange-072"},{"speaker":"おくの委員","kind":"質問・要望","question":"ぜひ寄り添った対応をしていただきたいと思います。２０１８年にＷＨＯは環境騒音ガイドラインを改定して、航空機騒音について、人の健康を守るために、１日平均の騒音指標の１つであるＬｄｅｎを４５デシベル以下にすることを強く勧告いたしました。そこで伺います。品川区では、騒音測定において、このＬｄｅｎの値をなぜ出さないのでしょうか。出すべきではないでしょうか。伺います。","respondent":"中村都市環境部長","answer":"Ｌｄｅｎですけれども、健康の保護に資する基準というところで、年間Ｌｄｅｎによって判断されるものですけれども、区では、現在、騒音の最高値、発生回数等を公表しております。ただ、Ｌｄｅｎにつきましても、今後、年間Ｌｄｅｎについて公表を予定しております。","voiceIndex":156,"id":"exchange-073"},{"speaker":"おくの委員","kind":"質問・要望","question":"Ｌｄｅｎの値、区民の健康という非常に重要な要素に関するものです。ぜひ積極的に取入れていっていただきたいと思います。地域からも驚きと不安の声が上がっております。そこで伺います。そして、受けていなかったのなら、区も区民も全く知らされてこなかった重大な事実が新たに判明したわけですから、国に即刻運用中止と、改めて説明の場を設けさせるべきだと思いますけれども、いかがでしょうか。伺います。","respondent":"中村都市環境部長","answer":"自衛隊輸送機が飛行したですけれども、新飛行ルートの事前の説明では、飛ぶとも飛ばないとも説明はなかったという認識です。","voiceIndex":158,"id":"exchange-074"},{"speaker":"おくの委員","kind":"質問","question":"事前に説明を受けなかった以上、やはり全く新しい事態が展開しているわけです。民間機と自衛隊機は全く違うものを運びますし、違う飛行機が飛ぶわけです。全く新しい事態が展開した以上、新しい事態の展開として少なくとも説明の場は設けさせるべきだと考えますけれども、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":162,"id":"exchange-075"},{"speaker":"おくの委員","kind":"質問・要望","question":"新しい事態に対する新しい説明、強く求めていただきたいと思います。新ルートの固定化回避を掲げる検討会が、結局、新ルートの固定化を招くという問題について伺いたいと思います。２番目、そうであるなら、この検討会は、区民にとって新ルートの固定化ということではないでしょうか。３番目、やはり中止またはルートの変更を国に求めるべきだと思うのですが、いかがでしょうか。以上３点、伺います。","respondent":"中村都市環境部長","answer":"ただ、この国が行う検討については、先ほども申し上げました区民の負担を可能な限り軽減していただく、こういった方向性で取組んでいただくというところは、区としてぶれずに結果を注視していきたいというふうに考えております。","voiceIndex":166,"id":"exchange-076"},{"speaker":"おくの委員","kind":"質問・要望","question":"結局、今のご答弁からも、区としてもこの固定化回避は現在の都心ルートを前提にしたものであると。次にいきます。伺います。品川区の住民に、新ルートへの賛否を聞かれたことが一度でもあったでしょうか。いかがでしょうか。それからもう１つ、最後に伺います。区として、住民投票を求める住民運動をどのように受止めていますか。伺います。","respondent":"中村都市環境部長","answer":"区も同席しましたけれども、国からの直接の回答による活発な質疑応答が行われたと記憶をしています。条例制定に向けた署名運動につきましては、自治法上も認められた権利ですので、区としましても法令に基づき厳正に対応してまいりたいと考えております。","voiceIndex":168,"id":"exchange-077"},{"speaker":"おくの委員","kind":"質問・要望","question":"結局、この条例制定運動も地元の理解を得て進めると国自らが言いながら、地元の理解を得られないまま進めた点から、こういう自体に立ち至ったと。新ルートへの賛否を聞かれたことが結局は一度もなかったという事態から生じたことだと私は思います。新ルートによって区民は日々の暮らしとその環境を壊され、また、健康も蝕まれております。新ルートの中止、撤回、強く求めて私の総括質疑を終えます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":170,"id":"exchange-078"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"続きまして、日本共産党の総括質疑を行います。感染拡大を抑えるためのＰＣＲ等検査の抜本拡充と、深刻な経済危機から区民の暮らしを守る対策を求めて質問します。それから、品川区のＰＣＲ検査体制について伺います。ＰＣＲ検査センター、帰国者・接触者外来での１日のＰＣＲ検査可能数、医師会を通じて東京都と契約しているＰＣＲ検査可能な医療機関の数と、そこでの検査可能数をそれぞれ教えてください。","respondent":"福内品川区保健所長","answer":"４月、７月、８月、９月、１０月の感染者数、ＰＣＲ検査数、陽性率です。４月は、感染者数１３９人、検査数５１３件で、陽性率２７.１％です。７月は、感染者数２３３人、検査数２,６４１件、陽性率８.８％。８月は、感染者数２７０人、検査数４,７１９件、陽性率５.７％。","voiceIndex":172,"id":"exchange-079"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この抜本拡充こそ必要だと思います。さらに、９月１５日、厚生労働省からインフルエンザの流行に備え、検査体制の拡充に向けた指針が出され、検査体制の点検と強化が求められています。これからの検査需要の見込み、ＰＣＲ検査の検体採取対応力について、現状での１日の件数と、ピーク時、１日何件まで引き上げる計画か、そのための体制整備をどうつくっていくのか、相談体制はどう拡充するのか伺います。","respondent":"福内品川区保健所長","answer":"今後も増加の見込みがありますので、先ほど申し上げました１日で３２６件程度の検査は可能ではないかというふうに考えてあります。","voiceIndex":174,"id":"exchange-080"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひこれを区が活用して、高齢者、基礎疾患のある希望者へのＰＣＲ検査を実施するよう求めます。いかがでしょうか。この要請に沿って検査の拡充を求めます。いかがでしょうか。いかがでしょうか。以上、３点の実施について、お答えいただきたいと思います。新型コロナウイルス感染症地方創生臨時交付金は、品川区に幾ら出されているのか、どう活用されているのか、今述べた対策に活用できるのか伺います。","respondent":"品川財政課長、伊崎福祉部長、福内品川区保健所長","answer":"委員のご質問にありますＰＣＲ検査等につきましては、地方創生臨時交付金の対象におおむねなるというふうには考えておりますが。区といたしましては、委員ご指摘の介護サービス事業者等のＰＣＲ検査の実施に向けて、今、作業を進めているところでございまして、こういった手段を講じて。今後も感染状況等に応じて確実に検査を実施してまいります。","voiceIndex":176,"id":"exchange-081"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"高齢者と基礎疾患のある人を対象に、国庫補助を行うという通知は、１か月前の９月１５日に出ているのです。１か月前に出ているものに対して、１か月間、このことに対して検討してこなかったのでしょうか。何よりも高齢者と基礎疾患のある人は、かなり幅広くなります。大変意味のあることだと思いますが、区は、この高齢者と基礎疾患のある人への検査に対して、必要な検査とは考えないのか伺います。","respondent":"福内品川区保健所長","answer":"ただ、検査を実施するにあたっては、やはり効果的に実施する、また、感染の疑いがある方たちからきちんと検査を行い、また、場合によっては対象をそこから広げて検査をしていくことが望ましいというふうに考えてあります。","voiceIndex":180,"id":"exchange-082"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、この６５歳以上の高齢者と、基礎疾患を有する者に国庫補助を行うと、ここまで出しているわけですから、この検査をやっていただきたい。これを検討しなかったのか、そしてこれを必要だと思わないのかを伺ったので、そのことについて答弁をお願いします。","respondent":"福内品川区保健所長","answer":"品川区の場合は、現在、高齢者の方は家族からの感染、または施設の中での感染ということが見られておりますので、現時点では、そのような状況を踏まえて、施設等、または家族の中で。","voiceIndex":182,"id":"exchange-083"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"非常に残念です。ここまで国が出しているわけですから。改めてＰＣＲ検査等の拡充を強く求めます。次に、保健所体制の拡充について伺います。この間、長時間労働や仕事の緊張など、多大なストレスだったのではないでしょうか。もともと保健師は、人口対比の定数が２３区で最低の人数であり、共産党は定員増を求め続けてきました。区として保健師の正規職員の大幅増員を求めますが、いかがでしょうか。","respondent":"榎本総務部長","answer":"ストレスチェックにつきましては、９月に全職員に実施しておりまして、その中で、今、検診機関のほうで集計をしているところで、１１月には各個人に報告書を通知する予定です。その結果によりまして、産業医の面談、本人であったり上司を通じての面談などを行う予定です。","voiceIndex":184,"id":"exchange-084"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"区がこの状況をどう捉え、どのような対策が必要と考えるか伺います。さらに具体的に伺います。東京都並みの２倍に額を引き上げること、３か月の期間を国並みの６か月に引き上げることを提案します。さらに区独自の収入が５割減、また３割減が３か月という厳しい要件を緩和することを求めますが、いかがでしょうか。１回限りの給付ではなく、持続的支援を国に求めていただきたいが、いかがでしょうか。","respondent":"榎本総務部長、久保田地域振興部長","answer":"そのほかいろいろな業務量を考えて、この間、増員をしてきているところです。今後も適正な仕事の執行ができるように人員をきちんと配分しながら仕事を進めていきたいと考えています。家賃支援給付金についてですが、これらの要件につきましては、経営状況が特に厳しい事業者に迅速な支給を実施するものと考えておりまして、審査を極力簡略化し、迅速な給付をするという観点から。","voiceIndex":186,"id":"exchange-085"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"保健師は、ぜひ定数として増やしていただきたいと思います。続きまして提案ですけれども、住居確保給付金、緊急小口資金・総合支援資金は、多くの人が活用し救われています。支給された人数をそれぞれ教えてください。給付期間延長を国に求めてください。いかがでしょうか。港区のように、品川区でも大学生、専門学生に対する給付型奨学金制度の創設を改めて求めます。いかがでしょうか。","respondent":"伊崎福祉部長、柏原子ども未来部長","answer":"住宅確保給付金および緊急小口資金・総合支援資金の期間の延長につきましては、国において議論をされるものと認識しておりますので、状況を注視してまいります。こちらの問題に関しまして、進学はもちろんそうですが、高校生が途中で退学した場合に、その後の就職であったり、様々な影響がある、これはかなり大きな影響があるということで、大学生のそういった部分との比較において。","voiceIndex":191,"id":"exchange-086"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私はコロナ禍による区民の苦境に心を寄せた対応をお願いしたいと思います。しかし、まだまだ不十分です。ＰＣＲ検査、医療体制の拡充、暮らし、営業を守る支援の取組みを求めます。ＪＲ開発のために進める庁舎の建て替え、８００億円もの税金を投入する巨大道路づくり、こうした税金の使い方は見直し、コロナ禍から区民の命と暮らしを守るために充てるよう求め、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":194,"id":"exchange-087"},{"speaker":"須貝委員","kind":"質問","question":"新型コロナウイルス感染症問題の影響で、倒産、休・廃業や解散は５万件、解雇、雇い止め、自宅待機などの失業者と休業者は数百万人いて、その大半の収入がゼロになり、生活費や家賃に回すお金がなくなっていて様々な援助を受けています。１つ目、区内の中小・零細企業の経営の現状をどのように把握していますか。そして、倒産、廃業、休業、解散などをした企業数を把握していたら教えてください。","respondent":"久保田地域振興部長","answer":"区内中小企業の現状ですけれども、このコロナ禍の中で経営は大変厳しい状況になっているというふうに私どもも認識しています。倒産、廃業の件数ですけれども、廃業についての区内の状況はつかみ切れていないところです。","voiceIndex":197,"id":"exchange-088"},{"speaker":"須貝委員","kind":"質問","question":"今、地域経済と社会活動の崩壊が始まっていると思います。この新型コロナウイルス感染症による影響は、非常事態であり、そして異常事態ではありませんか。ならば、区内産業の経営状況を、調査、把握するべきだと思いますが、再度教えてください。確かに倒産は減っていますが、廃業、休業等の会社が多数あるように聞いております。もう一度ご見解をお聞かせください。","respondent":"久保田地域振興部長","answer":"廃業につきましての数値ですけれども、品川区ということではございませんが、全国の場合ですと、昨年が約４万件ほど、それに対して今年は、たしか５万件を超えて６万件近くいくのではないかという見込みが出ているということは把握しています。","voiceIndex":199,"id":"exchange-089"},{"speaker":"須貝委員","kind":"質問","question":"この新型コロナウイルス感染症問題から起きていることは、今までの不景気とは全く異質です。大企業であれ、日本の基幹産業であれ、対処が難しく、いつ倒産や廃業を迎えてもおかしくないという状況にあります。違いますか。これについてもう一度ご見解をお聞かせください。休業する。そして、何か対策をお考えですか。教えてください。そして失業者が増え、貧困層が増えると思いますが、教えてください。","respondent":"久保田地域振興部長","answer":"これらの対策に加えまして、企業のほうの様々な経営相談に乗るということも大事なことでございまして、社労士等を活用した相談窓口の設置、また、国や東京都の助成金の相談窓口の開設をはじめ、そういった企業や雇用を維持できるような形の支援も継続的に進めているところです。","voiceIndex":201,"id":"exchange-090"},{"speaker":"須貝委員","kind":"質問","question":"でも、いずれ返さなくてはいけない。別にご商売をやっている方にいくわけではなく、そして消費にしても、やはり品川区民の中の本当に一部ですから、これが景気回復または地域振興、仕事をやっている皆さんのために、ゼロとは言いませんがそんなに貢献しているとは思いません。今、相談ではないのではないですか。今は何とかして企業を存続させるということを第一に考えるべきではないかと思います。","respondent":"久保田地域振興部長","answer":"屋形船等の支援に加えて、他の業界へというお話もございましたけれども、まずは大きな痛手を負いました屋形船のところに支援をさせていただいて、その後、状況等を見ながら、必要に応じて他の業種等につきましても検討を進めていきたいと考えております。","voiceIndex":203,"id":"exchange-091"},{"speaker":"須貝委員","kind":"提案","question":"今、経営相談もやって、これから皆さんがどうやっていったらいいのだということを、区としても力を入れてやっていくと。第二には、今もう難しいなら転業を考えられたらどうですかとか、そういうことも１つの提案だと思います。私は、何とかその方たちにお金が回るようにやっていただきたいと思います。そして次にいきます。教えてください。そして、今後、区はどのような対応をお考えなのかお聞かせください。","respondent":"品川財政課長","answer":"今後の対策としましては、既存事業の見直しも進めまして、優先順位をしっかりと見極めながら、必要な事業をしっかりと進めていきまして、引き続き、計画的で健全な財政運営を行ってまいりたいと考えております。","voiceIndex":205,"id":"exchange-092"},{"speaker":"須貝委員","kind":"質問・要望","question":"１つは、しながわ水族館の廃止です。品川区の近くにはＪＲの駅前に２つの水族館があります。近くに民間の水族館がこれだけできているならば、ましてアクセスがいい水族館が２つもあるならば、もう民間でできることは民間に任せるべきだと思いますが、お答えください。そして２つ目は、ふるさと納税対策です。今では約２４億円の税収減で、渋谷区のように返礼品競争を本格的にやるべきではないかと思います。","respondent":"藤田防災まちづくり部長、榎本総務部長","answer":"しながわ水族館ですけれども、宿場町として栄えていた品川区として、昭和５０年代に埋立て等がかなり進んでいく中で、区として東京湾の資料や生物を紹介する資料館の計画案がまず立案されまして、その後、昭和６０年代に入りまして。その中で国がいろいろと制度を変えてきまして、地方に有利なルールづくりというか、そういう基準を作ってきました。その中で品川区は、平成２７年度から返礼品を考えてふるさと納税に着手してまいりました。","voiceIndex":207,"id":"exchange-093"},{"speaker":"須貝委員","kind":"質問","question":"お金に余裕があってやっているわけではないのです。そういうことを考えたら、もう転換しなければいけないのではないかと思いますが、もう一度ご見解をお聞かせください。でも、今はそれは終わったのではないですか。周りにこれだけ民間でできるところがある。ましてアクセスが全然違う。現に来場者が少しずつ減っているならば、もう転換する時期だと思いますが、もう一度ご見解をお聞かせください。","respondent":"榎本総務部長、藤田防災まちづくり部長","answer":"そういった仕組みになっておりますので、今現在そういう形で流出する元というのは、ちょっと言いづらいですが、区内の高額所得者の方が地方へ寄附すると、その部分の区の税金が外へ流れるという、そういう仕組みになっていますので。入館者数が減少してきていることは確かにそのとおりですけれども、現在、私どもも顧客満足度満点プロジェクトということで、来てもらえるお客様にぜひとも満足をしていただけるような仕組みも改めて検討しています。","voiceIndex":210,"id":"exchange-094"},{"speaker":"須貝委員","kind":"質問・要望","question":"個別にお聞きします。ですから、高齢者には社会活動に参加していただき、心身ともに元気な生活を続けていただきたいものと思いますが、ご見解を教えてください。そして、シルバーセンターやほっと・サロンでは、カラオケやマージャンなどの教室や様々なサークルなどがありますが、感染対策を工夫した上で、使用制限を解除したらどうでしょうか。お答えください。","respondent":"伊崎福祉部長","answer":"しかしながら、様々なところで再開をしている先例もありますので、そういったものを参考にしながら、区の中でどうやって活かしていったらいいのか検討してまいりたいと思います。","voiceIndex":213,"id":"exchange-095"},{"speaker":"須貝委員","kind":"質問・要望","question":"避難場所には、赤ちゃんから高齢者まで大勢の区民が殺到しますが、健康な方のほかに、様々な持病や病気をお持ちの方、インフルエンザや新型コロナウイルス感染症の感染者などを収容できるスペースはあるのですか。収容能力を超えた場合は入場制限をするのですか。混乱時ですが対応できるのですか。狭いところに大勢入るわけですから、二次感染、三次感染を防ぐことは可能なのですか。教えてください。","respondent":"滝澤災害対策担当部長","answer":"その場合には、そのエリアを閉鎖するとか、必要であれば、体育館に入っているものをホテルを借り上げて全て個室にして、そこで一時、２週間なり管理をするとか、そのときの状況に応じて。","voiceIndex":215,"id":"exchange-096"},{"speaker":"須貝委員","kind":"質問・要望","question":"ただ、これは本当に難しい問題だと思います。今回、新型コロナウイルス感染症問題が出て初めて、やっぱりこれは怖いなと私も思ったので、避難計画の見直しと避難所の見直しをしていただきたいと思うのですが、そこら辺はご検討しているのでしょうか。お知らせください。","respondent":"滝澤災害対策担当部長","answer":"現在、新型コロナウイルス感染症に伴いまして、避難所のマニュアルの改定を行いながら、いかに避難所の運営を支援するかについては検討しております。最終的に、新型コロナウイルス感染症に伴う災害対策計画の修正についてまでは検討している範囲ではございません。","voiceIndex":217,"id":"exchange-097"},{"speaker":"須貝委員","kind":"質問","question":"多くの生徒は、家族をはじめ、日常生活で習い事やスポーツクラブなど、様々な人と接触しております。教えてください。そして、今ご答弁がありましたが、学校は感染拡大を防止するより、風評被害を優先するということですか。教えてください。","respondent":"齋藤教育次長","answer":"保健予防課長に先頭に立っていただき、日曜や平日、夜間にも最も精度の高いＰＣＲ検査を実施していただきました。検査にあたっては、行動履歴の把握や関係者に丁寧な聞き取りを行っております。その上で、検査対象者を絞り込んでいました。","voiceIndex":221,"id":"exchange-098"},{"speaker":"須貝委員","kind":"質問","question":"今、校庭を使用している、学校施設を使用している団体の保護者が、校庭内で練習等を見学することを禁止されている学校がありますが、感染リスクが少ない校庭での見学はなぜ駄目なのですか。教えてください。見学を了承している学校もありますが、なぜ対応が分かれているのですか。この辺についてもご見解をお聞かせください。","respondent":"齋藤教育次長","answer":"学校での感染リスク、学校からの感染リスク、こういった疫学的判断は保健所の知見によることが重要であると考えておりますので、保健所と連携を図りつつ情報提供を図ってまいります。","voiceIndex":223,"id":"exchange-099"},{"speaker":"須貝委員","kind":"質問・要望","question":"やはり教育委員会として、学校を束ねている、指導しているのですから、私はやはり１つの指針が必要だと思います。なぜ外で駄目なのか、これは親御さんも分からない。教室とか体育館、校舎内は分かりますが、やはりその辺はしっかりとしたご見解をしていただきたいと思います。以上で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":225,"id":"exchange-100"},{"speaker":"吉田委員","kind":"質問","question":"全庁的な障害者への合理的配慮に関しての質問をいたします。これです。この編集の所管は障害者福祉課になっているので、改訂の都度、障害者福祉課から発信、配付がされていると考えてよろしいでしょうか。各所管では、このハンドブックを受止め、どのように職員で共有し、活用の方法を徹底しているのか、研修などもあったほうがいいと思うのですけれども、その辺の活用について伺います。","respondent":"伊崎福祉部長","answer":"各部の取組みといたしましては、障害者差別解消法や職員ハンドブックの内容にのっとり、庁内ルールの周知徹底をしております。情報発信では、音声コードへの対応を行う、窓口では必要な備品を配備するなど、各部の業務内容に応じて合理的配慮を行っているところです。","voiceIndex":227,"id":"exchange-101"},{"speaker":"吉田委員","kind":"確認","question":"発信だけではなく、この実施についても福祉部が統括的に行っているというふうな理解でよろしいでしょうか。それから、併せて２１ページの貸出用用品について伺います。款別審査のときには、たしか５０台用意されていると伺いましたが、貸出システムについて伺います。どのように利用されているのでしょうか。窓口でタブレットが使えることの表示、案内はどのようにあるのか、それぞれの所管について伺います。","respondent":"伊崎福祉部長、堀越企画部長","answer":"ハンドブックに記載されている内容につきましては、常に障害者福祉課として見直しを行っておりますので、近年の様々な対応にそぐわないところがございましたら、修正をしていきたいと考えております。関係団体につきましては障害者福祉課のほうで対応していますので、全庁的に連携して対応をしていきたいと思ってあります。","voiceIndex":229,"id":"exchange-102"},{"speaker":"吉田委員","kind":"質問・要望","question":"タブレットですけれども、情報推進課に５０台あるということなのでしょうか。総合案内も大分表示が変わってきてよくなったと思うのですけれども、ちょっと分かりにくいかと、総合案内、表示はありますけれども、分かりにくいかと思いますが、見解を伺いたいと思います。次に、２３ページの統一ルールの中の手話通訳者派遣・要約筆記者派遣について伺います。なぜでしょうか。この点について見解を伺います。","respondent":"伊崎福祉部長、堀越企画部長","answer":"手話通訳につきましては、合理的配慮の提供という部分になってくるかと思うのですが、国の基本指針、あるいは障害者差別解消法におきましても、合理的配慮の提供は、その事業を行うにあたり。周知については、今、福祉部長が申し上げましたとおり、我々としても全庁的に庁内周知に努めてまいりたいと考えています。","voiceIndex":232,"id":"exchange-103"},{"speaker":"吉田委員","kind":"質問・要望","question":"タブレットですけれども、どこに置かれているかが分からないということだと思います。併せて、これは要望ですが、説明会や講演会でパワーポイントを使う場合、視覚障害者の方には、パワーポイントに何が表示されているのかの説明をサポートすることが必要です。これらの配慮も今後実施してほしいと思いますが、見解を伺います。事前広報への明記も同様に考えますが、見解を伺います。","respondent":"伊崎福祉部長","answer":"手話通訳につきましては、先ほども申し上げましたが、本来、合理的配慮の考え方として、お申し出があればということではありますが、お申し出いただくということができるように、そのご案内はしていきたいと考えております。","voiceIndex":235,"id":"exchange-104"},{"speaker":"吉田委員","kind":"質問・要望","question":"どうぞよろしくお願いいたします。款別審査の際、新型コロナウイルス感染症の検査で陽性となった場合は、原則入院、軽症の場合は施設で隔離ということを改めて確認しました。自宅ならともかく、初めての場所ではサポートが必須です。あらかじめ想定しておきたいと考えるのは当然ではないでしょうか。障害者福祉課だけの判断では難しいと考えますが、しかるべき担当部署としてお答えいただきたいと思います。","respondent":"伊崎福祉部長、福内品川区保健所長","answer":"障害のある方に関する新型コロナウイルス感染症の検査のお話かと受止めました。検査につきましては……。検査で陽性になった後の隔離につきましては、障害のある方それぞれの特性がありますので。軽症者については、施設、ホテルに入所していただくですが、やはり様々なご事情があって、それが難しいという方については、こちらも事情をよくお聞きし。","voiceIndex":237,"id":"exchange-105"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひそのことを質問が出たときに答えていただきたいと思います。時間がないので次にいきます。最初に、騒音被害の問題について伺います。品川・生活者ネットワークとしても、当然、国の責任で行うべきと考えていますが、区としてそれを国にどのように主張しているのでしょうか。国はどう回答しているのか伺います。国が動くまで区民を守る立場から区が実施すべきと考えますが、見解を伺います。","respondent":"中村都市環境部長","answer":"新ルートの説明会でも同様の声がありまして、国の回答としましては、これまで事例がなく、調査は予定していないという回答でございましたけれども、やはり区としましては、こうした情報を得た場合には、しっかりと国に伝え、そして対応を求めていくというのは。","voiceIndex":241,"id":"exchange-106"},{"speaker":"吉田委員","kind":"質問・要望","question":"いろいろと求めていらっしゃることは承知しております。それは時間が経ってしまいますので、ぜひ国がその責任をちゃんと果たすまで、区民を守る立場から区が実施すべきと考えて見解を伺いました。その点について伺います。ぜひ検討すべきと考えますが、見解を伺います。落下物の目撃情報があったときは、少なくとも国としてきちんと調査はされるべきと考えますが、区としての見解を伺います。","respondent":"中村都市環境部長","answer":"万が一、落下物が発生した場合には、国が責任を持ち調査を行い、航空事業者とともに対応にあたるといったことを確認しています。事業の停止ですけれども、発生時の対応といたしまして、まずは速やかな原因究明が一番最初に行うべき重要なものであるというふうに考えております。","voiceIndex":243,"id":"exchange-107"},{"speaker":"吉田委員","kind":"質問・要望","question":"だから、被害があったら、本当に当然で、区も一緒にその原因を区民の立場に立って、国の責任、それから事業者の責任を求めていっていただきたいと思います。この点も区として国に求めるべきと考えます。そのことについて、品川区は、そのようなプレッシャーをかけるようなことはないと信じておりますので、区民の立場に立って国に求めていただきたいと考えますが、見解を伺います。","respondent":"中村都市環境部長","answer":"こうした役割を担う国土交通省が厳正に行うべきと考えておりますので、区としましても、それをしっかりと注視して、適切な措置が行われるように求めてまいります。","voiceIndex":245,"id":"exchange-108"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひ公正に行っていただきたいと思います。ただ、先ほどご紹介いたしました事例、やっぱり事業にとって都合が悪い調査はプレッシャーがかかるのです。それを区民は心配しております。ぜひ区民の立場に立っていただきたいと主張して、私の総括質疑を終了します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":247,"id":"exchange-109"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"令和元年度は、普通会計の実質収支が約５１億円の黒字となり、経常収支比率は７５.７％、人件費比率は１３.６％と健全財政を維持していることを評価いたします。そして、基金残高も１,０００億円超を維持しております。コロナ禍の中ではありますが、引き続き、区民の福祉・生活の維持向上に努められることを要望いたします。何点か、ここで取上げます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":250,"id":"exchange-110"},{"speaker":"大沢委員","kind":"提案","question":"普通会計の実質収支は５１億円の黒字。経常収支比率は７５.７％、人件費比率は１３.６％であり、引き続き健全財政が維持された区政運営が行われている、以上の状況を確認いたしました。本委員会で会派所属の各委員が発言した指摘や提案が今後の事業遂行に十分に反映され、予算編成をはじめとする区政運営が、区民福祉の一層の向上に寄与することを強く求め、意見表明といたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":252,"id":"exchange-111"},{"speaker":"若林委員","kind":"提案","question":"区民サービスにおいては、公明党の提案を含めた取組みを積極的に展開しました。今後は、本委員会総括質疑で我が会派が取上げたコロナ禍のＰＣＲ検査、防災や認知症対策、ＩＣＴ等を活用した区民サービスの向上策、款別審査での指摘、提案など、また、これまでの緊急要望や予算要望を十分に検討され、今後の区政運営および来年度予算へ反映されるよう求めます。最後に、来年度予算について意見を述べます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":254,"id":"exchange-112"},{"speaker":"安藤委員","kind":"提案","question":"以下、反対の理由を述べます。区内家賃支援給付金、販路拡大助成金は対象の拡大、１回で終わらせず継続的な給付など、事業者の実態をつかみ、さらなる支援の制度設計と実施を、また、持続化給付金、住居確保給付金、緊急小口・総合支援資金の延長を国に要請することを求めます。国に給付額の引上げを求め、区も認める「生活保護は権利」との文言を明記し、受けるべき方が受けられるよう制度の周知を求めます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":256,"id":"exchange-113"},{"speaker":"須貝委員","kind":"質問・要望","question":"本年度も歳入増に恵まれ、収支は５１億円の黒字となり、健全財政を維持しています。政府、日銀の財政金融政策で、資金繰り倒産は抑制されていますが、このまま社会活動や消費活動の停滞が続けば、廃業が増大し、さらに多くの失業者と貧困層が増えてしまうので、企業が存続できる支援をしていただきたい。そして、羽田飛行ルートの固定化を避けるために、これからも国に働きかけていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":258,"id":"exchange-114"},{"speaker":"田中委員","kind":"提案","question":"以下、何点か意見と要望を述べます。款別審査では、まだ制度的に完全に整っていないことが伺えました。今後、議会としての決算審査の質の向上のためにも、区民への説明責任のためにも、制度整備を求めます。障害者差別解消法が施行され４年が経ちます。各款別審査で指摘、提案させていただいた意見を予算編成に活かしていただくことを要望して、品川・生活者ネットワークの意見表明を終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":260,"id":"exchange-115"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1496#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":108521,"voices":267}},{"id":"r02-20201021-10","meetingId":"r02-cm10","date":"2020年10月21日","dateIso":"2020-10-21","committee":"議会運営委員会","time":"午前１０時３０分～午前１０時５９分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を3件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"議会報告会等準備会議からの報告事項","agenda":"議会報告会等準備会議からの報告事項","exchanges":[{"speaker":"こんの委員","kind":"意見","question":"議会報告会等準備会議より、品川女子学院生徒との意見交換会の実施についてご報告申し上げます。ちなみにテーマは、１つは満員電車の問題、２つ目に音楽によるストレス解消、３つ目に効果的な勉強方法、４つ目に鍵（パスワードなどを含む）について、５つ目に通学時の荷物の重さ解決、最後６つ目は、自己紹介についてというテーマです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":19,"id":"exchange-001"}]},{"id":"topic-02","title":"議長からの報告について","agenda":"議長からの報告について","exchanges":[{"speaker":"安藤委員","kind":"意見","question":"この資料で、初めて知ったのですけれども、今のご説明で、議会に親しんでいただくことが目的で、議運のメンバーにご協力を仰ぐということなのですけれども、議会というのはいろいろと多様性もあるので、少数会派の方々を、メンバーの選定に当たっては、そういった方々に、こういうのがありますということを含めて、議会全体で選出していくことも必要なのではないかと私は思うのですけれども。","respondent":"渡辺議長","answer":"その辺は大切なポイントかと承知しています。昨年の実績をもとに、昨年正副議長で対応して、参加する先方の都合といいますか、先方の人数や割り当てられた時間、質疑の時間から、経験をもとにまず適正な人数を想定しました。そして、いろいろな会議体があります。","voiceIndex":27,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"まだやり始めたばかりということもありますし、先方からのオファーの時期もあると思うので、検討の時間とかもあると思うのですけれども、試みとしてはすごく大事なものだと思いますので、少し時間をかけて、必要な会議体、議運なのか、議会報告等準備会議なのか分かりませんけれども、そういったところを使いながら、場を活かしながら、丁寧な対応については今後議論をしていただければという要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-003"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5380#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":8819,"voices":37}},{"id":"r02-20201109-6","meetingId":"r02-cm11","date":"2020年11月9日","dateIso":"2020-11-09","committee":"区民委員会","time":"午後 １時００分～午後 １時５３分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"マイナンバーカード予約受付制の開始","agenda":"マイナンバーカード予約受付制の開始","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"この施策については賛成なのですけれども、予約制ということに関して、電話の予約も受け付けていただけるということで、インターネットが余り得意ではない方に対しても対応しているということは評価できるのですけれども、電話を受ける体制というのはどうなっているのですか。いずれできるのだと思いますよ。","respondent":"木村戸籍住民課長","answer":"実際、もう人間対応です。テープは使っておりませんので、その場でお伺いをして、その場で入れるというような形で、お待たせしないような形で対応するということで考えております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"藤原委員","kind":"確認","question":"お待たせしないというのは、すぐかかりますよということですか。すぐ。だから、私が例えば電話予約しようとして、電話をかけるわけですよね。そうすると、コール、１０コールぐらいで必ず出るということの意味で、お待たせしませんよということですか。ですから、お待たせしないというのは１０コールぐらいで必ず出ますよということか、そこの確認。","respondent":"木村戸籍住民課長","answer":"今、状況としては、お待たせしてしまうというような形ですね。コールをずっと待っていただくという形ですけれども、今のご提案含めまして、考えていきたいと思います。","voiceIndex":7,"id":"exchange-002"},{"speaker":"くにば委員","kind":"質問","question":"１点伺いたいのが、これは当日の予約もできるのでしょうか。","respondent":"木村戸籍住民課長","answer":"可能です。","voiceIndex":9,"id":"exchange-003"},{"speaker":"くにば委員","kind":"質問","question":"それが混雑回避の方向であり、これが活用できるのではないかなと思ったので、そちらに関しては、掲示であるとか、あとは庁舎内ですね。庁舎内でどういったところにこれを、マイナンバーカードの予約、ホームページと電話で受付開始しましたというのを掲示予定ですか。掲示予定の箇所。","respondent":"木村戸籍住民課長","answer":"現在に関しましては、今、本課と特設会場とあるので、そちらのほうでお知らせを、現地の掲示としてお知らせをするような形を考えておりますけれども、今、ご提案のあったモニターに関しても検討してまいりたいと思います。","voiceIndex":11,"id":"exchange-004"},{"speaker":"くにば委員","kind":"質問","question":"周知に関してもう１点なのですけれども、これは通常どおり、しなメールやツイッターでも告知するというふうに考えてよろしいのでしょうか。","respondent":"木村戸籍住民課長","answer":"ＳＮＳを活用したような形も考えているところです。","voiceIndex":13,"id":"exchange-005"},{"speaker":"くにば委員","kind":"質問","question":"今回の周知という部分で、ふだんでしたらホームページ、しなメール、ツイッターとか書いてあるのが、今回、チャットボットであるとか、ＬＩＮＥという形で、割と最近導入した新しい広報の方法が書いてあったので、従来の方法、しなメールとかツイッターのほうが入っていないのかと思って、お伺いしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-006"}]},{"id":"topic-02","title":"公益財団法人十四世六平太記念財団との連携に関する協定書調印式","agenda":"公益財団法人十四世六平太記念財団との連携に関する協定書調印式","exchanges":[{"speaker":"松本委員","kind":"意見","question":"私からなのですけれども、協力事項は書かれているのですが、今後、何がしか予算が必要になってくるものが出てくるのが、どの程度、出てくるとしたらどの程度の規模感を考えてらっしゃるのか、お願いいたします。","respondent":"古巻文化観光課長","answer":"予算に関しましては、まず、今年行う予定でありました品川薪能でありますとか、また、トット基金との３者の連携によりますインクルーシブＮＩＰＰＯＮという能・狂言のシリーズの舞台、そういったものを予定をいたしておりますけれども、それぞれ。","voiceIndex":21,"id":"exchange-007"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"このチラシは、まず、品川区が作ったのでしょうか。そして、どこにどう配るのでしょうか。それと、委員長、短くやりますが、これ、全然分からない。分からないですよ。５０％オフは分かりますよ。５,０００円で。だけど、どこに申し込んで、どういうふうにすればいいか。全然。どういう順番でどういうふうに申し込んでというぐらい、もうちょっと具体的に、どういうふうにすればと。これ、どうしていいか。","respondent":"古巻文化観光課長","answer":"そこが分かりづらかったと言えば分かりづらかったのかもしれませんが、状況としてはそのようなことでご理解いただければと思うのですけれども。","voiceIndex":28,"id":"exchange-008"},{"speaker":"藤原委員","kind":"確認","question":"私はね。せっかくこういう施策をするわけですよね。この業界だけに、品川の文化ということでお金を出すわけですから。もうちょっと、せっかくこれで、区の予算で作るのであるならば、もっと大きく、各お店によって料金が違うから、必ず確認してくださいとか、そういうのを私は書くべきだと思って、もっと分かりやすく、行きやすくという思いがあるのですよね。と思うのですけれども、いかがでしょうか。","respondent":"古巻文化観光課長","answer":"いろいろな出し方があるのかなと思いますけれども、そのあたり、もう少し丁寧にというところにつきましては、またほかの事業などの広報のときに、もう少し分かりやすいご案内をさせていただければと思いますので、このチラシについてはもう作ってあるものということで。","voiceIndex":30,"id":"exchange-009"},{"speaker":"くにば委員","kind":"質問・要望","question":"で、これを見る限り、何も分からないのですね。ですので、もちろん、次回以降のという、もしくはプラスアルファで、何かチラシを、第２弾とか作る場合にというお話なのですけれども、ぜひとも、屋形船がどういうもので、どういった良さがあって、そもそもどういう料金体系のものなのかということが伝わるような形で告知をしていただきたいなというふうに思いましたというのが１点と、また、その裏ですね。","respondent":"古巻文化観光課長","answer":"作ったときの様々な検討の中での、こういった形になってきているというところでは、表面、もう少し分かりやすく情報をということにつきましては、今後また、先ほどの答弁と重なってしまいますけれども、周知する中でしっかり伝えられるようにしていきたいというふうに思います。","voiceIndex":32,"id":"exchange-010"},{"speaker":"くにば委員","kind":"質問・要望","question":"ぜひとも、品川の屋形船というものの、屋形船の魅力、僕も本当に知らなかったですし、まだ乗ったこともないので分からないです。私の認識だと、総数が１万人に達した時点で終了なので、この１０の船宿のトータルの申込み数が１万人に達した時点で終了なのかと思っていましたが、この書き方を見ると、ちょっとこれは確認です。１社当たり１,０００人の枠で１０社みたいな感じなのでしょうか。","respondent":"古巻文化観光課長","answer":"その後、若干いろいろあると思うので、そのあたりの調整はまた発生するかと思いますけれども、現時点では１,０００人ずつというような枠で始めているというふうなことです。","voiceIndex":34,"id":"exchange-011"},{"speaker":"くにば委員","kind":"提案","question":"結局これ、申込みは、まず船宿にお電話が来ました、そのお電話のときに、これを、キャンペーンを適用しますということを、まず最初に言わないと教えてもらえないのですかね。わざわざ船宿のほうから、お申込みがあった際に、今こういうキャンペーンをやっておりますので、このキャンペーンを適用しますかみたいな形で、船宿のほうから提案していただけるものですか。","respondent":"古巻文化観光課長","answer":"基本的には先着という形になると思うのですけれども、１,０００人ずつの方に関しましてはキャンペーン対象ということになりますので、当然、キャンペーンをということでお申込みいただくというようなケースもあると思いますし、これこれこういうことをやっているので。","voiceIndex":36,"id":"exchange-012"},{"speaker":"くにば委員","kind":"質問","question":"その点を私が伺った一番の大きな理由というのが、これは、船宿にとって積極的にやりたいキャンペーンなのかどうかというのが１つあるのですね。これ、同じく半額補助という形で、残りの半額は、区はいつ、それぞれの事業者さんにお支払いする予定ですか。","respondent":"古巻文化観光課長","answer":"毎月月末締めでご報告いただいて、その月の月末の翌月までには、翌月末までには入金をすると、そのような流れで考えております。","voiceIndex":38,"id":"exchange-013"},{"speaker":"くにば委員","kind":"確認","question":"それを聞いて安心しました。最後にもう１点が、これは確認なのですけれども、今回、天王洲キャナルサイド活性化協会、こちらと共催という形なのですけれども、これは事務局機能のみでしょうか。そちらの経緯についてもお聞かせ願えればと思います。","respondent":"古巻文化観光課長","answer":"天王洲ではありますけれども、水辺の様々なこういった活動に対して、積極的に取り組んでいただいているこちらに事務局をお願いしている、そういう状況です。","voiceIndex":40,"id":"exchange-014"},{"speaker":"松本委員","kind":"確認","question":"今ので続き、１点確認、２点ぐらいお伺いしたいのですけれども、今の話を伺う限り、私も今、ウェブサイトを全部見ているのですけれども、このキャンペーンを告知している会社と、告知されていない会社があって、そうすると、何も知らない人が申し込むと、場合によっては正規の料金でそのまま取られてしまうということがあるということでいいのでしょうか。お願いします。","respondent":"古巻文化観光課長","answer":"基本的には、枠が埋まるまではキャンペーンの対象とするという流れになるというふうな認識をしておりますので、どうしても正規料金を払いたいという方についてはそういう扱いになるかと思いますけれども。","voiceIndex":42,"id":"exchange-015"},{"speaker":"松本委員","kind":"確認","question":"例えば、ほかの、行政が一括して請け負っている場合というのは、もうウェブサイトで１,０００人なり１万人なりを達成した時点で、そこでもうソールドアウトですよ、終わりですよというような告知がすぐできると思うのですけれども、これ、事業者さんに任せているので、そこの部分がきちんと、線を超えた時点でしっかりと消費者に対して告知できるようになっているのかというのは、一応。","respondent":"古巻文化観光課長","answer":"ご予約の状況については事務局のほうで取りまとめをしておりますけれども、日報的なものをファクスでやりとりをしているというような形でございまして、日々の状況については事務局のほうでしっかり把握をした上で、どう調整をするかというのはありますけれども。","voiceIndex":44,"id":"exchange-016"},{"speaker":"松本委員","kind":"質問","question":"例えば、団体なのか、個人なのか、どういう、品川区の人たちなのか、あるいは区外なのか、そういったとこも把握して、今後の観光にも役立てていったほうがいいのではないかと思うのですが、そのあたりの取組の状況はいかがでしょうか。","respondent":"古巻文化観光課長","answer":"感染症対策の一環ということもありますので、代表者の方が中心ですけれども、ご連絡先等を伺っておりますので、そういった意味で言うと、統計的なものというのは取れると思いますし、当然、事務局のほうでしっかりその辺の利用状況については統計を取っていただいて。","voiceIndex":46,"id":"exchange-017"},{"speaker":"小芝委員","kind":"質問","question":"今日、９日で、既に始まって９日たっているわけですけれども、これまで事業者のサイドから、また、実際に屋形船に乗られた方から、そういった反響といったものは区のほうには届いているのでしょうか。","respondent":"古巻文化観光課長","answer":"聞いてはいるところですので、今後いろいろな、多分、反響が区のほうにも寄せられるのかなというふうに考えております。","voiceIndex":48,"id":"exchange-018"},{"speaker":"小芝委員","kind":"質問・要望","question":"せっかく１万人上限で、予算も補正予算のところで出しているわけですので、ぜひとも反響、これから出てくると思いますので、この広報広聴課とも連携をとって、うまくホームページ、またＳＮＳ、そのほか広報媒体を使って、ぜひ、結果というものを周知していただきたいなと思います。述べさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-019"},{"speaker":"大倉委員","kind":"確認","question":"確認なのですが、先ほど来、お話の中で、５,０００円上限で５０％オフですよという話があって、下のＱＲコードから公式サイトのほうへ飛んでいくと、その中には、この流れ、申込みとか、そういうところの説明があるのですが、方法のところの注意書きみたいなところで、キャンペーン利用とお伝えくださいというところが書いてあって、先ほどのお話だと、基本的には電話でもお申込みをいただいた方は。","respondent":"古巻文化観光課長","answer":"基本的には、枠内であれば、そのような扱いになるというふうに、区としては認識をしています。","voiceIndex":51,"id":"exchange-020"},{"speaker":"大倉委員","kind":"質問・要望","question":"これ、しっかりとその辺も把握していただいて、本当にこれを見て、よく分からないけれどもちょっと乗ってみたいから申込んでみようと言って、それが、あれ、おかしいなと、結局これが利用できませんでしただと困るので、その辺はしっかり確認していただきたいのと、ここに書かれている内容については、キャンペーン利用とお伝えくださいというのは、チラシにしっかりと載せていただいたほうが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-021"},{"speaker":"つる副委員長","kind":"質問","question":"この事業そのものについては、今、様々な質疑があったのですけれども、良い機会なのでということで、こちらの所管、文化観光課だけではないと思うのですけれども、先ほど、最初の質疑の中で、これは区が作ったチラシですよねというふうにあったのですけれども、これは区職員がデザインをしたものか、それともどこかに、デザイン会社か何かに依頼して作ってもらったのか、そのところが分かれば教えてください。","respondent":"古巻文化観光課長","answer":"区の予算が入っていますけれども、デザインについては事務局のほうでデザイン専門家と言うのですか、デザイン会社のほうに委託というか、お願いをして作っていただいたというふうに認識しております。","voiceIndex":54,"id":"exchange-022"},{"speaker":"つる副委員長","kind":"提案","question":"ですからやはり、そういう意味では、非常に意識を持ってやってもらわないと、これだけ大きい規模、そして、ましてやこういうコロナ禍を乗り越えようという、そういった取組を、賛成する人もいるし、何でそこだけという、いろいろな業界にあると思うのですね。今回、この事業周知啓発費、経費等で１５５万円ですかね。この議会からも提案があったと思うのだけれども、そういうデザイン枠採用というのですかね。","respondent":"山崎文化スポーツ振興部長","answer":"ですから、その公益性がある観光事業をやっていらっしゃる事業者なので、今回はそこに焦点を当てたというのが合理性かなというふうには思っているところですが、様々なご意見をいただきつつ、やはり水辺観光の牽引役というのは、ある意味そう思っていますので。","voiceIndex":56,"id":"exchange-023"},{"speaker":"つる副委員長","kind":"質問・要望","question":"これはもう文化観光課のこのＥＮＪＯＹしながわ屋形船キャンペーンだけではない、区が今後、いろいろなものを広告媒体でやっていくに当たっては、何か売上を上げるわけじゃないのだけれども、やはり、いろいろな部分で品川のポイントを上げていくというところでは、もっと言うと、区民の方の理解をいただくというところでは、非常に、私は大事な視点なのかなという部分では。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2882#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":19041,"voices":60}},{"id":"r02-20201109-7","meetingId":"r02-cm11","date":"2020年11月9日","dateIso":"2020-11-09","committee":"厚生委員会","time":"午後 １時００分～午後 ２時３７分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を31件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"請願・陳情審査","agenda":"請願・陳情審査","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"陳情書の中に、車椅子利用者が２月の厚生委員会の時点で１は名だった、それが現在５名に増えていると書かれていますが、実際５名に増えたのか、これを第１点、伺いたいと思います。それから、今の避難訓練においては、この５名の車椅子利用者ということで行っているのかということを伺いたいと思います。そうすると、火災時、この車椅子利用者の避難というのは、担架で下ろすことになるのかということ。","respondent":"築山障害者施策推進担当課長","answer":"現状ですが、車椅子利用者は５名です。それから、避難訓練の実施につきましては、５名を対象としたものというわけではありませんが、事業所として実施しているものです。","voiceIndex":6,"id":"exchange-001"},{"speaker":"おくの委員","kind":"質問・要望","question":"このような状況で重度心身障害者を受入れるのは大変危険だと思う、とあるのですが、区ではどのように認識されているか、伺いたいと思います。それから、この陳情には、施設を整備した上で受入れを進めるよう求めてくださいとあるのですが、区ではどんな施設整備が考えられるのか、その点も伺いたいと思います。消防署の方というのは、どの消防署の方が来るのか。そういうことを伺いたいと思います。","respondent":"築山障害者施策推進担当課長","answer":"重度の方、特に医療的ケアが必要な方につきましては、担架等で避難するのも状況によっては難しい場合もあるかと思いますので、消防と連携した対応が必要になってくるだろうと考えているところです。","voiceIndex":8,"id":"exchange-002"},{"speaker":"おくの委員","kind":"質問","question":"今の質問に関わってなのですが、実際に大井消防署の人が来て非常用エレベーターを動かすことになっているのですか。でも、実際に大井消防署の人が来て訓練したことはないということなのでしょうか。それからもう１つ、今のお答えは、具体的な施設整備としてはまだそれほど考えていないということなのですか。ちょっとよく分からなかったので、もう一度お願いします。","respondent":"築山障害者施策推進担当課長","answer":"訓練につきまして、非常用エレベーターは、通常、動かせる状態です。動かしているところで救助をしたという訓練は特段行っておりません。整備につきましては、これも冒頭にご説明させていただきましたが、ハードの大規模な改修の予定はしておりません。","voiceIndex":10,"id":"exchange-003"},{"speaker":"おくの委員","kind":"質問・要望","question":"そうしましたら、もう１つ質問します。重度障害者の受入れいかんによって、指定管理の費用も変わってくると思うのですが、区としては重度障害者の方の受入れをどうしようと考えているのか、ちょっと見えてこないので、この点についても、この陳情に関わってお伺いしておきたいのですが、いかがでしょうか。","respondent":"築山障害者施策推進担当課長","answer":"総合支援施設は、地域生活支援拠点機能を設けております。地域生活支援拠点では、重度の方の受入れ等も対象とした機能を考えておりますので、そういったところで重症心身障害者の受入れというところは求めているということを公募要項にも示させていただいているところです。","voiceIndex":12,"id":"exchange-004"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"現在、車椅子の方が５名ということで、これから重度の方を生活介護でもショートステイでも受入れていくという方向ではないのでしょうか。その点、これからの方向性、生活介護とショートステイの２つがあるのかなと思うのですが、その方向性をお聞かせいただきたいと思います。その点、まずお聞かせください。","respondent":"築山障害者施策推進担当課長","answer":"５階は定員２０名ですので、生活介護は２０名、また、短期入所は４階が６名、５階が６名ということで、５階の６名を想定しています。","voiceIndex":14,"id":"exchange-005"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"生活介護が２０名、それから短期入所が６名、それの全てが重度ということではないと思うのです。その中で重度の方が何人くらいかという想定を区として持っていないのでしょうか。","respondent":"築山障害者施策推進担当課長","answer":"ですので、定義をどう持っていくかによってまた回答の仕方も変わってきますが、いわゆるピッコロのようなところで受入れている重症心身障害者という意味でいきますと、現在まだ、体制は整っておりませんが、まずは５名からと想定しております。","voiceIndex":16,"id":"exchange-006"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"消防署と一緒の訓練を２月に行ったということですが、実際問題、消防の方に来ていただいて、非常用エレベーターを使って避難することにならざるを得ないのではないかという思いをするのですが、そういうことから考えると、実際の訓練の中にも非常用エレベーターを使った訓練を入れていくべきではないかと思うのですが、なぜそれは、消防の方が見えるのに、実際訓練としてされなかったのか。","respondent":"築山障害者施策推進担当課長","answer":"最後の質問ですが、避難スペースにつきましては、避難誘導用エレベーターを設置というところになりますと、求められているスペースは取れないところですが、災害時というところでは、状況に応じて、スペースがないわけではないので。","voiceIndex":18,"id":"exchange-007"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"煙に巻き込まれないというのがすごく大事だと聞いたのですが、そこに一時避難して、消防の方に来ていただいたら、次々と非常用エレベーターで避難するというやり方はできないのかなという思いをしたのですが、そこら辺のところを教えていただきたいのと、あと、区としては、生活介護で５名、それからショートステイでもこれから需要によって受入れていくことになると、今。","respondent":"築山障害者施策推進担当課長","answer":"失礼いたしました。現在の機能を変更していくということが考えられるかと思います。先ほどの答弁は訂正します。それから、安定した避難ですが、これは冒頭の説明のとおり、利用者の状態に合わせた対応が必要かと考えております。","voiceIndex":20,"id":"exchange-008"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"もう１つ、先ほど消防との訓練のときに助言を頂いたと言われたと思うのですが、その助言というのはどんなものだったのかということと、施設を整備した上で受入れを進めるよう求めてくださいというところで、現在ある機能を潰すという答弁は取消すということですか。その点、もう１回、はっきりとお願いしたいと思います。","respondent":"築山障害者施策推進担当課長","answer":"助言につきましては、災害発生時に、関係するところにすぐ連絡を取って、速やかな避難ができるようにというアドバイスを頂いたところです。それから、機能を潰すといった発言については訂正します。機能の変更の必要が出てくるだろうという発言に変えします。","voiceIndex":22,"id":"exchange-009"},{"speaker":"鈴木（ひ）副委員長","kind":"提案","question":"公募要領に重度障害者の方の具体的な文言がないですが、説明会の中でそこら辺のところは説明されて、例えば生活介護では５名程度を受入れます、ショートステイも需要に合わせてやっていただきたいと、これからの公募ではそこら辺も含めた形での提案ということでお求めになるということでいいのでしょうか。その確認もお願いします。","respondent":"築山障害者施策推進担当課長","answer":"機能変更ですが、施設を再考するとなりますと、今ある設置場所を変更することになりますので、そうなったときに必要なスペースが取れるか、場合によっては今ある定員数を変更するだとか、そういったことも考えられるというところで。","voiceIndex":24,"id":"exchange-010"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"機能変更のところですが、ということは、やっぱり現在の車椅子の方５名に加えて重度の方を５名、それに加えて、ショートステイをプラスで受入れていくとなれば、この施設は、本来であればもっと安全な避難ができるような施設として区としても変更が必要だと考えられていると。本来であればもっとこういうふうな安全な施設を造れればよかったということなのでしょうか。","respondent":"築山障害者施策推進担当課長","answer":"先ほどお答えしました機能変更の例につきましては、委員から例えばということでご質問がありましたので、私のほうで具体例をご説明したものですが、現時点で大きな改修等は考えておりません。","voiceIndex":26,"id":"exchange-011"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ただ、こういう安全対策というのは、より高い、本当に全ての方の安全がしっかりと守れる対策が必要だというところで、これから求められるということで出されてきている陳情だと思うのですが、そういう点では、改めて今の中でも取れる対策をぜひ取っていただきたいと思いますし、訓練のところでも、非常用エレベーターを使った、消防隊の方も入れた形での訓練を取入れていただきながら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-012"},{"speaker":"西村委員","kind":"意見","question":"本日結論を出すで、不採択でお願いいたします。説明がありましたとおり、取れる対策をしながら、ショートステイ、生活介護含めて、重度心身障害者の方の受入れを進めていただいていることを理解しましたので、不採択でお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":31,"id":"exchange-013"},{"speaker":"渡部委員","kind":"意見","question":"前回、同じような内容で審議をしたときと変わらないですし、本当に何か事がある、どういう形で避難というのも、そこはしっかり訓練していただいて、なおかつ、本当の災害とかが来たときに、多分エレベーターもそんなにすぐには使えないので、急なときは、担架なのか、担いで避難していただくのか、しっかり訓練を重ねていただければと思います。今回の件については不採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":32,"id":"exchange-014"},{"speaker":"あくつ委員","kind":"質問・要望","question":"本日結論を出すということで、不採択でお願いいたします。おんぶひもや担架、また、消防による非常用エレベーターということもありましたが、やっぱり最後はその場の状況に応じた避難ということが求められると思います。そういったこともしっかりと訓練の中でやっていただきたいという要望を含めまして、ここにエレベーターというところについては不採択ということでお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":33,"id":"exchange-015"},{"speaker":"おくの委員","kind":"意見","question":"本日結論を出すで、採択でお願いします。基準は満たしておりますが、まだまだ積み重ねてやっていかなければいけないことが、今の審議の中でもいろいろ明らかになってきたことと思います。そういう意味で、採択でいきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":34,"id":"exchange-016"},{"speaker":"高橋（し）委員","kind":"質問","question":"本日結論を出すで、不採択でお願いします。ほかの委員の方からもお話がありましたが、前回の議論、そして今回の説明を伺って、現状、でき得ることをやられているということと、最悪こういった事態になったときは、どうしても人の手で行かなければいけないということなので、その対応を中心に考えているということも分かりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-017"}]},{"id":"topic-02","title":"第６期品川区障害福祉計画・第２期品川区障害児福祉計画の策定期間の延期","agenda":"第６期品川区障害福祉計画・第２期品川区障害児福祉計画の策定期間の延期","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"それからもう１つ、昨年というか、前の経過を見ますと、前回は策定スケジュールの中に、計画策定意見交換会があって、今回はその意見交換会がないのですが、なぜこれがなくなったのかというか、必要ではないかと思うのですが、策定意見交換会の中で、特に障害者相談員の方の意見を聞く場として重要ではないかと思うのですが、そういう意味で必要ではないでしょうか。それをお伺いしたいと思います。","respondent":"築山障害者施策推進担当課長","answer":"それから２点目の質問ですが、今回の計画策定委員会のメンバーは、当事者側の意見を聞けるようにというところで、障害者団体から７名が委員として入っております。障害者団体へのヒアリングを、昨年度、基礎調査を実施する際に実施しており、また、今年度も実施する予定です。","voiceIndex":42,"id":"exchange-018"},{"speaker":"おくの委員","kind":"質問","question":"前回やっているのですから、そんなに省略しなければいけないようなものでもないし、現場の意見ということでも大事な意見だと思うのですが、やられるべきではないでしょうか。いかがでしょうか。","respondent":"築山障害者施策推進担当課長","answer":"意見交換会というところですが、先ほどと同じ説明になるところがありますが、今回は委員に障害者団体の方が７名入っている、それからヒアリング等の実施なども含んでおり、丁寧に実施しているものと考えております。","voiceIndex":44,"id":"exchange-019"},{"speaker":"おくの委員","kind":"質問","question":"今のご説明では、私は両方とも納得できないのですが、適していると言われても、私には適していないと反論する以外ないのですが、どこがどう適しているのか、伺います。〔「適しているよ」「そんなの感覚の問題じゃないですか」「前回と仕組みが変わっているんだから。７ 団体入っているんだから。","respondent":"築山障害者施策推進担当課長","answer":"１点目ですが、骨子案につきましては、先ほどご説明しましたように、計画策定委員会で作成している途中段階のものですので、ご報告するというところでは、素案の段階が良いと考えております。","voiceIndex":46,"id":"exchange-020"},{"speaker":"渡部委員","kind":"確認","question":"ですから、従来どおりのやり方で進めてくれているのかなと考えます。１点だけ確認しますが、今回の変更で、２カ月ぐらい延ばすというのは、いわゆる新型コロナウイルス感染症の影響で、この間、できなかったので、その分、２カ月後ろにずらすという意味合いの報告と受けてよろしいのでしょうか。","respondent":"築山障害者施策推進担当課長","answer":"委員がおっしゃるとおり、２カ月遅れたので、その分遅れるという報告になります。ただし、この間、調整等も行っておりますので、２カ月の遅れで済むかどうかというと、ちょっと難しいかなと考えていますので、順調にいけば３カ月程度の遅れかなと考えております。","voiceIndex":48,"id":"exchange-021"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"日程的な確認ですが、今度、策定委員会で素案の報告、議論をされるのが１２月２２日に予定され、１月下旬からはパブリックコメントが予定されているとのことですが、そうすると、議会への素案の報告というのはいつになるのかということを１点お聞かせいただきたいのと、障害者団体ヒアリングは、幾つぐらいの団体、全ての団体というか、どこら辺までの団体を想定しているのか。","respondent":"築山障害者施策推進担当課長","answer":"素案のご報告ですが、パブリックコメントを実施する前の段階になります。ですので、計画どおりいけば、１月の厚生委員会でご報告できるのではないかと考えております。ヒアリングの対象団体ですが、区で把握しております１３の団体となっています。","voiceIndex":51,"id":"exchange-022"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"１３の団体の、７団体は分かるのですが、それ以外の団体名を教えていただけますでしょうか。","respondent":"築山障害者施策推進担当課長","answer":"１３団体ですが、基礎調査をやったときに障害者団体にヒアリングを実施しております。その時と同じ団体になっております。","voiceIndex":53,"id":"exchange-023"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"その基礎調査というのは、報告書に出ていますか。こちらで調べれば分かるのかどうかだけ、教えてください。","respondent":"築山障害者施策推進担当課長","answer":"調査結果のほうに出ております。","voiceIndex":55,"id":"exchange-024"}]},{"id":"topic-03","title":"冒頭申し上げましたとおり、取上げる順番を変更し、報告事項(4)から先に行います。 それでは","agenda":"冒頭申し上げましたとおり、取上げる順番を変更し、報告事項(4)から先に行います。 それでは","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"大規模改修ということですが、令和２年度、今年度に基本設計で、来年度に実施設計ということですが、今の時点で分かっている大規模改修の主な中身を教えていただきたいのと、あと、荏原特別養護老人ホームにしても、中身そのものは変わらないと考えていいのか。","respondent":"榎本荏原保健センター所長、宮尾高齢者福祉課長","answer":"今の時点で分かっている改修についての内容ということですが、現在行っております事業はそのまま、階数や内容等を維持して実施できるような体制を取りたいと考えていますので、基本設計の大枠が決まったということで。特別養護老人ホーム部分につきましては、今回の大規模改修によって、特に機能を変更するとか、そういったことは今のところ予定しておりません。","voiceIndex":64,"id":"exchange-025"}]},{"id":"topic-04","title":"新型コロナウイルス感染症に係る保健所・保健センターの対応","agenda":"新型コロナウイルス感染症に係る保健所・保健センターの対応","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"高齢者施設と障害者施設の従業員に対してＰＣＲ検査を行うという補正予算が組まれました。それをいつ実施するのかということをお伺いしておきたいのが第１点。それからもう１つは、都が区市町村と協働してＰＣＲ検査を行うと。それに対して品川区はどのように申込んだのか、申請しているのか、その点をお伺いしたいと思います。","respondent":"鷹箸保健予防課長","answer":"その他の対象者に対する検査をどのように拡大するかということについて、保健所の方針は現状、特段変更しておりませんが、高齢者施設等、高齢者福祉課等の考え方については、保健所として現状把握してございません。","voiceIndex":72,"id":"exchange-026"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"新型コロナウイルス感染症の感染状況ですが、１１月に入って全国的にもすごく増えてきている状況にあると思うのですが、品川区はどんな状況になっているのか。これから寒くなり、乾燥する冬になっていくにつれ、さらに広がっていくのではないかという懸念もかなり報道されているところですが、それに対して区はどう対策を取っていこうという考えなのか、その点について１点、伺いたいと思います。","respondent":"鷹箸保健予防課長","answer":"２点目の都の検査の助成ですが、こちらについては本部で検討するという形ではありませんが、保健所の考え方については特段変更ございませんで、陽性者が出た場合に広く検査をし、それも迅速に検査をする、それから必要がある場合には複数回検査をするという方針で進めています。","voiceIndex":74,"id":"exchange-027"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"私は、新型コロナウイルス感染症対策本部にいろいろ聞いても、なかなか中身が分からなくて、感染状況もよく分からなくて、これは保健所だ、これはＰＣＲ検査センターだみたいな感じにいつもなるので、新型コロナウイルス感染症対策本部の中でそこら辺のところも共有できるような形に、保健所からの働きかけも必要なのではないかと思うのですが、その点についてもいかがでしょうか。","respondent":"鷹箸保健予防課長","answer":"ですので、例えば今回、補助金ができたのでどこかの施設、地域全体というような考え方に方針が変わるというものではございませんので、先ほどもお話ししたとおりですが、陽性者が出たときに、急いでというか、適切な時期もあるのですが。","voiceIndex":76,"id":"exchange-028"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"ということは、東京都がこういう補助金を出しますよということで予算を組まれましたが、これに対して、区としては必要だと捉えていないので、申請はしないということでしょうか。","respondent":"鷹箸保健予防課長","answer":"その中の、外からの持込みで、入所者と接点があるのは従業員の方々ということで、正確な時期は私のほうで把握しておりませんが、そう遠くない時期に区内の施設の従業員の方についてはきっちりと検査をされると伺っておりますので、今後、この補助金を活用して。","voiceIndex":78,"id":"exchange-029"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"ということは、障害者福祉だったら障害者福祉課、高齢者福祉だったら高齢者福祉課で検討した結果、こういうことでやりたいということはあるかもしれないけれど、やるべきだからやったほうがいいのではないかという保健所からの発信は、今までの考え方を踏襲すると、ないという方針で確認させていただいていいでしょうか。","respondent":"鷹箸保健予防課長","answer":"今回、都の補助金を活用して福祉部門の高齢者ですとか障害者の施設で何らかの新たな方針を出される場合には、また改めてご相談があろうかと思いますが、少なくとも本日の時点では特段ご相談を頂いておりませんので、福祉部でも相当きっちり固めてからでないと我々のところに。","voiceIndex":80,"id":"exchange-030"},{"speaker":"あくつ委員","kind":"質問・要望","question":"確認させていただきたいと思います。前回の委員会でもたしか触れられたと思うのですが、次の報告にも関係あるのですが、ＣＯＣＯＡの接触通知があって相談を受けている方が、今、相談の大体どれぐらいの割合、たしか前は４割ぐらいに増えてきたというお話があったのですが、感触としては変わっていないのかどうかということが１つ。その３点、お伺いしたいと思います。","respondent":"鷹箸保健予防課長","answer":"ただ、症状のある方が結構多かったので、ＣＯＣＯＡ通知で検査をしたから陽性なのか、もともと症状があって陽性なのかというのは、なかなか判断が難しいところかなと考えています。ＣＯＣＯＡ通知については以上です。次の報告でＣＯＣＯＡについてはご説明したいと思います。","voiceIndex":83,"id":"exchange-031"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3580#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":22987,"voices":94}},{"id":"r02-20201109-8","meetingId":"r02-cm11","date":"2020年11月9日","dateIso":"2020-11-09","committee":"建設委員会","time":"午後 １時００分～午後 ５時０１分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を90件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"（仮称）旗の台六丁目公園整備に向けた都市計画決定","agenda":"（仮称）旗の台六丁目公園整備に向けた都市計画決定","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"今、基本計画を策定中ということで、この間、ワークショップを２回実施されたということですけれども、このワークショップでのやり取り、今の状況をお聞かせいただけたらと思います。このワークショップは何人くらいでやられているのか、伺いたいと思います。","respondent":"高梨公園課長","answer":"都市計画公園と防災公園との違い、今回の都市計画手続きについてのご質問ですが、当該地につきましては、ご説明させていただいたとおり、周辺に公園がなく、かねてから上位計画で公園整備が望まれていた地区であるということから、都市計画の手続きを行って。","voiceIndex":5,"id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"公園の違いについては、広域的な見方と地域での見方というところでの違いというお話だったと思うのですが、規模とかによる違いというのは特にないのでしょうか。","respondent":"高梨公園課長","answer":"規模として、都市計画公園として定めるのであれば、街区公園として平均０.２５ｈａ以上という都市計画法上の規定はあるものの、なかなか品川区ではそういった規定に基づく大きな公園の設置は難しいといったところもありまして、品川区の中で見て。","voiceIndex":7,"id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"今、ワークショップをやられて、地域の方といろいろ様々な意見を聞きながら進めていらっしゃるということですので、そういった住民の声を反映させて造っていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-003"},{"speaker":"田中委員","kind":"質問・要望","question":"ですので、今後も、こうした手話通訳についての記載を求めたいのですけれども、そこのところはいかがでしょうかというのが１点と、また、説明会のときに、多分、パワーポイントとかを使われると思うのですけれども、そのときの視覚障害者の方に向けた説明をどのように考えているのかといったことを聞きたいと思います。","respondent":"高梨公園課長","answer":"視覚障害のある方への説明会での対応といったところなのですが、どうしてもやはり紙ベースであったり、当日、パワーポイントを見ていただいての説明といったところがメインになってしまいますので。","voiceIndex":11,"id":"exchange-004"},{"speaker":"田中委員","kind":"質問・要望","question":"視覚障害の方に向けた説明会の実施についてのお知らせというのはどのようにされているのか。そうでないと説明会自体も分からないので、そういった周知についても伺いたいというのと、説明会のときに視覚障害の方が突然来られたとしても対応ができるように、ぜひ検討というか、実施していただきたいと思いますが、その辺、いかがでしょうか。","respondent":"高梨公園課長","answer":"説明会等での、来られた際の突発的な対応といったところにつきましては、展示等の準備であるとか、いろいろノウハウは考えられるところではありますが、実際に、どのような対応が現実的に可能かといったところにつきましては、今後の検討課題とさせていただきたいと思います。","voiceIndex":13,"id":"exchange-005"},{"speaker":"西本委員","kind":"質問","question":"１点目は、都市計画公園とした理由を知りたいのです。なぜそれを選んだのかということで。それと、補助金というのが、都市計画公園にはどういう関係が発生してくるのでしょうか。それと、ワークショップを２５人という形で２回ほどされたということなのですけれども、この２５人というのは公募でしょうか。それとも、割当てになっているのでしょうか。教えてください。","respondent":"高梨公園課長","answer":"２番目の質問にも関連するのですが、都市計画公園の整備といったところで、都市計画交付金等の東京都の財源等も充当を考えているところですので、都市計画公園としてはしっかりと手続きを進めるとともに、東京都からの補助金もしっかりと獲得していきたいと考えているところです。","voiceIndex":16,"id":"exchange-006"},{"speaker":"西本委員","kind":"質問・要望","question":"都市計画公園の理由、上位計画というのは分かるのですけれども、そうではなくて、上位計画があったらどれでも都市計画公園になるのですかという話になってしまうのです。区の一般財源から出すのではなくて、上位計画があれば、そこでの公園を造るというときには補助金が使えるという形になるのですよねという、その関係がどうなのだろうと思ってお聞きしましたので、もう少し教えてほしいと思います。","respondent":"高梨公園課長","answer":"理由としましては、たとえ補助金を獲得できるからといって、仮なのですが、この旗の台六丁目公園の整備ができました、その２軒隣りにまた公園の用地ができまして、ここも都市計画公園ですというのは。","voiceIndex":18,"id":"exchange-007"},{"speaker":"西本委員","kind":"質問・要望","question":"お茶の水女子大学とお話ができてよかったと思います。そういうのがあると、何かしらきっかけというか、たまたま今回は教えていただいたというきっかけがあったとは思うのですけれども、そういう何かしら情報が得られるような仕組みがあるといいなと思いましたので、今後、そういうものも検討していただきたいと思います。意外といいのです。今後とも、いい公園ができるように、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-008"}]},{"id":"topic-02","title":"水辺のライトアップ整備工事（アイル橋）","agenda":"水辺のライトアップ整備工事（アイル橋）","exchanges":[{"speaker":"西本委員","kind":"質問","question":"契約金額などは今総務委員会で話されていると思うのですけれども、ランニングコストとかというのはどのくらいかかるものなのでしょうか。それと、目的のところに、「にぎわう観光・交流の軸となることを目指し」とありますが、これは、そうすると、文化観光課とかといろいろと共同で何かやろうとしているのか、どういうことを想定されているのか、お聞きしたいと思います。","respondent":"松本河川下水道課長","answer":"ご質問、２点あったと認識しております。ランニングコストといたしましては、電気代、設備の清掃費、設備の点検費、カーボン・オフセットをしていますので、それらの費用としまして、年間で１橋当たり約７５万円程度を想定しております。","voiceIndex":25,"id":"exchange-009"},{"speaker":"西本委員","kind":"質問","question":"１橋７５万円と言っていたのですけれども、このアイル橋で７５万円ということですか。その７５万円の意味が、ここだけのものなのか、ほかもそのくらいなのか。それはどういう意味になっているのでしょうか。","respondent":"松本河川下水道課長","answer":"７５万円というのは、１つの橋当たり７５万円ということになってあります。","voiceIndex":27,"id":"exchange-010"},{"speaker":"西本委員","kind":"質問","question":"今日はこのアイル橋になりますけれども、この１３橋は既にかかっている部分があって、これは何番目なのですか。それとも、もうこれで最後、１３橋が全部ライトアップされていますということなのでしょうか。","respondent":"松本河川下水道課長","answer":"ライトアップにつきましては、今までで８橋かかってあります。今年度、残りの５橋をやる予定でございまして、今、要津橋のライトアップと、今回のアイル橋のライトアップ工事が進んでいるところです。残り３橋につきましては、今後、契約をしていく予定です。","voiceIndex":31,"id":"exchange-011"},{"speaker":"西本委員","kind":"質問・要望","question":"橋もいろいろと観光資源という形になるかと、もちろん期待はしておりますけれども、これは意見として、ぜひ文化観光課のほうと協力体制を取っていただいて、これも一つの大きな目玉になるように工夫していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":33,"id":"exchange-012"},{"speaker":"田中委員","kind":"意見","question":"区民委員会とかでも、イルミネーションで総額で幾らとかいうのを、答えてもらったことがあったのです。そこでもＬＥＤのやつで幾らとか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":39,"id":"exchange-013"},{"speaker":"田中委員","kind":"質問","question":"私が伺いたかったのが、この１つの橋でかかる金額だったのですけれども、ＬＥＤがどのくらい使われて幾ら、ＬＥＤの設置代に幾らとか、そういった内訳があると思うのですけれども……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-014"},{"speaker":"のだて委員","kind":"意見","question":"今、このアイル橋については１億２,６５０万円と。事務事業概要で見ると、ライトアップの予算というのが６億１,３５７万円ということで出ていたのですけれども、そういった予算は、今はやはりコロナ対策のほうに充てていくことが必要なのではないかと思ってしまうのですが、いかがかということと、あと……。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":46,"id":"exchange-015"},{"speaker":"のだて委員","kind":"質問・要望","question":"予算を要望するのはここの課だと思うので、そこの考え方を伺いたいと思ったのですが、お答えできたら答えていただきたいのと、あと、橋のライトアップが、先ほど少しありましたけれども、水辺の観光とか交流の軸にしていくということに、どのように寄与していくのかというところを伺いたいと思います。","respondent":"松本河川下水道課長","answer":"ライトアップにつきましては、平成３０年度から、ヒカリの水辺プロジェクトということで、河川下水道課のほうで橋のライトアップを進めているところです。先ほどお伝えしましたように、今回整備することで、今年度で全部で１３橋がつくこととなっています。","voiceIndex":48,"id":"exchange-016"},{"speaker":"のだて委員","kind":"質問","question":"というのと、あと、社会運動のカラーをやっていくということで、最後に１点、事務事業概要にアウェアネスカラーというのが書いてありましたけれども、区としてはどういったことをやっていくのか。ピンクリボンデーというのは１つ書いてありましたが、ほかのものはどういったことをやっていくのか、伺いたいと思います。","respondent":"松本河川下水道課長","answer":"これは東京都のほうも示しておりまして、それと合わせたような形の連携をした対応といたしまして、例えば、４月２日に世界自閉症啓発デーということで、自閉症の理解・支援をする応援メッセージということを、こちらも色はブルーです。","voiceIndex":50,"id":"exchange-017"},{"speaker":"大沢委員","kind":"質問","question":"この委員会と違うといえば違うのですが、委員長にご指摘いただければ。今、課長の答弁の中で、観光という話の中で、経済も戻りつつあるというお話をいただいたのですが、何を根拠におっしゃっているのか、教えてください。","respondent":"松本河川下水道課長","answer":"すみません。戻りつつというか、申し訳ございません。そこは発言を撤回させていただきたいと思うのですが、経済が戻るように努力していくです。","voiceIndex":53,"id":"exchange-018"},{"speaker":"石田（秀）委員","kind":"質問","question":"１点だけお伺いしたいのですが、簡単に言うと、これは人道橋ですよね。そうすると、先ほどメッセージ性という話もあった。そういうことはお考えの中になかったのかということをお伺いしたい。","respondent":"松本河川下水道課長","answer":"今お話がありましたのは、天王洲ふれあい橋のことだと思います。こちらのライトアップにつきましては、天王洲のほうで実施していただいたという経緯がございまして、特段、私たちの計画の中にはそこの中には入れていなかったです。","voiceIndex":57,"id":"exchange-019"},{"speaker":"石田（秀）委員","kind":"質問","question":"要は、幕を張って、全部アートで、両面から見られるアートみたいなものをやって、これにはメッセージ性もあるわけではないですか。車が走っているところだと、なかなか上にかけるということができないではないですか。せっかくアートもあれだけやっているのであれば、ライトアップするのであれば、そういうチャレンジ的な部分もあってもいいと思うのだけれども、そこら辺はどうお考えですかということです。","respondent":"松本河川下水道課長、藤田防災まちづくり部長","answer":"アイル橋にそういったメッセージ性のものをですが、基本的に橋の所管につきましては、ここの所管が分かっていないところがありますが、私たち河川下水道課としてはライトアップのところの整備を任されておりますので。そのほか、これから屋外広告物等のことも含めて、地元の協議会のほうとも少しいろいろお話をさせていただきながら、よりよい形については検討させていただきたいと考えています。","voiceIndex":59,"id":"exchange-020"}]},{"id":"topic-03","title":"令和３年度からの不燃化特区支援制度","agenda":"令和３年度からの不燃化特区支援制度","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"木造住宅が立ち並んでいるところというのはほかにも結構あると思うのです。この支援制度があることで建て替えが進んできたというのもあると思うので、ぜひ区内で建て替えを進めていくためには、やはりこの支援制度をさらに広げていくということが必要なのではないかと思うのですけれども、いかがでしょうかということと、あと、申請するにあたっての条件というのはどういったものがあるのか、伺います。","respondent":"佐藤木密整備推進課長","answer":"最後に、助成の要件ですけれども、助成制度については、３点、解体の助成、引っ越しに係る移転の助成、また、建て替えの助成ということになりますけれども、１つ目の老朽家屋の解体助成というのが前提になってまいりますので、その建物が一定の要件。","voiceIndex":67,"id":"exchange-021"},{"speaker":"のだて委員","kind":"質問","question":"優先度が高いところということで、今回、この３つ、西品川一丁目と大井二丁目と西中延三丁目ということで新たに追加するということですけれども、優先度が高いというところが、どういう優先度が高いのか、お伺いしたいと思うのと、あと、申請する条件というのは、個々の住宅ではなくて、区が不燃化特区支援制度の新たな地区を増やすために申請するにあたって、必要な条件というのがあるのかどうか。","respondent":"佐藤木密整備推進課長","answer":"１つ目の、優先度が高いということの内容ですけれども、まず、大井二丁目、西中延三丁目につきましては、特区の現在行っております事業実施地区を除きますと、最も不燃領域率、燃えにくさを表す指標ですけれども、こちらが低い地域となっております。","voiceIndex":69,"id":"exchange-022"},{"speaker":"のだて委員","kind":"質問・要望","question":"優先度が高いということで今回３地区ということですけれども、やはりほかのところでも、建て替えにあたって進めていく必要があるところというのはあると思うので、こういった支援をしていただいて、建て替えを進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-023"},{"speaker":"田中委員","kind":"質問・要望","question":"新たに３地区が加わったことの選定基準は分かりました。ただ、そのほかに、この３地区以外でここもどうかと挙がった地区がもしあったら、その地区も何地区あったのかというのをお知らせいただきたいと思います。","respondent":"佐藤木密整備推進課長","answer":"１つは、不燃領域率。先ほどからご説明しておりますけれども、この値で、現在行っている地域よりも低い地域というのが、大井二丁目と西中延三丁目という地域ですので、ここのところは優先してということで入れております。","voiceIndex":73,"id":"exchange-024"},{"speaker":"田中委員","kind":"意見","question":"この３地区以外にも、ここの３地区ほどはいかなかったけれども、候補に挙がった地区が何地区かあったということだったのですけれども、大体何地区ぐらいというのをお知らせいただければと思います。","respondent":"佐藤木密整備推進課長","answer":"今回挙げた地域以外は、優先度という点からいきますと、現在行っている地域に比べて、まだそこまで不燃領域率が低くないという意味では、それほど優先して行うべき地域ということは言えないかと考えますけれども、総体的には、危険度が全くないということではないので、今後。","voiceIndex":75,"id":"exchange-025"}]},{"id":"topic-04","title":"大井町駅周辺地域のまちづくり","agenda":"大井町駅周辺地域のまちづくり","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"まちづくり方針の策定のほうで伺いたいのですけれども、今回、２回説明会が行われて、１２７名の方が参加をしたということで、いろいろなご意見が出たと思うのですが、その説明会での区の受け止めを伺いたいと思います。","respondent":"多並都市開発課長","answer":"それ以外につきましても、例えば、2)でも、説明会でも広町地区に関するご意見で、やはり駅の混雑緩和であったり、広町地区と駅とのつながりというご意見がありましたので、2)と3)も含めてですけれども、かなりそこら辺については、今回も協議が調ったところについては。","voiceIndex":81,"id":"exchange-026"},{"speaker":"のだて委員","kind":"確認","question":"今のご説明だと、説明会の受け止めは、地域の方からは意見を聞いてほしいという声がたくさん出たという受け止めということでよろしいということか、その確認と、あと、実際、この方針としては今回修正をされたということですけれども、今後、具体的に意見を聞いていくというのはどのようにやっていくのか、そこを伺ったので、ご説明いただけたらと思います。","respondent":"多並都市開発課長","answer":"今後につきましては、都市計画の手続きを来年度予定しているということでこの間もご説明させていただきましたが、それに向けまして、地域説明会、または縦覧手続きであったり、法令に基づいた手続きも含めてしっかりとご説明しながら進めていくということで。","voiceIndex":83,"id":"exchange-027"},{"speaker":"のだて委員","kind":"質問・要望","question":"広町地区については、これから都市計画の手続きを進めていくということですけれども、ほかの周辺地区についても、やはり様々な声が出て、意見を聞いてほしいということですので、そういったところについては、きちんと意見を聞いていく、そうした具体的な策を講じていただきたいと思いますけれども、いかがでしょうかというところと、あと、資料のところで伺いたいのですが、別添２の８ページで。","respondent":"多並都市開発課長","answer":"１点目の、周辺地区の今後の進め方、地域のご意見の伺い方ですけれども、それがまさに地域の方が主体となって、今後のまちをどうしていくかを考えていただくというところですので、それをしっかりと皆さんで考えていただくということを。","voiceIndex":85,"id":"exchange-028"},{"speaker":"のだて委員","kind":"質問・要望","question":"3)が区役所前の通りのところかと思うのですが、4)がどこになるのかと。一応、イメージということですけれども、想定している場所がありましたら、伺いたいと思います。それと、今回、１２ページの資料で、歩行者広場というのが２か所追加されましたけれども、先ほど歩行者空間の確保というお話がありましたが、もう少し詳しくご説明いただけたら、お願いしたいと思います。","respondent":"多並都市開発課長","answer":"その左側の空間につきましての広場空間としましては、先ほどの１１ページのイメージ図の右上の2)になりますけれども、このようなイメージで、交通広場から立体的に上に上がるような形で、その上をたまれるような状態ということで。","voiceIndex":87,"id":"exchange-029"},{"speaker":"のだて委員","kind":"確認","question":"それと、広町地区のまちづくりについてお聞きしたいのですけれども、今回、環境影響評価調査、つまり環境アセスメントを行うということで、これはＪＲの開発についてということで、新庁舎のほうはアセスメントの対象ではないということでいいのかという確認と、今回、環境アセスメントに当てはまるということで、ＪＲの建築計画がどういったものになるのか。そこを伺いたいと思います。","respondent":"多並都市開発課長","answer":"イメージ図のほうからですけれども、イメージとしては、デッキで３層になっていますけれども、ここの土地が、駅の部分と、また、補助２６号線とのつながりの部分と、本当の地べたの部分ということで、非常に高低差があるところなので。","voiceIndex":89,"id":"exchange-030"},{"speaker":"田中委員","kind":"質問","question":"幾つかお伺いしたいのですけれども、まず、１枚目の広町地区のまちづくりについての、今ご説明があったところなのですけれども、縦覧期間について、この周知方法をまず聞きたいのと、あと、ここでは意見書の募集というのはないのかというところを伺いたいのですけれども、いかがでしょうか。","respondent":"多並都市開発課長","answer":"周知としましては、１２月１日号の広報しながわでお知らせする予定としております。意見書については、この縦覧と合わせていただけるようにということで、そのように予定しているということで聞いているところです。","voiceIndex":94,"id":"exchange-031"},{"speaker":"田中委員","kind":"質問","question":"ほかのところでも、縦覧期間の周知が本当に分かりづらくて、なかなか意見を出せなかったということがあるので、ぜひ広報しながわだけにとどまらず、ホームページであったりとか、お知らせをしてほしいと思うのですけれども、そこのところを伺いたいと思います。","respondent":"提坂環境課長","answer":"今、周知方法としては、確かに広報しながわだけにとどまっているかと思いますが、その辺、今後検討する余地がありますので、ホームページに載せられるかどうか、検討してまいりたいと考えています。","voiceIndex":96,"id":"exchange-032"},{"speaker":"田中委員","kind":"質問・要望","question":"これは要望で終わります。次なのですけれども、まちづくり方針の中で、先ほどもありました、２ページと、あと、１３ページにも、「地域の意見を聞きながら」といった文言が入っているのですけれども、この地域に当たる対象、地域とはどこまでを指すのかということを伺いたいのですけれども、いかがでしょうか。","respondent":"多並都市開発課長","answer":"地域というのは、このタイトルにあります大井町駅周辺地域というところを捉えているところです。","voiceIndex":98,"id":"exchange-033"},{"speaker":"田中委員","kind":"質問・要望","question":"どうつながっていくのかというのが不安です。広町地区のほうが浸水ハザードマップに載っているので、そこをどのように考えているのかということと、あと、考え方として、高低差を利用した、例えば、貯水槽を造るようなイメージとか、そういったことは考えられているのかといったことを伺いたいのですけれども、いかがでしょうか。","respondent":"多並都市開発課長","answer":"先ほど高低差を利用して貯水槽というお話がありましたが、これにつきましても、今後の庁舎機能の検討の中で、どのような機能が必要かということは検討していくところになりますので、併せて連携しながら進めていくべきと考えるところです。","voiceIndex":100,"id":"exchange-034"},{"speaker":"田中委員","kind":"質問","question":"貯水槽についてが、庁舎機能でなく、広町地区全体として考えなければいけないのかなというのを思っていて、前回、決算特別委員会でもこのことについて伺ったのですけれども、そのときに、排水事業だったり下水道管のことなどについても設計に入ってくるところなので、非常に重要な設備だと思って、検討といったことだったのですけれども、地域性というところもあって、そして。","respondent":"多並都市開発課長","answer":"そこの計画の中で防災機能をどうしていくかということについては、しっかりと検討していく必要があるということですので、そこの中で今のご意見も踏まえながら検討していくことと考えているところです。","voiceIndex":102,"id":"exchange-035"},{"speaker":"西本委員","kind":"質問・要望","question":"勝手にやるのはいいのかもしれないのですけれども、ただ、誤解されるような状況はすべきではないし、そういうことはやめていただきたいと。説明会にたくさん来ていただくことはありがたいことなのですが、ただ、それが逆にいろいろと利用されてしまうということはいかがなものかと思ったので、そこの仕切りといいますか、例えば、注意するであるとか、していただきたいと考えていますが、いかがでしょうか。","respondent":"多並都市開発課長","answer":"今ありましたように、説明会の案内につきましては、区としてオフィシャルな部分と、知り得なかった部分といろいろあるかと思いますので、そこについては、よく地域の方とも話し合いながら、より適切な方法があるのであれば、それは皆さんと話していきたいと思っているところです。","voiceIndex":105,"id":"exchange-036"},{"speaker":"西本委員","kind":"質問・要望","question":"すごいハードルがあると思います。ただ、ここは何とかしなければいけないという部分もあるので、ご理解を求めながら、いい方向に行けばいいというふうに、これはＣ地区の皆様方のお願いだと考えていますので、ぜひそういう形で、くれぐれも利用されないように、しっかりとした態度を取っていただきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":107,"id":"exchange-037"},{"speaker":"田中委員","kind":"質問・要望","question":"８ページの3)の交通広場なのですけれども、ごめんなさい、先ほどご説明があったかもしれないのですけれども、素案のときにはこの矢印は出ていたと思うのですが、今回このように文言を長く書かれて、交通広場と位置づけられた理由というか、その辺をお知らせいただきたいのですけれども。","respondent":"多並都市開発課長","answer":"先ほど広町地区の中でも少しご説明、１２ページの中でも、歩行者広場というのを設置するということと、交通広場が連携するというところをご説明したいということで、あえて明記させていただいたところです。","voiceIndex":109,"id":"exchange-038"}]},{"id":"topic-05","title":"区内の魅力的な建築物を楽しむイベント「オープンしなけん」","agenda":"区内の魅力的な建築物を楽しむイベント「オープンしなけん」","exchanges":[{"speaker":"西本委員","kind":"質問","question":"参加の申込み期限が１１月６日金曜日で、もう終わってしまっているのです。今、大体どのくらいかというのは分かっているのでしょうか。","respondent":"長尾建築課長","answer":"参加の申込み期限は１１月６日ということで、先週の金曜日に締め切っております。参加の申込みの状況としまして、４日時点の情報になりますけれども、応募の延べ人数としては約４００人弱の方に申し込んでいただいている状況です。","voiceIndex":115,"id":"exchange-039"},{"speaker":"西本委員","kind":"質問","question":"４００人ということですが、これは募集としてこのくらいで、今年はコロナ感染のこともあるので４００人程度がいいということなのか、それとも、もう少し余裕がある状況なのか。いかがですか。","respondent":"長尾建築課長","answer":"今回、１０本の街歩きツアーを企画しておりまして、各ツアーの定員は８名となっております。４００人ほど延べでお申込みいただいていまして、各ツアーとも抽選で８名にこれから決定していく予定となっております。","voiceIndex":117,"id":"exchange-040"}]},{"id":"topic-06","title":"東京港大井ふ頭（都有地内）において確認された「ヒアリ」","agenda":"東京港大井ふ頭（都有地内）において確認された「ヒアリ」","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"区のほうではできないのかもしれないので、都や国のほうでぜひしていただきたいということで、要望していただきたいと思いますが、いかがでしょうかということと、資料に、「駆除を継続して実施」していると書いてあるのですが、これは発見された場所ではすべて駆除されたと考えてよいのか、そこを伺いたいと思います。","respondent":"提坂環境課長","answer":"前回の７月とは別ルートで侵入したものと考えるとご説明いたしまして、国のほうでは、環境省の主催で港湾事業者向けのヒアリの講習会を実施、あと、荷物の積込み時ですとか出荷時での疑わしいアリ発見時の対応等の周知を行っているということで。","voiceIndex":123,"id":"exchange-041"},{"speaker":"のだて委員","kind":"質問・要望","question":"今、国のほうで対応しているということですので、出荷元の対策がどうか分からないというお話もありましたけれども、そういったところも国で事前に入ってこないようにしてもらう対策をぜひきちんとやっていただくということと、あと、この調査、今年度はこれでやらないとなると、このペースで見ると、また発生する可能性があるのかなと思いますので、今年度あと１回くらいはやっていただくように。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":125,"id":"exchange-042"},{"speaker":"若林委員","kind":"確認","question":"最初、５００個体等が確認されて、そのままこの事業者のほうで殺虫餌を設置したという説明があって、それが１０月２日ですね。国がどういう説明をしているかというのが１つ確認と、前回も説明があったかどうか、すみません、議事録が追えなかったので、２の区の対応状況の一番最後の、全５回予定の（生息調査の）ところの区有施設６か所、この６か所の具体的な場所を教えてください。","respondent":"提坂環境課長","answer":"区有施設調査ですけれども、６か所ということで、具体的には、品川南ふ頭公園、天王洲公園、東品川海上公園、八潮北公園、みなとが丘ふ頭公園の中の品川区キャンプ場、東品川清掃作業所、こちらの６か所です。","voiceIndex":127,"id":"exchange-043"}]},{"id":"topic-07","title":"令和２年度 ウォームビズキャンペーンの実施","agenda":"令和２年度 ウォームビズキャンペーンの実施","exchanges":[{"speaker":"田中委員","kind":"質問","question":"実施内容の（１）で、庁舎の室温とかの温度があるのですけれども、今回、感染症の広がりとかがあって、温度はこれがいいとは思うのですけれども、ただ、換気をしていく中で室温が下がってしまう。そういったときの対策というか、感染症対策もやはり入れていかなければいけないのだろうと思うのですけれども、どのようにお考えなのか、伺いたいと思います。","respondent":"提坂環境課長","answer":"自動的に換気の機能というか、排気の機能があるということなので、その辺をうまく利用しながら室温を保つような工夫をいたしたいと思います。その辺は、経理課の庁舎管理の担当と連携してやっていきたいと考えています。","voiceIndex":133,"id":"exchange-044"}]},{"id":"topic-08","title":"特定整備路線放射２号線沿道の都市計画変更に伴う説明会の実施","agenda":"特定整備路線放射２号線沿道の都市計画変更に伴う説明会の実施","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"資料について伺いたいのですが、特別工業地区というのが、「地場産業の保護育成と公害の防止を図る地区」と資料に書かれていますけれども、今回、商業地域に変わるところがありますけれども、つまりは、地場産業の保護は必要ない、なくなったということなのか、伺います。","respondent":"鈴木都市計画課長","answer":"今お話しいただきました、別紙の資料で言いますと、3)のところですが、沿道のところがもともと商業地域というところで、それに合わせて３０ｍ広がる部分について、準工業地域のところを商業地域に、路線型の商業地域ということで合わせていくわけなのですが、基本的には。","voiceIndex":139,"id":"exchange-045"},{"speaker":"のだて委員","kind":"質問","question":"もともとこの放射２号線のところは、そもそもあまり木密ではないという地域で、この特定整備路線に選定されたのも、どうかと。おかしな話だと思っているのですけれども、そうした中で、今回、星薬科大学が、この放射２号線によって分断されてしまうということになりますけれども、星薬科大学のほうでは何か話は聞いているのか、どういった状況になっているのか、伺いたいと思います。説明なども含めて。","respondent":"鈴木都市計画課長","answer":"道路に合わせて、それが完全にできてから、沿道の用途地域、最低限高度７ｍですとか、防火地域の変更をかけるというやり方よりも、今まさに交渉が進んでいる中で、建て替えも行われている、進んでいることに合わせて、一刻も早く沿道の容積、用途地域等も見直すことで。","voiceIndex":141,"id":"exchange-046"},{"speaker":"のだて委員","kind":"質問","question":"できた後よりも今進めていくというお話でしたけれども、それが万が一、万が一というか、私たちは中止にするために頑張っておりますが、放射２号線が廃止になった場合に、その沿道で高い建物が建っていくとすると、こうした建物は、どうなってしまうのでしょうか。","respondent":"鈴木都市計画課長","answer":"今のご質問は、万が一中止になった場合ということだとは思いますが、基本的には、東京都が今、事業を進めている中で、やはり木密地域あるいは地域の防災性の向上というのは、いつ来るか分からない地震への備えということでは喫緊の課題ですので。","voiceIndex":143,"id":"exchange-047"},{"speaker":"のだて委員","kind":"質問","question":"仮定の話はしないということでしたけれども、実際にある程度進んだところで廃止になったところもあるというところで言いますと、やはり私はこの放射２号線は必要ないと思いますし、脇に中原街道が通っているというところでも必要ないと思っていますので、中止すべきだと思いますけれども、そういった中では、防災性のためということで区や都は進めているわけですが。","respondent":"鈴木都市計画課長","answer":"都市計画道路の整備につきましては、東京都が鋭意、地域へしっかりと説明しながら、現在進めているところです。","voiceIndex":145,"id":"exchange-048"},{"speaker":"のだて委員","kind":"質問・要望","question":"地域に根差したというか、しっかりと防災性を高めていくという意味では、耐震化ですとか不燃化、建て替えをやっていく、そういったことを強化していく、後押ししていくということのほうが、今住んでいる人たちも協力しやすいということになります。そのほうが早く防災性が向上していくのではないかと思いますので、この手続きは進めるべきではないと要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":147,"id":"exchange-049"},{"speaker":"田中委員","kind":"質問・要望","question":"この４０ｍ以内という根拠をお知らせいただきたいというのと、あと、区立学校とかも近くにありますよね。やはりそこへの影響とかもあるので、学校へのお知らせ、保護者へ向けたお知らせというのもされるのかといったところも知りたくて、お伺いしたいと思います。","respondent":"鈴木都市計画課長","answer":"ただ、影響としても、既に学校については３階建て以上の建物になっておりますし、防火地域、準防火地域がかかったとしても、既に耐火建築物ですので、この変更によって何か学校が今後建て替えのときに、今の機能が損なわれるようなものが建てられないとか。","voiceIndex":149,"id":"exchange-050"},{"speaker":"田中委員","kind":"質問・要望","question":"学校が３階以上というのは分かるのですけれども、学校周辺に高いものとかが建ってしまったりしたときに、日照とかの問題も出てきて影響があるので、保護者にも説明が必要なのではないかという、そういった意味で伺っています。","respondent":"鈴木都市計画課長","answer":"学校の周辺の建物について、高い建物が建ってしまうのではないかというところと併せて、保護者への説明が必要なのではないかですが、基本的には、最低限度高度地区の考え方は、例えば、特に今回、エリア内にある学校の周辺の建蔽率とか容積率がアップされて。","voiceIndex":151,"id":"exchange-051"},{"speaker":"田中委員","kind":"質問・要望","question":"そういったこともありますし、荏原第一中学校のほうもそうですし、求められればといっても、なかなかこういった情報が届かないというか、なかなかつかみにくい情報なので、ぜひ積極的に区のほうから伝えていただきたいというのと、会場が第一日野小学校と荏原第一中学校なので、学校のお知らせとかは外に向かって貼りつけてあったりするではないですか。","respondent":"鈴木都市計画課長","answer":"学校の都市計画道路内、あるいは学校のところの沿道の３０ｍの範囲の用途変更にかかるところにお住まいの方々については、当然直接、説明を求められればと私は先ほどお話ししましたが、基本的には学校が対象で、その沿道の方々が。","voiceIndex":153,"id":"exchange-052"},{"speaker":"田中委員","kind":"質問","question":"説明会の掲示を学校でされるのか。学校に掲示板というのがあるではないですか。","respondent":"鈴木都市計画課長","answer":"当日ということではなくて、従前からということですか。関係の方には直接郵送して、あるいは投函をしてお知らせしますので、例えば、１週間前とか２週前から学校の掲示板に、いつ説明会を行いますというお知らせを掲示していただくということは考えてございません。","voiceIndex":155,"id":"exchange-053"},{"speaker":"田中委員","kind":"質問・要望","question":"子どもも保護者も、学校に関わることなので、そこに通う方たちも関係することだと思うのです。なので、せめて説明会の日程、こういう説明会をこの学校のここで行いますくらいの掲示をする、その程度だけでもいいので、周知方法の一つとしてしてほしいと要望したいのですけれども、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"先ほどからご説明しているように、この変更の対象となる必要な方々に直接お知らせをしていくということで、今、考えているところです。","voiceIndex":157,"id":"exchange-054"},{"speaker":"田中委員","kind":"質問・要望","question":"今ご説明いただいたことを保護者の方に説明していただきたいのです。だから、学校の……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":159,"id":"exchange-055"},{"speaker":"田中委員","kind":"質問・要望","question":"沿道に関係する人といったお話なのですけれども、沿道に学校があるので今話をしていて、学校に関わる保護者だったり、そこに通う子どもたちも、そこに住んでいなかったとしても、学校に通っているところで関係するではないですか。そういった意味で言っています。実際にどうなっているのかと気にしているのです。ですので、ぜひそういったお知らせをしてほしいと言っているのですけれども、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"そこに学校のほうで必要に応じて保護者の方に説明する必要があるのであれば、それは学校のほうの判断でやっていただくような、学校に限らず民間の建物もそうですが、これは建物を所有の方が、利用者含めて外側、どれだけ外側が膨らむかは一定あると思うのですが。","voiceIndex":161,"id":"exchange-056"},{"speaker":"田中委員","kind":"質問・要望","question":"説明を求めていただきたいということもあったので、そういった連携がきちんと取られるということを確認したいというのと、すみません、先ほどの都市計画法の第１７条の縦覧・意見書のほうなのですけれども、ホームページのほうでの記載の方法、お知らせとかのトップページですぐに確認ができるような周知方法となるのかといったところを、確認と要望をさせていただきたいのですけれども、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"ホームページでの周知につきましては、当然、できるだけ分かりやすく、ただ、トップページの一番見やすいところにぽんと常時張りつくというのは、今、いろいろな情報がありますので、それは全体の区の広報の観点からの順位づけというか。","voiceIndex":163,"id":"exchange-057"}]},{"id":"topic-09","title":"航空機騒音の常時測定結果","agenda":"航空機騒音の常時測定結果","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回、区の騒音測定結果ということですが、４、５、６月を見ますと、飛んできた回数なども含めて、６月が一番うるさかったのかなと私は受け止めましたけれども、そうした中で、区や国などへの苦情の件数というのは、どうなっていますでしょうか。教えていただけたらと思います。","respondent":"鈴木都市計画課長","answer":"区への苦情等の問合せの件数ですが、４月が２６件、５月が２７件、６月が２４件、７月が３３件、８月が３０件、９月が３０件、１０月が１７件、本格開始以降これまで１８７件の電話等のお問合せをいただいてあります。","voiceIndex":169,"id":"exchange-058"},{"speaker":"のだて委員","kind":"質問","question":"それでいいのかどうかと思うのですけれども。今回、いろいろ、最大、最小と、結構、幅があるのですが、一番大きいところだと８４.２ｄＢということで最大の騒音値が出ておりますが、これはやはりこの間の国が示してきた推計値から見ると、大幅にオーバーしていると思うのですけれども、こうしたことについて国から説明を受けたり、あるいは抗議をしたりということをしたのかどうか、伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"年間Ｌｄｅｎの考え方は、まさに１年間のデータとしてＬｄｅｎとして取りまとめて出すものですので、これは住宅の防音工事助成などの考え方のデータに基づく基本となるものが年間のＬｄｅｎという考え方ですから、４月より測定を開始していますので。","voiceIndex":171,"id":"exchange-059"},{"speaker":"のだて委員","kind":"質問・要望","question":"は確認ということですが、やはり８４ｄＢというのは、立会小学校、台場小学校どちらも１回だけなのか。教育への影響などは、学校や教育委員会などから話が出ているのかどうかということと、今回、調査結果をまとめた中で、区の受け止めというのですか、この結果をどう見ているのか、伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"したがいまして、国が出しているものとの比較はできないのですが、先ほどご説明したとおり、この２地点については、８４ｄＢというのが、例えば、台場小学校でいうと、６月でいうと７３２回、あるいは４月でいうと６６４回、立会小学校のほうは、６月でいうと３４８回ですとか。","voiceIndex":173,"id":"exchange-060"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはりこうした区民の被害を率直に受け止めていただいて、羽田新飛行ルートの中止を求めていくという立場に立っていただきたいと思いますけれども、いかがでしょうか。６月でも、立会小学校では７回ありますし、台場小学校では４回という状況ですので、やはりこうした騒音の被害というのは大きいと思うのですけれども、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"区としましては、やはりこうした区民の不安の払拭に向けて、こうした声をしっかりと国に届けていくというところと、特に落下物、騒音に対する取組については、今後もさらに進めていただきたいというところを国のほうには継続して強く申入れをしていきたいです。","voiceIndex":175,"id":"exchange-061"},{"speaker":"のだて委員","kind":"質問","question":"最後に１点伺いたいと思います。この騒音の区民への影響を問題だとは思っていないのか、伺います。","respondent":"鈴木都市計画課長","answer":"そうした声が区に届いているというところを受け止めて、区のほうは、先ほどご答弁申し上げたように、しっかりと国に届けて、取組を求めているです。","voiceIndex":177,"id":"exchange-062"},{"speaker":"田中委員","kind":"確認","question":"お伺いしたいのですけれども、これだけ細かなものが出るということは、学校に限らず、福祉施設などに通う方たちの体調や具合の変化というのも、この測定結果と併せて、どんな変化が表れているのかというのがきっと調査できると思うのですけれども、そういった確認というのを今後してほしいのですが、そこのお考えを伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"そうした影響があるかどうか、その調査の必要があるかどうか、どういった調査を行うといいのかどうかも含めて、そうした判断、検討、実施は、やはりこれは事業主体である国が責任を持って行っていくべきだと考えますし、その必要性があれば。","voiceIndex":180,"id":"exchange-063"},{"speaker":"田中委員","kind":"質問・要望","question":"子どもたちの施設だけに限らず、障害のある方たちへの影響といったこともあるのです。事業主体が国であるというのは分かっています。騒音もこれだけ数字として表れていて、８０ｄＢを超えたか超えていないかとか、そういう問題でもなくて、本当に騒音の影響というのがあるので、自治体としてきちんとそれはやっていくべきだと思うので、そこのお考えをもう一回伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"固定化回避に向けた第２回目の検討会の開催状況ですが、年度末にはメリット、デメリットを整理するというところを公表していくということまでは伺っているのですが、その間の２回目、３回目の開催の予定については、これは折に触れて、くどいくらい問合せはしているのですが。","voiceIndex":182,"id":"exchange-064"},{"speaker":"田中委員","kind":"質問","question":"どうですかと。区でも騒音の測定を調査しているので、そこに照らし合わせて、体調の変化とかを見ていこうと思うのですけれどもいかがですかといったような呼びかけがあってもいいと思うのです。ですので、そこら辺についてもう一度、前向きなご答弁をいただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":184,"id":"exchange-065"},{"speaker":"田中委員","kind":"質問・要望","question":"分かりました。常々伺っているそうなのですけれども、なかなか示されないということでした。やっと検討会が設置されたということだったのですけれども、検討会において、新飛行ルートの滑走路運用および発着便数を再検討することは考えていないといった、国のほうでご答弁というか、あったそうなのですけれども、そこについて区として把握しているのか伺いたいのですけれども、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"固定化回避の中身について、国の中でのやり取りの中で、今ある滑走路の運用を基本としつつということを国のほうが答えたということは、今、委員にご紹介いただいたところも承知していますが、もともとこの検討会の名前にもありますように。","voiceIndex":186,"id":"exchange-066"},{"speaker":"田中委員","kind":"質問・要望","question":"検討会についても、国でのやり取りについて区としても把握しているけれども、再検討することは考えていない、何も考えていないという国の考えではないと区としては受け止めているということでしたが、区として、今、検討会第２回目を実施することを求めているのもそうなのですけれども、それも口頭ですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":188,"id":"exchange-067"},{"speaker":"田中委員","kind":"質問・要望","question":"区としても、検討会は自分たちが実施させたといったこともあるので、もっと強く求めてほしいと思うのですけれども、そこら辺も伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"固定化回避に向けた取組を文書としてしっかりと求めているのかですが、昨年８月に、国が飛行ルートについて本格運用を決定した前の段階で、東京都の会議の中で、副区長が参加をして、しっかりと区としての求めるべき、これは固定化回避も含めてですが、発言をして。","voiceIndex":190,"id":"exchange-068"},{"speaker":"田中委員","kind":"質問・要望","question":"多分毎回私、言っていると思うのですけれども、航空機騒音の測定結果の報告も含めて、次回から、区への騒音に対する問合せの件数と、測定の結果と、あと、検討会の状況、国とのやり取りの状況をきちんと報告してほしいというのを強く要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":192,"id":"exchange-069"},{"speaker":"西本委員","kind":"質問・要望","question":"ですので、このデータを見ると、便数もおそらく何倍くらいになるのですかね。品川区独自でこの２か所のデータを取られたということは、非常に私は評価をしております。やはり品川区独自で調査していくということは本当に大切なことですから、それは評価をして、これからも続けていただきたいと思っていますけれども、このデータの見方というのはどのように見ればよいか。","respondent":"鈴木都市計画課長","answer":"５月になりますと、Ａ滑走路が７１％減で、Ｃ滑走路が７０％減、６月がＡ滑走路が６４％減、Ｃ滑走路が６３％減ですので、半分以上の件数の結果が、今お示ししている便数の騒音の結果だということなので、単純に考えれば、コロナが終息をして、従前に戻るということになると。","voiceIndex":194,"id":"exchange-070"},{"speaker":"西本委員","kind":"質問・要望","question":"昨年度の比較になるのかどうか分かりませんが、本来であればこのくらい飛ぶはずというのはきちんと言っておかないと、このデータが実際のデータになるのかどうかというのは、今の現状からすると違う結果が今後出てくる可能性もあると考えていますので、それもきちんと公表していただきたいと思います。それで、８４ｄＢということで、かなり高い数字が出ています。区の見解はどうなのでしょう。","respondent":"鈴木都市計画課長","answer":"８４ｄＢ、回数は少ないという話をしましたが、委員ご紹介のように、結果として出ているわけです。これは航空機に由来するものだということも、コンサルを通して確認していますので、事実として実態としてあるということはしっかりと受け止めておりますし、認識しています。","voiceIndex":196,"id":"exchange-071"},{"speaker":"西本委員","kind":"質問・要望","question":"ただ、やっていただきたいのは、区民の人たちがどんなに困っているか、大変な思いをしているのかというのは、今、本当に伝えていただいているというお話でしたので、少々安心はしているのですけれども、信頼をしておりますけれども、やはりそこを品川区の立場としてしっかりと国のほうに伝えていただきたいということを強くお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":198,"id":"exchange-072"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"９１回のうち五十何回飛んでいる。例えば、９３回分の１１回とか、６月だったら４３回とか４６回とか３０回とかあるわけだから、これ、ゼロがあるから、今言った全体はどうだとなるのだろうけれども。別に千葉との約束がどうということは今さら言うつもりもないけれども、この表の見方くらいは、これが表に出るなら、きちんと分かるようにしてほしいと思っていますので、そこら辺の答弁をお願いします。","respondent":"鈴木都市計画課長","answer":"それと、今委員にご指摘いただいたように、夕方３時から７時までで実際飛んでいるのは、切替えもあって、３時半から６時半までというところは、これは運用の考え方としては、本格運用前も実施後も変わっていないのですが、時間の関係を国のほうにはいろいろと聞いているのですが。","voiceIndex":200,"id":"exchange-073"},{"speaker":"石田（秀）委員","kind":"質問","question":"お願いだけしておきます。これは多分南風だと分かるではないですか。あれ、何でだろうと思うときもある。表の見方がきちんと分かるようにしてほしいというのと、あと、今言ったように、３時。本当に、「あ、３時だ」と言ったら飛んで来るときがあるのです。本当に３時前は飛んでいないのです。何回か。これもどこかでそれは分かるようにしてほしいということがあるので、これはお願いだけしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":202,"id":"exchange-074"},{"speaker":"大沢委員","kind":"質問・要望","question":"機があるときで構いません。今すぐとは申し上げませんので、今、途中ですから、なかなか答えも出しづらいでしょうけれども、機があれば、そのような問題意識を持っていただきながら、国の方と接するなりお話をしていただきたいと考えています。これは要望ですので、答弁は結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":203,"id":"exchange-075"}]},{"id":"topic-10","title":"令和２年陳情第５２号、西大井地域に西大井駅経由区役所に通じるコミュニティバス運用を求める陳情","agenda":"令和２年陳情第５２号、西大井地域に西大井駅経由区役所に通じるコミュニティバス運用を求める陳情","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今、ワークショップをやられているということで、それについて伺いたいのですけれども、今回、この陳情が出されているところで、「西大井３丁目、４丁目」と書かれておりますが、その丁目が含まれている大井第三地域でのワークショップでは、どんな意見が出たのでしょうか。それと併せて、これまで開催してきたほかの地域の状況も報告いただければと思います。","respondent":"鈴木都市計画課長","answer":"全体的にいただいているのは、今回、ホームページ上でも示しておりますが、これは試算ですが、収支について、なかなか３ルートとも赤字になるような設定、収支についても説明を差し上げたのですが、やはりできるだけ赤字にならないように、運行時間帯、運行本数を減らすとか。","voiceIndex":209,"id":"exchange-076"},{"speaker":"のだて委員","kind":"質問・要望","question":"大井第三地域については、ワークショップでも西大井三丁目から五丁目の辺りを通してほしいということで声が出ていたということですので、やはりこの地域の中での切実な願いだと思います。そういった中でこのコミュニティバスが通ることになれば、そうした外出を促進することにもなると思いますので、ぜひ考えていただきたいと思うのですけれども、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"今回の陳情にあります西大井三丁目、四丁目、五丁目の辺りは、当委員会のほうでもご説明しておりますし、昨年度の学識経験者を交えた検討会の中で区の考えとしてもお示ししていますが、やはりもともと指標を定めて設定していく中で。","voiceIndex":211,"id":"exchange-077"},{"speaker":"のだて委員","kind":"質問","question":"伺いたいと思います。陳情にも書いてありますが、西大井地域から区役所に行こうと思うと、大森駅に行ってから大井町駅に行って、そこから歩くということで、３０分くらいかかってしまうということで言われておりますので、やはりそういったところを解消していくためにも、コミュニティバスというのが当然役に立ってくると思いますので、ぜひ検討をお願いしたいのですが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"ご紹介いただいた資料の中には、こうしたケースの場合はとかと様々書いてありますが、最終的に判断するのは区ではございませんので、区としては、そういういろいろな制限がある中で、いろいろと検討を重ねて、あるいは地域の声をお聞きして、通したい。","voiceIndex":213,"id":"exchange-078"},{"speaker":"のだて委員","kind":"質問・要望","question":"地域の方から聞いたところによりますと、実際に、この西大井地域でバスが通れるのかという試乗運転をしたということも聞いておりまして、それでは問題はなかったということですので、ぜひ前向きに進めていただきたいと思いますが、最後に伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"もともとコミュニティバスにつきましては、鉄道あるいは民間の路線バスを補完するというところで検討を開始していますので、そうした意味で、バス停からあるいは駅から遠い地域について、いかに地域の足を補完する、足を生んでいくかですので、そうしたところでは。","voiceIndex":215,"id":"exchange-079"},{"speaker":"石田（秀）委員","kind":"提案","question":"だから、今、話があったように、地域の方は、試運転ではないけれども、試乗したというか、そのときは警察の方もいたと聞いたのだけれども、そこはどう捉えているのですか。だけれども、それはあれだけの道幅だから、曲がるときはオーバーしてしまうことはあったけれども、それはそれで回って来られないことはなかったと聞いたのだけれども、そこら辺のところはどう捉えていらっしゃるのでしょうか。","respondent":"鈴木都市計画課長","answer":"そこには警察の方には乗っていただいていない状況で、まず職員が本当に曲がれないところ、何回も切り返さないとできないところはないかどうか確認したいというところで。","voiceIndex":218,"id":"exchange-080"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"地域の方から伺っていて、地域の方はあれで大変期待感を持ったみたいであります。この結論は後でしっかりと言いますが、ぜひそれでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":220,"id":"exchange-081"},{"speaker":"田中委員","kind":"質問","question":"やはりいろいろな方の声を聞くということが足りなかったのではないかと思いますし、これからでも意見を聞く場というのを設けてほしいと思うのですが、その辺りについて伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"ただ、一方では、今ご紹介いただいたように、参加したかったのだけれども、おそらくそれは町会の方も役員の方も人数の制限を、こちらからコロナの密の関係で制限をさせていただいたものもあって参加いただけなかったので、ただ、そうした声は、事前に参加する前に。","voiceIndex":222,"id":"exchange-082"},{"speaker":"田中委員","kind":"質問・要望","question":"今後は地域の声を聞いていくということでしたので、本当に広く、そして、各地域の状況が分かるような聞き方とか、周知の仕方をしてほしいと要望いたします。そして、荏原ルートに関してなのですけれども、やはり地域の方から……。〔「何で荏原ルートなんだ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":224,"id":"exchange-083"},{"speaker":"田中委員","kind":"意見","question":"主なご意見の中で荏原ルートのことが書かれていたのですけれども、参加できなかった方たちからのご意見の中で、荏原地域に障害者施設がないので、荏原ルートが心身障害者福祉会館を経由していればよかったなど、様々な声があったのです。きちんと声が届く形で、このように反映されるようにしてほしいと思うのですけれども、今後の地域の声の聞き方をもう少し具体的にお知らせいただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":225,"id":"exchange-084"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"本日結論を出してください。結論としては、不採択。これまでもずっとコミュニティバスの件につきましては何度もお話をさせていただいているけれども、地域の皆様のお気持ちは分かるけれども、個々のそういうご要望については、議会でそれをどのようにするということは、私どもがするべきではないと思っておりまして、陳情については不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":229,"id":"exchange-085"},{"speaker":"若林委員","kind":"質問","question":"本日結論を出すで、不採択でお願いします。そういう声を地域からお聞きしているので、ぜひ前向きに、最後は警察、そして、せっかく通っても交通事故が恒常的に起きるような、そういうルートとはしないということも含めて、区民が広く、大井地域の方が喜ぶルートを、皆さんの声をもとに実現していただければということでお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":231,"id":"exchange-086"},{"speaker":"のだて委員","kind":"意見","question":"この西大井地域は坂道が多かったり、あと、高齢者が多く、移動の保障をしていくという意味でも、コミュニティバスは力を発揮すると思いますし、やはりそうした地域の声を議会として受け止めていくということが必要だと思いますので、本日結論を出すということで、採択を主張します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":232,"id":"exchange-087"},{"speaker":"田中委員","kind":"質問・要望","question":"本日結論を出すで、趣旨採択を主張します。特定の地域の運行に関わることなので、これまでどおり生活者ネットワークとして、趣旨採択とします。区民、地域の方たちの話を今後も聞いていくということだったのですけれども、本当にきちんと聞いてほしい、限定せずに広く聞いていただきたいと強く要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":233,"id":"exchange-088"},{"speaker":"西本委員","kind":"質問・要望","question":"本日結論を出していただきたいと思います。不採択でお願いします。参加者の集め方もいろいろあるかもしれませんけれども、でも、ご意見を聞きますと、いろいろと平等性のある様々なご意見をいただいているのだと私は受け止めましたので、安心もいたしましたし、このまま進めていただいて、結果を出していただければと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":234,"id":"exchange-089"},{"speaker":"のだて委員","kind":"意見","question":"共産党としては、これは区民の声を受け止めて採択をしたいと思いますけれども、区民の声を受け止める議員が多くなるということも大事だと思いますので、態度をそろえるということもやぶさかではありません。趣旨採択ということで。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":237,"id":"exchange-090"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4304#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":68192,"voices":241}}]);
